}

func (app *App) locationPayloadC(id string) map[string]interface{} {
	var name string
	var lat, lng, cov float64
	var handle int
	var active, fnC, fnT, fnH, fnL bool
	var cap, res, ccap, cres int
	err := app.store.pg.QueryRow(bg(), `
SELECT name, latitude, longitude, coverage_km, handling_minutes, active,
  fn_collection, fn_transfer, fn_hub, fn_laboratory,
  capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
FROM locations WHERE id=$1`, id).Scan(&name, &lat, &lng, &cov, &handle, &active, &fnC, &fnT, &fnH, &fnL, &cap, &res, &ccap, &cres)
	if err != nil {
		return map[string]interface{}{"locationId": id}
	}
	capO := Capacity{CapacityUnits: cap, ReservedUnits: res, CooledCapacityUnits: ccap, CooledReservedUnits: cres}.fillAvail()
	return map[string]interface{}{
		"locationId":      id,
		"name":            name,
		"coordinates":     Coord{lat, lng},
		"functions":       LocationFunctions{fnC, fnT, fnH, fnL},
		"coverageKm":      cov,
		"handlingMinutes": handle,
		"active":          active,
		"capacity":        capO,
	}
}

func bg() interface {
	Deadline() (time.Time, bool)
	Done() <-chan struct{}
	Err() error
	Value(any) any
} {
	return contextBG()
}

