		app.emit("sample.created", "sample", sampleID, map[string]interface{}{"presealed": true})
		out := map[string]interface{}{
			"requestId": reqID, "sampleId": sampleID, "serviceability": svc, "reason": reason,
		}
		if journeyID != "" {
			out["journeyId"] = journeyID
		}
		if len(assignmentIDs) > 0 {
			out["assignmentIds"] = assignmentIDs
		}
		return 201, out, nil
	})
