func (app *App) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleRequester && !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		Origin          Coord  `json:"origin"`
		OriginType      string `json:"originType"`
		OriginNodeID    string `json:"originNodeId"`
		RequestedAt     string `json:"requestedAt"`
		DeliveryDeadline string `json:"deliveryDeadline"`
		CollectionWindow struct {
			Earliest string `json:"earliest"`
			Latest   string `json:"latest"`
		} `json:"collectionWindow"`
		SampleTypeID string `json:"sampleTypeId"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	requestedAt, err := parseTime(req.RequestedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid requestedAt")
		return
	}
	deadline, err := parseTime(req.DeliveryDeadline)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid deliveryDeadline")
		return
	}
	earliest, err := parseTime(req.CollectionWindow.Earliest)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid collection window")
		return
	}
	latest, err := parseTime(req.CollectionWindow.Latest)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid collection window")
		return
	}
	plan, err := app.checkServiceability(r.Context(), req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, requestedAt, deadline, earliest, latest)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	status := "unserviceable"
	if plan.Serviceable {
		status = "serviceable"
	}
	reason := plan.Reason
	if plan.Serviceable {
		reason = "serviceable"
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "serviceability.check", "sampleType", req.SampleTypeID, true, map[string]interface{}{"status": status, "reason": reason})
