package main

import (
	"net/http"
	"time"
)

func (app *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	scope := r.URL.Query().Get("scope")
	if scope == "" {
		scope = "current"
	}
	if scope != "current" && scope != "past" {
		writeErr(w, 400, "invalid_scope", "invalid scope")
		return
	}
	items := []map[string]interface{}{}
	switch u.ActiveRole {
	case RoleRequester:
		items = app.listRequesterWork(u, scope)
	case RoleCollectionProfessional, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam:
		items = app.listWorkerWork(u, scope)
	case RoleDispatcher, RoleAdministrator:
		items = app.listDispatcherWork(u, scope)
	}
	if items == nil {
		items = []map[string]interface{}{}
	}
	writeData(w, 200, map[string]interface{}{
		"role":  u.ActiveRole,
		"scope": scope,
		"items": items,
	})
}

func (app *App) listRequesterWork(u *SessionUser, scope string) []map[string]interface{} {
	q := `SELECT id, request_id, status, sample_type_id, delivery_deadline FROM samples WHERE requester_id=$1`
	if scope == "past" {
		q += ` AND status IN ('received','cancelled')`
	} else {
		q += ` AND status NOT IN ('received','cancelled')`
	}
	q += ` ORDER BY requested_at DESC`
	rows, err := app.store.pg.Query(contextBG(), q, u.UserID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var sid, rid, status, stid string
		var dl time.Time
		if err := rows.Scan(&sid, &rid, &status, &stid, &dl); err != nil {
			continue
		}
		out = append(out, map[string]interface{}{
			"kind":             "request",
			"sampleId":         sid,
			"requestId":        rid,
			"status":           status,
			"sampleTypeId":     stid,
			"deliveryDeadline": dl.UTC().Format(time.RFC3339Nano),
		})
	}
	return out
}

func (app *App) listWorkerWork(u *SessionUser, scope string) []map[string]interface{} {
	q := `
SELECT id, journey_id, sample_id, kind, status, from_location_id, to_location_id, node_id, laboratory_id, offer_expires_at
FROM assignments
WHERE (worker_id=$1 OR offered_to=$1)`
	if scope == "past" {
		q += ` AND status IN ('completed','cancelled','declined')`
	} else {
		q += ` AND status IN ('offered','accepted','in_progress','handoff_pending')`
	}
	q += ` ORDER BY created_at DESC`
	rows, err := app.store.pg.Query(contextBG(), q, u.UserID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var id, jid, kind, status string
		var sid, from, to, node, lab *string
		var exp *time.Time
		if err := rows.Scan(&id, &jid, &sid, &kind, &status, &from, &to, &node, &lab, &exp); err != nil {
			continue
		}
		item := map[string]interface{}{
			"kind":         "assignment",
			"assignmentId": id,
			"journeyId":    jid,
			"assignmentKind": kind,
			"status":       status,
		}
		if sid != nil {
			item["sampleId"] = *sid
		}
		if from != nil {
			item["fromLocationId"] = *from
		}
		if to != nil {
			item["toLocationId"] = *to
		}
		if node != nil {
			item["nodeId"] = *node
		}
		if lab != nil {
			item["laboratoryId"] = *lab
		}
		if exp != nil {
			item["offerExpiresAt"] = exp.UTC().Format(time.RFC3339Nano)
		}
		out = append(out, item)
	}
	return out
}

func (app *App) listDispatcherWork(u *SessionUser, scope string) []map[string]interface{} {
	q := `SELECT id, request_id, status, sample_type_id, delivery_deadline FROM samples`
	if scope == "past" {
		q += ` WHERE status IN ('received','cancelled')`
	} else {
		q += ` WHERE status NOT IN ('received','cancelled')`
	}
	q += ` ORDER BY requested_at DESC LIMIT 200`
	rows, err := app.store.pg.Query(contextBG(), q)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var sid, rid, status, stid string
		var dl time.Time
		if err := rows.Scan(&sid, &rid, &status, &stid, &dl); err != nil {
			continue
		}
		out = append(out, map[string]interface{}{
			"kind": "sample", "sampleId": sid, "requestId": rid, "status": status,
			"sampleTypeId": stid, "deliveryDeadline": dl.UTC().Format(time.RFC3339Nano),
		})
	}
	return out
}

func (app *App) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	var req struct {
		AssignmentID string `json:"assignmentId"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var offered *string
	var status, kind string
	err := app.store.pg.QueryRow(r.Context(), `SELECT offered_to, status, kind FROM assignments WHERE id=$1`, req.AssignmentID).
		Scan(&offered, &status, &kind)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if status != "offered" {
		writeErr(w, 409, "invalid_state", "assignment is not offered")
		return
	}
	if offered == nil || *offered != u.UserID {
		writeErr(w, 403, "not_offered_to_you", "assignment was not offered to you")
		return
	}
	_, err = app.store.pg.Exec(r.Context(), `
UPDATE assignments SET status='accepted', worker_id=$2, accepted_at=NOW() WHERE id=$1`, req.AssignmentID, u.UserID)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET last_assigned_at=NOW() WHERE id=$1`, u.UserID)
	app.audit(r.Context(), u.UserID, u.ActiveRole, "assignment.accept", "assignment", req.AssignmentID, true, nil)
	app.emit("assignment.accepted", "assignment", req.AssignmentID, map[string]interface{}{"workerId": u.UserID})
	writeData(w, 200, map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"status":       "accepted",
		"workerId":     u.UserID,
	})
}

func (app *App) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	var req struct {
		AssignmentID string `json:"assignmentId"`
		Reason       string `json:"reason"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var offered *string
	var status string
	err := app.store.pg.QueryRow(r.Context(), `SELECT offered_to, status FROM assignments WHERE id=$1`, req.AssignmentID).
		Scan(&offered, &status)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if status != "offered" {
		writeErr(w, 409, "invalid_state", "assignment is not offered")
		return
	}
	if offered == nil || *offered != u.UserID {
		writeErr(w, 403, "not_offered_to_you", "assignment was not offered to you")
		return
	}
	_, err = app.store.pg.Exec(r.Context(), `
UPDATE assignments SET status='declined', declined_by=$2, declined_at=NOW() WHERE id=$1`, req.AssignmentID, u.UserID)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	var dc int
	_ = app.store.pg.QueryRow(r.Context(), `SELECT decline_count FROM users WHERE id=$1`, u.UserID).Scan(&dc)
	dc++
	var until interface{}
	if dc >= 3 {
		until = time.Now().Add(declinePenalty)
		dc = 0
	}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET decline_count=$2, decline_penalty_until=$3 WHERE id=$1`, u.UserID, dc, until)
	app.audit(r.Context(), u.UserID, u.ActiveRole, "assignment.decline", "assignment", req.AssignmentID, true, map[string]interface{}{"reason": req.Reason})
	app.reoffer(r.Context(), req.AssignmentID)
	writeData(w, 200, map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"status":       "declined",
	})
}

func (app *App) handleRecordCollection(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleCollectionProfessional && u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		CollectedAt  string `json:"collectedAt"`
		Latitude     float64 `json:"latitude"`
		Longitude    float64 `json:"longitude"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var worker, sampleID *string
	var status, kind string
	var earliest, latest time.Time
	err := app.store.pg.QueryRow(r.Context(), `
SELECT a.worker_id, a.status, a.kind, a.sample_id, s.earliest_collection_at, s.latest_collection_at
FROM assignments a JOIN samples s ON s.id=a.sample_id WHERE a.id=$1`, req.AssignmentID).
		Scan(&worker, &status, &kind, &sampleID, &earliest, &latest)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if kind != "collection" {
		writeErr(w, 409, "invalid_assignment_kind", "not a collection assignment")
		return
	}
	if status != "accepted" && status != "in_progress" {
		writeErr(w, 409, "invalid_state", "assignment not accepted")
		return
	}
	if worker == nil || *worker != u.UserID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	collectedAt, err := parseTime(req.CollectedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid collectedAt")
		return
	}
	if collectedAt.Before(earliest) || collectedAt.After(latest) {
		writeErr(w, 409, "outside_collection_window", "collection outside window")
		return
	}
	// qualification check
	var stID string
	_ = app.store.pg.QueryRow(r.Context(), `SELECT sample_type_id FROM samples WHERE id=$1`, *sampleID).Scan(&stID)
	st, _ := app.loadSampleType(r.Context(), stID)
	if st != nil && st.QualifiedRequired && !contains(u.Qualifications, st.RequiredQualification) && !hasActiveCert(u.Certifications, st.RequiredQualification) {
		writeErr(w, 403, "missing_qualification", "missing qualification")
		return
	}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='in_progress' WHERE id=$1`, req.AssignmentID)
	_, _ = app.store.pg.Exec(r.Context(), `
UPDATE samples SET status='collected', latest_lat=$2, latest_lng=$3, location_recorded_at=$4, current_holder_id=$5
WHERE id=$1`, *sampleID, req.Latitude, req.Longitude, collectedAt, u.UserID)
	app.audit(r.Context(), u.UserID, u.ActiveRole, "sample.collect", "sample", *sampleID, true, nil)
	app.emit("sample.collected", "sample", *sampleID, map[string]interface{}{"assignmentId": req.AssignmentID})
	writeData(w, 200, map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"sampleId":     *sampleID,
		"status":       "collected",
		"collectedAt":  collectedAt.UTC().Format(time.RFC3339Nano),
	})
}

func contains(xs []string, v string) bool {
	for _, x := range xs {
		if x == v {
			return true
		}
	}
	return false
}

func hasActiveCert(cs []Certification, code string) bool {
	now := time.Now()
	for _, c := range cs {
		if c.Code == code && c.Active && (c.ExpiresAt == nil || c.ExpiresAt.After(now)) {
			return true
		}
	}
	return false
}

func (app *App) handleRecordSeal(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleCollectionProfessional && u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		SealedAt     string `json:"sealedAt"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var worker, sampleID *string
	var status, kind string
	err := app.store.pg.QueryRow(r.Context(), `SELECT worker_id, status, kind, sample_id FROM assignments WHERE id=$1`, req.AssignmentID).
		Scan(&worker, &status, &kind, &sampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if worker == nil || *worker != u.UserID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	var sampStatus string
	_ = app.store.pg.QueryRow(r.Context(), `SELECT status FROM samples WHERE id=$1`, *sampleID).Scan(&sampStatus)
	if sampStatus != "collected" && sampStatus != "sealed" {
		writeErr(w, 409, "invalid_state", "sample not collected")
		return
	}
	sealedAt, err := parseTime(req.SealedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid sealedAt")
		return
	}
	_, _ = app.store.pg.Exec(r.Context(), `
UPDATE samples SET status='sealed', sealed=TRUE, sealed_at=$2 WHERE id=$1`, *sampleID, sealedAt)
	app.audit(r.Context(), u.UserID, u.ActiveRole, "sample.seal", "sample", *sampleID, true, nil)
	app.emit("sample.sealed", "sample", *sampleID, map[string]interface{}{"assignmentId": req.AssignmentID})
	writeData(w, 200, map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"sampleId":     *sampleID,
		"status":       "sealed",
		"sealedAt":     sealedAt.UTC().Format(time.RFC3339Nano),
	})
}

func (app *App) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	var req struct {
		AssignmentID string  `json:"assignmentId"`
		Latitude     float64 `json:"latitude"`
		Longitude    float64 `json:"longitude"`
		Sequence     int     `json:"sequence"`
		RecordedAt   string  `json:"recordedAt"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var worker, sampleID *string
	var status string
	err := app.store.pg.QueryRow(r.Context(), `SELECT worker_id, status, sample_id FROM assignments WHERE id=$1`, req.AssignmentID).
		Scan(&worker, &status, &sampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if worker == nil || *worker != u.UserID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	at, err := parseTime(req.RecordedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid recordedAt")
		return
	}
	id := newUUID()
	_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO worker_location_updates (id, worker_id, assignment_id, latitude, longitude, sequence, recorded_at)
VALUES ($1,$2,$3,$4,$5,$6,$7)
ON CONFLICT (assignment_id, sequence) DO NOTHING`,
		id, u.UserID, req.AssignmentID, req.Latitude, req.Longitude, req.Sequence, at)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1`,
		u.UserID, req.Latitude, req.Longitude, at)
	if sampleID != nil {
		var holder *string
		_ = app.store.pg.QueryRow(r.Context(), `SELECT current_holder_id FROM samples WHERE id=$1`, *sampleID).Scan(&holder)
		if holder != nil && *holder == u.UserID {
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1`,
				*sampleID, req.Latitude, req.Longitude, at)
		}
	}
	app.emit("location.update", "assignment", req.AssignmentID, map[string]interface{}{"latitude": req.Latitude, "longitude": req.Longitude})
	writeData(w, 200, map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"sequence":     req.Sequence,
		"recordedAt":   at.UTC().Format(time.RFC3339Nano),
	})
}

func (app *App) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	var req struct {
		SampleID              string  `json:"sampleId"`
		AssignmentID          string  `json:"assignmentId"`
		LocationID            string  `json:"locationId"`
		ContainerType         string  `json:"containerType"`
		ObservedTemperatureC  float64 `json:"observedTemperatureC"`
		RecordedAt            string  `json:"recordedAt"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var holder *string
	var tmin, tmax float64
	var reqContainer, status string
	err := app.store.pg.QueryRow(r.Context(), `
SELECT current_holder_id, temperature_min_c, temperature_max_c, container_type, status FROM samples WHERE id=$1`, req.SampleID).
		Scan(&holder, &tmin, &tmax, &reqContainer, &status)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if holder == nil || *holder != u.UserID {
		writeErr(w, 403, "not_current_holder", "not current holder")
		return
	}
	at, err := parseTime(req.RecordedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid recordedAt")
		return
	}
	compliant := req.ObservedTemperatureC >= tmin && req.ObservedTemperatureC <= tmax
	if req.ContainerType != "" && reqContainer != "" && req.ContainerType != reqContainer {
		compliant = false
	}
	id := newUUID()
	var loc interface{}
	if req.LocationID != "" {
		loc = req.LocationID
	}
	_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, recorded_at, compliant)
VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
		id, req.SampleID, req.AssignmentID, loc, req.ContainerType, req.ObservedTemperatureC, at, compliant)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	if !compliant {
		exc := map[string]interface{}{
			"reason": "handling_violation", "containerType": req.ContainerType,
			"observedTemperatureC": req.ObservedTemperatureC, "checkpointId": id,
		}
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`, req.SampleID, asJSON(exc))
		app.audit(r.Context(), u.UserID, u.ActiveRole, "sample.handling_exception", "sample", req.SampleID, true, exc)
		app.emit("sample.exception", "sample", req.SampleID, exc)
	} else {
		app.audit(r.Context(), u.UserID, u.ActiveRole, "sample.checkpoint", "sample", req.SampleID, true, map[string]interface{}{"checkpointId": id})
	}
	writeData(w, 200, map[string]interface{}{
		"checkpointId": id,
		"sampleId":     req.SampleID,
		"compliant":    compliant,
		"recordedAt":   at.UTC().Format(time.RFC3339Nano),
	})
}

func (app *App) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	var req struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var holder *string
	var sealed bool
	var status string
	err := app.store.pg.QueryRow(r.Context(), `SELECT current_holder_id, sealed, status FROM samples WHERE id=$1`, req.SampleID).
		Scan(&holder, &sealed, &status)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if !sealed {
		writeErr(w, 409, "not_sealed", "sample not sealed")
		return
	}
	if holder == nil || *holder != u.UserID {
		writeErr(w, 403, "not_current_holder", "not current holder")
		return
	}
	// existing pending handoff?
	var existing string
	_ = app.store.pg.QueryRow(r.Context(), `
SELECT id FROM handoffs WHERE sample_id=$1 AND status='pending' LIMIT 1`, req.SampleID).Scan(&existing)
	if existing != "" {
		writeData(w, 200, map[string]interface{}{"handoffId": existing, "status": "pending"})
		return
	}
	id := newUUID()
	now := time.Now().UTC()
	_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, sender_confirmed, initiated_at)
VALUES ($1,$2,$3,$4,$5,$6,'pending',TRUE,$7)`,
		id, req.SampleID, req.FromAssignmentID, req.ToAssignmentID, u.UserID, req.ReceiverID, now)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='handoff_pending' WHERE id=$1`, req.FromAssignmentID)
	app.audit(r.Context(), u.UserID, u.ActiveRole, "handoff.initiate", "handoff", id, true, map[string]interface{}{"sampleId": req.SampleID})
	app.emit("handoff.initiated", "handoff", id, map[string]interface{}{"sampleId": req.SampleID})
