func (app *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	var req struct {
		HandoffID string `json:"handoffId"`
		Role      string `json:"role"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var sampleID, sender, receiver, status, fromA, toA string
	var sConf, rConf bool
	err := app.store.pg.QueryRow(r.Context(), `
SELECT sample_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed, from_assignment_id, to_assignment_id
FROM handoffs WHERE id=$1`, req.HandoffID).Scan(&sampleID, &sender, &receiver, &status, &sConf, &rConf, &fromA, &toA)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if status == "completed" {
		writeData(w, 200, map[string]interface{}{"handoffId": req.HandoffID, "status": "completed", "sampleId": sampleID})
		return
	}
	if req.Role == "sender" {
		if u.UserID != sender {
			writeErr(w, 403, "forbidden", "not the sender")
			return
		}
		sConf = true
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=TRUE WHERE id=$1`, req.HandoffID)
	} else if req.Role == "receiver" {
		if u.UserID != receiver {
			writeErr(w, 403, "forbidden", "not the receiver")
			return
		}
		rConf = true
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET receiver_confirmed=TRUE WHERE id=$1`, req.HandoffID)
	} else {
		writeErr(w, 400, "invalid_role", "role must be sender or receiver")
		return
	}
	outStatus := "pending"
	if sConf && rConf {
		now := time.Now().UTC()
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET status='completed', completed_at=$2 WHERE id=$1`, req.HandoffID, now)
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET current_holder_id=$2, status='in_transit' WHERE id=$1 AND status NOT IN ('received','cancelled')`, sampleID, receiver)
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='completed', completed_at=$2 WHERE id=$1`, fromA, now)
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='in_progress' WHERE id=$1 AND status IN ('accepted','offered')`, toA)
		outStatus = "completed"
		app.audit(r.Context(), u.UserID, u.ActiveRole, "handoff.complete", "handoff", req.HandoffID, true, map[string]interface{}{"sampleId": sampleID, "newHolder": receiver})
		app.emit("handoff.completed", "handoff", req.HandoffID, map[string]interface{}{"sampleId": sampleID, "holderId": receiver})
	} else {
		app.audit(r.Context(), u.UserID, u.ActiveRole, "handoff.confirm", "handoff", req.HandoffID, true, map[string]interface{}{"role": req.Role})
	}
	writeData(w, 200, map[string]interface{}{
		"handoffId": req.HandoffID,
		"status":    outStatus,
		"sampleId":  sampleID,
	})
}

func (app *App) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u.ActiveRole != RoleLaboratoryTeam && u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		SampleID     string `json:"sampleId"`
		ReceivedAt   string `json:"receivedAt"`
	}
	if err := decodeStrict(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	var worker, labID, sampleID *string
	var status, kind string
	err := app.store.pg.QueryRow(r.Context(), `SELECT worker_id, status, kind, laboratory_id, sample_id FROM assignments WHERE id=$1`, req.AssignmentID).
		Scan(&worker, &status, &kind, &labID, &sampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if kind != "laboratory" {
		writeErr(w, 409, "invalid_assignment_kind", "not a laboratory assignment")
		return
	}
	if worker == nil || *worker != u.UserID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	if sampleID != nil && req.SampleID != "" && *sampleID != req.SampleID {
		writeErr(w, 400, "sample_mismatch", "sample mismatch")
		return
	}
	sid := req.SampleID
	if sid == "" && sampleID != nil {
		sid = *sampleID
	}
	at, err := parseTime(req.ReceivedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid receivedAt")
		return
	}
	var deadline time.Time
	_ = app.store.pg.QueryRow(r.Context(), `SELECT delivery_deadline FROM samples WHERE id=$1`, sid).Scan(&deadline)
	newStatus := "received"
	if at.After(deadline) {
		exc := map[string]interface{}{"reason": "missed_deadline", "receivedAt": at.UTC().Format(time.RFC3339Nano)}
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='exception', exception=$2, received_laboratory_id=$3 WHERE id=$1`, sid, asJSON(exc), labID)
		newStatus = "exception"
	} else {
		_, _ = app.store.pg.Exec(r.Context(), `
UPDATE samples SET status='received', received_laboratory_id=$2, current_holder_id=$3 WHERE id=$1`, sid, labID, u.UserID)
	}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='completed', completed_at=$2 WHERE id=$1`, req.AssignmentID, at)
	if jid := ""; true {
		_ = app.store.pg.QueryRow(r.Context(), `SELECT active_journey_id FROM samples WHERE id=$1`, sid).Scan(&jid)
		if jid != "" {
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE id=$1`, jid)
			_ = app.releaseJourneyCapacity(r.Context(), jid)
		}
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "sample.receive", "sample", sid, true, map[string]interface{}{"status": newStatus})
	app.emit("sample.received", "sample", sid, map[string]interface{}{"status": newStatus})
	writeData(w, 200, map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"sampleId":     sid,
		"status":       newStatus,
		"receivedAt":   at.UTC().Format(time.RFC3339Nano),
	})
}

