func (app *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	scope := r.URL.Query().Get("scope")
	if scope == "" {
		scope = "current"
	}
	if scope != "current" && scope != "past" {
		writeErr(w, 400, "invalid_scope", "invalid scope")
		return
	}
	items := []map[string]interface{}{}
	switch u.ActiveRole {
	case RoleRequester:
		items = app.listRequesterWork(u, scope)
	case RoleCollectionProfessional, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam:
		items = app.listWorkerWork(u, scope)
	case RoleDispatcher, RoleAdministrator:
		items = app.listDispatcherWork(u, scope)
	}
	if items == nil {
