}

func (app *App) loadSampleType(ctx context.Context, id string) (*sampleTypeRow, error) {
	var s sampleTypeRow
	err := app.store.pg.QueryRow(ctx, `
SELECT id, name, qualified_collector_required, COALESCE(required_qualification,''),
  container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
  requires_cooled_route, batching_allowed
FROM sample_types WHERE id=$1`, id).Scan(
		&s.ID, &s.Name, &s.QualifiedCollector, &s.RequiredQualification,
		&s.ContainerType, &s.TempMin, &s.TempMax, &s.Incompatible,
		&s.RequiresCooled, &s.BatchingAllowed)
