package main

import (
	"context"
	"encoding/json"
	"time"
)

func emptyStrs() []string { return []string{} }

func (app *App) locationPayload(ctx context.Context, id string) (map[string]interface{}, error) {
	var name string
	var lat, lng, cov float64
	var handling int
	var active, fnC, fnT, fnH, fnL bool
	err := app.store.pg.QueryRow(ctx, `
SELECT name, latitude, longitude, coverage_km, handling_minutes, active,
  fn_collection, fn_transfer, fn_hub, fn_laboratory
FROM locations WHERE id=$1`, id).Scan(&name, &lat, &lng, &cov, &handling, &active, &fnC, &fnT, &fnH, &fnL)
	if err != nil {
		return nil, herr(404, "not_found", "location not found")
	}
	if cov <= 0 {
		cov = 5
	}
	return map[string]interface{}{
		"locationId":      id,
		"name":            name,
		"coordinate":      map[string]interface{}{"latitude": lat, "longitude": lng},
		"coverageKm":      cov,
		"handlingMinutes": handling,
		"active":          active,
		"functions": LocationFunctions{
			CollectionPoint: fnC, TransferPoint: fnT, Hub: fnH, Laboratory: fnL,
		},
	}, nil
}

func (app *App) sampleTypePayload(ctx context.Context, id string) (map[string]interface{}, error) {
	st, err := app.loadSampleType(ctx, id)
	if err != nil {
		return nil, err
	}
	return map[string]interface{}{
		"sampleTypeId":               st.ID,
		"name":                       st.Name,
		"qualifiedCollectorRequired": st.QualifiedCollector,
		"requiredQualification":      st.RequiredQualification,
		"containerType":              st.ContainerType,
		"temperatureMinC":            st.TempMin,
		"temperatureMaxC":            st.TempMax,
		"incompatibleSampleTypes":    st.Incompatible,
		"requiresCooledRoute":        st.RequiresCooled,
		"batchingAllowed":            st.BatchingAllowed,
	}, nil
}

func (app *App) userPayload(ctx context.Context, id string) (map[string]interface{}, error) {
	u, err := app.loadUser(ctx, id, "")
	if err != nil {
		return nil, herr(404, "not_found", "user not found")
	}
	out := map[string]interface{}{
		"userId":         u.UserID,
		"username":       u.Username,
		"roles":          u.Roles,
		"qualifications": u.Qualifications,
		"certifications": u.Certifications,
		"active":         u.Active,
	}
	if u.Email != "" {
		out["email"] = u.Email
	}
	if u.FullName != "" {
		out["fullName"] = u.FullName
	}
	if u.Phone != "" {
		out["phone"] = u.Phone
	}
	return out, nil
}

type sampleRow struct {
	ID, RequestID, RequesterID, SampleTypeID, Status string
	Sealed                                           bool
	SealedAt                                         *time.Time
	CurrentHolderID                                  *string
	Serviceability, ServiceabilityReason             string
	ActiveJourneyID, TargetLabID, ReceivedLabID      *string
	ContainerType                                    string
	TempMin, TempMax                                 float64
	Incompatible                                     []string
	OriginLat, OriginLng                             float64
	OriginType                                       string
	RequestedAt, Deadline, Earliest, Latest          time.Time
	LatestLat, LatestLng                             *float64
	LocationRecordedAt                               *time.Time
	Exception                                        []byte
}

func (app *App) loadSample(ctx context.Context, id string) (*sampleRow, error) {
	var s sampleRow
	err := app.store.pg.QueryRow(ctx, `
SELECT id, request_id, requester_id, sample_type_id, status, sealed, sealed_at, current_holder_id,
  serviceability, serviceability_reason, active_journey_id, target_laboratory_id, received_laboratory_id,
  container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
  origin_lat, origin_lng, origin_type, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
  latest_lat, latest_lng, location_recorded_at, exception
FROM samples WHERE id=$1`, id).Scan(
		&s.ID, &s.RequestID, &s.RequesterID, &s.SampleTypeID, &s.Status, &s.Sealed, &s.SealedAt, &s.CurrentHolderID,
		&s.Serviceability, &s.ServiceabilityReason, &s.ActiveJourneyID, &s.TargetLabID, &s.ReceivedLabID,
		&s.ContainerType, &s.TempMin, &s.TempMax, &s.Incompatible,
		&s.OriginLat, &s.OriginLng, &s.OriginType, &s.RequestedAt, &s.Deadline, &s.Earliest, &s.Latest,
		&s.LatestLat, &s.LatestLng, &s.LocationRecordedAt, &s.Exception)
	if err != nil {
		return nil, herr(404, "not_found", "sample not found")
	}
	if s.Incompatible == nil {
		s.Incompatible = []string{}
	}
	return &s, nil
}

func (app *App) activeAssignmentIDs(ctx context.Context, sampleID string) []string {
	rows, err := app.store.pg.Query(ctx, `
SELECT id FROM assignments
WHERE sample_id=$1 AND status NOT IN ('completed','cancelled','declined')
ORDER BY sequence, created_at`, sampleID)
	if err != nil {
		return []string{}
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err == nil {
			out = append(out, id)
		}
	}
	if out == nil {
		out = []string{}
	}
	return out
}

func (app *App) sampleStatePayload(ctx context.Context, s *sampleRow) map[string]interface{} {
	now := time.Now()
	ids := []string{s.ID, s.RequestID}
	if s.ActiveJourneyID != nil {
		ids = append(ids, *s.ActiveJourneyID)
	}
	tl := app.loadTimeline(ctx, ids...)
	if tl == nil {
		tl = []map[string]interface{}{}
	}
	stale := isStale(s.LocationRecordedAt, now)
	out := map[string]interface{}{
		"sampleId":                s.ID,
		"requestId":               s.RequestID,
		"requesterId":             s.RequesterID,
		"origin":                  map[string]interface{}{"latitude": s.OriginLat, "longitude": s.OriginLng},
		"originType":              s.OriginType,
		"requestedAt":             rfc3339(s.RequestedAt),
		"deliveryDeadline":        rfc3339(s.Deadline),
		"sampleTypeId":            s.SampleTypeID,
		"containerType":           s.ContainerType,
		"temperatureMinC":         s.TempMin,
		"temperatureMaxC":         s.TempMax,
		"incompatibleSampleTypes": s.Incompatible,
		"serviceability":          s.Serviceability,
		"activeAssignmentIds":     app.activeAssignmentIDs(ctx, s.ID),
		"state":                   map[string]interface{}{"status": s.Status},
		"timeline":                tl,
		"locationStale":           stale,
	}
	if s.ActiveJourneyID != nil {
		out["activeJourneyId"] = *s.ActiveJourneyID
	}
	if s.TargetLabID != nil {
		out["targetLaboratoryId"] = *s.TargetLabID
	}
	if s.LatestLat != nil && s.LatestLng != nil {
		out["latestLocation"] = map[string]interface{}{"latitude": *s.LatestLat, "longitude": *s.LatestLng}
	}
	if s.LocationRecordedAt != nil {
		out["locationRecordedAt"] = rfc3339(*s.LocationRecordedAt)
	}
	return out
}

func (app *App) sampleLifecyclePayload(ctx context.Context, s *sampleRow) map[string]interface{} {
	now := time.Now()
	ids := []string{s.ID}
	if s.ActiveJourneyID != nil {
		ids = append(ids, *s.ActiveJourneyID)
	}
	tl := app.loadTimeline(ctx, ids...)
	if tl == nil {
		tl = []map[string]interface{}{}
	}
	completed := []string{}
	rows, err := app.store.pg.Query(ctx, `SELECT id FROM assignments WHERE sample_id=$1 AND status='completed' ORDER BY sequence`, s.ID)
