		s.Incompatible = []string{}
	}
	return &s, nil
}

func (app *App) activeAssignmentIDs(ctx context.Context, sampleID string) []string {
	rows, err := app.store.pg.Query(ctx, `
SELECT id FROM assignments
WHERE sample_id=$1 AND status NOT IN ('completed','cancelled','declined')
ORDER BY sequence, created_at`, sampleID)
	if err != nil {
		return []string{}
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err == nil {
			out = append(out, id)
		}
	}
	if out == nil {
		out = []string{}
	}
	return out
}

func (app *App) sampleStatePayload(ctx context.Context, s *sampleRow) map[string]interface{} {
	now := time.Now()
	ids := []string{s.ID, s.RequestID}
	if s.ActiveJourneyID != nil {
		ids = append(ids, *s.ActiveJourneyID)
	}
	tl := app.loadTimeline(ctx, ids...)
	if tl == nil {
		tl = []map[string]interface{}{}
	}
	stale := isStale(s.LocationRecordedAt, now)
	out := map[string]interface{}{
		"sampleId":                s.ID,
		"requestId":               s.RequestID,
		"requesterId":             s.RequesterID,
		"origin":                  map[string]interface{}{"latitude": s.OriginLat, "longitude": s.OriginLng},
		"originType":              s.OriginType,
		"requestedAt":             rfc3339(s.RequestedAt),
		"deliveryDeadline":        rfc3339(s.Deadline),
		"sampleTypeId":            s.SampleTypeID,
		"containerType":           s.ContainerType,
		"temperatureMinC":         s.TempMin,
		"temperatureMaxC":         s.TempMax,
		"incompatibleSampleTypes": s.Incompatible,
		"serviceability":          s.Serviceability,
		"activeAssignmentIds":     app.activeAssignmentIDs(ctx, s.ID),
		"state":                   map[string]interface{}{"status": s.Status},
		"timeline":                tl,
		"locationStale":           stale,
	}
