package main

import (
	"context"
	"encoding/json"
	"net/http"
	"time"
)

func (app *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	_ = decodeBody(body, &req)
	if req.Role != "" && req.Role != u.ActiveRole && !u.isDispatcher() {
		writeErr(w, 400, "invalid_role", "role does not match active role")
		return
	}
	role := u.ActiveRole
	if req.Role != "" && u.isDispatcher() {
		role = req.Role
	}
	pending, inProg, completed := app.roleWork(r.Context(), u, role)
	if req.Status != "" {
		switch req.Status {
		case "pending":
			inProg, completed = []map[string]interface{}{}, []map[string]interface{}{}
		case "in_progress", "accepted", "inProgress":
			pending, completed = []map[string]interface{}{}, []map[string]interface{}{}
		case "completed", "past":
			pending, inProg = []map[string]interface{}{}, []map[string]interface{}{}
		}
	}
	writeData(w, 200, map[string]interface{}{
		"role":      role,
		"pending":   pending,
		"inProgress": inProg,
		"completed": completed,
	})
}

func (app *App) roleWork(ctx context.Context, u *SessionUser, role string) (pending, inProg, completed []map[string]interface{}) {
	pending, inProg, completed = []map[string]interface{}{}, []map[string]interface{}{}, []map[string]interface{}{}
	now := time.Now()
	if role == RoleRequester {
		rows, err := app.store.pg.Query(ctx, `SELECT id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, u.UserID)
		if err != nil {
			return
		}
		defer rows.Close()
		for rows.Next() {
			var id string
			if rows.Scan(&id) != nil {
				continue
			}
			s, err := app.loadSample(ctx, id)
			if err != nil {
				continue
			}
			item := app.sampleWorkItem(ctx, s, now)
			switch s.Status {
			case "received", "cancelled", "expired":
				completed = append(completed, item)
			case "requested":
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
		return
	}
	if role == RoleDispatcher || role == RoleAdministrator {
		rows, err := app.store.pg.Query(ctx, `SELECT id FROM samples ORDER BY created_at DESC LIMIT 300`)
		if err != nil {
			return
		}
		defer rows.Close()
		for rows.Next() {
			var id string
			if rows.Scan(&id) != nil {
				continue
			}
			s, err := app.loadSample(ctx, id)
			if err != nil {
				continue
			}
			item := app.sampleWorkItem(ctx, s, now)
			switch s.Status {
			case "received", "cancelled", "expired":
				completed = append(completed, item)
			case "requested":
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
		return
	}
	// worker assignments
	rows, err := app.store.pg.Query(ctx, `
SELECT id FROM assignments
WHERE worker_id=$1 OR offered_to=$1
ORDER BY created_at DESC`, u.UserID)
	if err != nil {
		return
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		if rows.Scan(&id) != nil {
			continue
		}
		item, status, ok := app.assignmentWorkItem(ctx, id)
		if !ok {
			continue
		}
		switch status {
		case "completed", "cancelled":
			completed = append(completed, item)
		case "accepted", "in_progress", "at_pickup", "picked_up", "in_transit", "arrived", "delivered":
			inProg = append(inProg, item)
		default:
			pending = append(pending, item)
		}
	}
	return
}

func (app *App) sampleWorkItem(ctx context.Context, s *sampleRow, now time.Time) map[string]interface{} {
	ids := []string{s.ID, s.RequestID}
	hist := app.loadTimeline(ctx, ids...)
	if hist == nil {
		hist = []map[string]interface{}{}
	}
	item := map[string]interface{}{
		"kind":          "sample",
		"sampleId":      s.ID,
		"sample_id":     s.ID,
		"requestId":     s.RequestID,
		"status":        s.Status,
		"serviceability": s.Serviceability,
		"requestedAt":   rfc3339(s.RequestedAt),
		"deliveryDeadline": rfc3339(s.Deadline),
		"earliestCollectionAt": rfc3339(s.Earliest),
		"latestCollectionAt": rfc3339(s.Latest),
		"requesterId":   s.RequesterID,
		"history":       hist,
		"locationStale": isStale(s.LocationRecordedAt, now),
	}
	if s.ActiveJourneyID != nil {
		item["journeyId"] = *s.ActiveJourneyID
		item["activeJourneyId"] = *s.ActiveJourneyID
	}
	if s.TargetLabID != nil {
		item["laboratoryId"] = *s.TargetLabID
	}
	if s.CurrentHolderID != nil {
		item["currentHolderId"] = *s.CurrentHolderID
	}
	if s.LocationRecordedAt != nil {
		item["locationRecordedAt"] = rfc3339(*s.LocationRecordedAt)
	}
	return item
}

func (app *App) assignmentWorkItem(ctx context.Context, id string) (map[string]interface{}, string, bool) {
	var kind, status string
	var sampleID, journeyID, from, to, node, lab, incoming, outgoing, expected *string
	var seq int
	var offerExp *time.Time
	err := app.store.pg.QueryRow(ctx, `
SELECT kind, status, sample_id, journey_id, from_location_id, to_location_id, sequence,
  offer_expires_at, node_id, laboratory_id, incoming_from_location_id, outgoing_to_location_id, expected_sample_type_id
FROM assignments WHERE id=$1`, id).Scan(&kind, &status, &sampleID, &journeyID, &from, &to, &seq, &offerExp, &node, &lab, &incoming, &outgoing, &expected)
	if err != nil {
		return nil, "", false
	}
	sid := ""
	if sampleID != nil {
		sid = *sampleID
	}
	hist := app.loadTimeline(ctx, id, sid)
	if hist == nil {
		hist = []map[string]interface{}{}
	}
	item := map[string]interface{}{
		"kind":         kind,
		"assignmentId": id,
		"assignment_id": id,
		"sampleId":     sid,
		"sample_id":    sid,
		"status":       status,
		"history":      hist,
	}
	if journeyID != nil {
		item["journeyId"] = *journeyID
	}
	if from != nil {
		item["fromLocationId"] = *from
	}
	if to != nil {
		item["toLocationId"] = *to
	}
	item["sequence"] = seq
	if offerExp != nil {
		item["offerExpiresAt"] = rfc3339(*offerExp)
	}
	if node != nil {
		item["nodeId"] = *node
	}
	if incoming != nil {
		item["incomingFromLocationId"] = *incoming
	}
	if outgoing != nil {
		item["outgoingToLocationId"] = *outgoing
	}
	if lab != nil {
		item["laboratoryId"] = *lab
	}
	if expected != nil {
		item["expectedSampleTypeId"] = *expected
	}
	return item, status, true
}

func (app *App) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			AssignmentID string `json:"assignmentId"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		var status string
		var offered, worker *string
		err := app.store.pg.QueryRow(r.Context(), `SELECT status, offered_to, worker_id FROM assignments WHERE id=$1`, req.AssignmentID).
			Scan(&status, &offered, &worker)
		if err != nil {
			return 0, nil, herr(404, "not_found", "assignment not found")
		}
		if worker != nil && *worker == u.UserID && (status == "accepted" || status == "in_progress") {
			return 201, map[string]interface{}{"assignmentId": req.AssignmentID, "workerId": u.UserID, "status": "accepted"}, nil
		}
		if offered == nil || *offered != u.UserID {
			if !u.isDispatcher() {
				return 0, nil, herr(409, "offer_not_available", "offer not available")
			}
		}
		if status != "offered" && status != "pending" && !u.isDispatcher() {
			return 0, nil, herr(409, "offer_not_available", "offer not available")
		}
		_, err = app.store.pg.Exec(r.Context(), `
UPDATE assignments SET status='accepted', worker_id=$2, accepted_at=now(), offered_to=NULL WHERE id=$1`, req.AssignmentID, u.UserID)
		if err != nil {
			return 0, nil, err
		}
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET last_assigned_at=now() WHERE id=$1`, u.UserID)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "accept_assignment", "assignment", req.AssignmentID, true, nil)
		app.emit("assignment.accepted", "assignment", req.AssignmentID, map[string]interface{}{"workerId": u.UserID})
		return 201, map[string]interface{}{
			"assignmentId": req.AssignmentID,
			"workerId":     u.UserID,
			"status":       "accepted",
		}, nil
	})
}

func (app *App) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			AssignmentID string `json:"assignmentId"`
			Reason       string `json:"reason"`
			DeclinedAt   string `json:"declinedAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		at := time.Now().UTC()
		if req.DeclinedAt != "" {
			t, err := parseTime(req.DeclinedAt)
			if err != nil {
				return 0, nil, herr(400, "invalid_time", "invalid declinedAt")
			}
			at = t
		}
		var status string
		var offered *string
		err := app.store.pg.QueryRow(r.Context(), `SELECT status, offered_to FROM assignments WHERE id=$1`, req.AssignmentID).
			Scan(&status, &offered)
		if err != nil {
			return 0, nil, herr(404, "not_found", "assignment not found")
		}
		if offered == nil || *offered != u.UserID {
			if !u.isDispatcher() {
				return 0, nil, herr(409, "offer_not_available", "offer not available")
			}
		}
		_, _ = app.store.pg.Exec(r.Context(), `
UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$2, declined_at=$3 WHERE id=$1`,
			req.AssignmentID, u.UserID, at)
		_, _ = app.store.pg.Exec(r.Context(), `
UPDATE users SET decline_count = decline_count + 1, decline_penalty_until=$2 WHERE id=$1`,
			u.UserID, time.Now().Add(declinePenalty))
		next := app.offerOne(r.Context(), req.AssignmentID)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "decline_assignment", "assignment", req.AssignmentID, true, map[string]interface{}{"reason": req.Reason})
		out := map[string]interface{}{
			"assignmentId": req.AssignmentID,
			"status":       "pending",
			"declinedBy":   u.UserID,
			"declinedAt":   rfc3339(at),
		}
		if next != "" {
			out["reofferedTo"] = next
		}
		return 201, out, nil
	})
}

func (app *App) handleUpdateProgress(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			AssignmentID string `json:"assignmentId"`
			Status       string `json:"status"`
			OccurredAt   string `json:"occurredAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		at, err := parseTime(req.OccurredAt)
		if err != nil {
			return 0, nil, herr(400, "invalid_time", "invalid occurredAt")
		}
		allowed := map[string]bool{"at_pickup": true, "picked_up": true, "in_transit": true, "arrived": true, "delivered": true, "in_progress": true, "completed": true}
		if !allowed[req.Status] {
			return 0, nil, herr(400, "invalid_json", "invalid status")
		}
		var sampleID *string
		var worker *string
		var status string
		err = app.store.pg.QueryRow(r.Context(), `SELECT sample_id, worker_id, status FROM assignments WHERE id=$1`, req.AssignmentID).
			Scan(&sampleID, &worker, &status)
		if err != nil {
			return 0, nil, herr(404, "not_found", "assignment not found")
		}
		if !u.isDispatcher() && (worker == nil || *worker != u.UserID) {
			return 0, nil, herr(403, "forbidden", "not assigned worker")
		}
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status=$2, completed_at=CASE WHEN $2 IN ('completed','delivered') THEN $3 ELSE completed_at END WHERE id=$1`,
			req.AssignmentID, req.Status, at)
		sid := ""
		if sampleID != nil {
			sid = *sampleID
			if req.Status == "picked_up" || req.Status == "in_transit" {
				_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='in_transit', current_holder_id=$2 WHERE id=$1`, sid, u.UserID)
			}
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "update_assignment_progress", "assignment", req.AssignmentID, true, map[string]interface{}{"status": req.Status})
		app.emit("assignment.progress", "assignment", req.AssignmentID, map[string]interface{}{"status": req.Status})
		return 201, map[string]interface{}{
			"assignmentId": req.AssignmentID,
			"sampleId":     sid,
			"status":       req.Status,
		}, nil
	})
}

func (app *App) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	var req struct {
		AssignmentID string `json:"assignmentId"`
		Coordinate   Coord  `json:"coordinate"`
		Sequence     int    `json:"sequence"`
		RecordedAt   string `json:"recordedAt"`
	}
	if err := decodeBody(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Sequence < 1 {
		writeErr(w, 400, "invalid_sequence", "invalid sequence")
		return
	}
	at, err := parseTime(req.RecordedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid recordedAt")
		return
	}
	var worker, sampleID *string
	err = app.store.pg.QueryRow(r.Context(), `SELECT worker_id, sample_id FROM assignments WHERE id=$1`, req.AssignmentID).Scan(&worker, &sampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	if !u.isDispatcher() && (worker == nil || *worker != u.UserID) {
		writeErr(w, 403, "forbidden", "not assigned worker")
		return
	}
	var maxSeq int
	_ = app.store.pg.QueryRow(r.Context(), `SELECT COALESCE(MAX(sequence),0) FROM worker_location_updates WHERE assignment_id=$1`, req.AssignmentID).Scan(&maxSeq)
	if req.Sequence <= maxSeq {
		writeErr(w, 409, "stale_location", "stale location sequence")
		return
	}
	_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO worker_location_updates (id, worker_id, assignment_id, latitude, longitude, sequence, recorded_at)
VALUES ($1,$2,$3,$4,$5,$6,$7)`, newUUID(), u.UserID, req.AssignmentID, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, at)
	if err != nil {
		writeErr(w, 409, "concurrent_conflict", "location conflict")
		return
	}
	_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1`,
		u.UserID, req.Coordinate.Latitude, req.Coordinate.Longitude, at)
	if sampleID != nil {
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1`,
			*sampleID, req.Coordinate.Latitude, req.Coordinate.Longitude, at)
	}
	app.audit(r.Context(), u.UserID, u.ActiveRole, "record_worker_location", "assignment", req.AssignmentID, true, map[string]interface{}{"sequence": req.Sequence})
	app.emit("worker.location", "assignment", req.AssignmentID, map[string]interface{}{"coordinate": req.Coordinate})
	writeData(w, 201, map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"coordinate":   req.Coordinate,
		"sequence":     req.Sequence,
		"recordedAt":   rfc3339(at),
	})
}

func (app *App) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			SampleID         string `json:"sampleId"`
			FromAssignmentID string `json:"fromAssignmentId"`
			ToAssignmentID   string `json:"toAssignmentId"`
			ReceiverID       string `json:"receiverId"`
			InitiatedAt      string `json:"initiatedAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		at, err := parseTime(req.InitiatedAt)
		if err != nil {
			return 0, nil, herr(400, "invalid_time", "invalid initiatedAt")
		}
		s, err := app.loadSample(r.Context(), req.SampleID)
		if err != nil {
			return 0, nil, err
		}
		if s.CurrentHolderID == nil || *s.CurrentHolderID != u.UserID {
			if !u.isDispatcher() {
				return 0, nil, herr(409, "not_current_holder", "not current holder")
			}
		}
		var pending string
		_ = app.store.pg.QueryRow(r.Context(), `SELECT id FROM handoffs WHERE sample_id=$1 AND status='pending' LIMIT 1`, s.ID).Scan(&pending)
		if pending != "" {
			return 0, nil, herr(409, "pending_handoff_exists", "pending handoff exists")
		}
		hid := newUUID()
		_, err = app.store.pg.Exec(r.Context(), `
INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at)
VALUES ($1,$2,$3,$4,$5,$6,'pending',$7)`, hid, s.ID, req.FromAssignmentID, req.ToAssignmentID, u.UserID, req.ReceiverID, at)
		if err != nil {
			return 0, nil, err
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "initiate_handoff", "handoff", hid, true, map[string]interface{}{"sampleId": s.ID})
		return 201, map[string]interface{}{
			"handoffId":       hid,
			"senderId":        u.UserID,
			"receiverId":      req.ReceiverID,
			"currentHolderId": ptrStr(s.CurrentHolderID),
			"status":          "pending",
		}, nil
	})
}

func (app *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			HandoffID         string `json:"handoffId"`
			ConfirmationSide  string `json:"confirmationSide"`
			ConfirmedAt       string `json:"confirmedAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
			return 0, nil, herr(400, "invalid_json", "invalid confirmationSide")
		}
		at, err := parseTime(req.ConfirmedAt)
		if err != nil {
			return 0, nil, herr(400, "invalid_time", "invalid confirmedAt")
		}
		var sampleID, sender, receiver, status string
		var sConf, rConf bool
		err = app.store.pg.QueryRow(r.Context(), `
SELECT sample_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed
FROM handoffs WHERE id=$1`, req.HandoffID).Scan(&sampleID, &sender, &receiver, &status, &sConf, &rConf)
		if err != nil {
			return 0, nil, herr(404, "not_found", "handoff not found")
		}
		if req.ConfirmationSide == "sender" {
			if !u.isDispatcher() && u.UserID != sender {
				return 0, nil, herr(403, "forbidden", "not sender")
			}
			sConf = true
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=TRUE WHERE id=$1`, req.HandoffID)
		} else {
			if !u.isDispatcher() && u.UserID != receiver {
				return 0, nil, herr(403, "forbidden", "not receiver")
			}
			rConf = true
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET receiver_confirmed=TRUE WHERE id=$1`, req.HandoffID)
		}
		holder := sender
		st := "pending"
		if sConf && rConf {
			st = "confirmed"
			holder = receiver
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET status='confirmed', completed_at=$2 WHERE id=$1`, req.HandoffID, at)
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET current_holder_id=$2 WHERE id=$1`, sampleID, receiver)
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "confirm_handoff", "handoff", req.HandoffID, true, map[string]interface{}{"side": req.ConfirmationSide})
		return 201, map[string]interface{}{
			"handoffId":          req.HandoffID,
			"status":             st,
			"senderConfirmed":    sConf,
			"receiverConfirmed":  rConf,
			"currentHolderId":    holder,
		}, nil
	})
}

func (app *App) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	var req struct {
		JourneyID string `json:"journeyId"`
	}
	if err := decodeBody(body, &req); err != nil || req.JourneyID == "" {
		writeErr(w, 400, "invalid_json", "journeyId required")
		return
	}
	payload, err := app.journeyPlanPayload(r.Context(), req.JourneyID, u.ActiveRole, u.UserID)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	// requester may only see journeys of their samples
	if u.ActiveRole == RoleRequester {
		sids := app.journeySampleIDs(r.Context(), req.JourneyID)
		ok := false
		for _, sid := range sids {
			s, err := app.loadSample(r.Context(), sid)
			if err == nil && s.RequesterID == u.UserID {
				ok = true
				break
			}
		}
		if !ok {
			writeErr(w, 403, "forbidden", "forbidden")
			return
		}
	}
	writeData(w, 200, payload)
}

func (app *App) bumpPlan(ctx context.Context, journeyID string, expected int) error {
	var ver int
	var status string
	err := app.store.pg.QueryRow(ctx, `SELECT plan_version, status FROM journeys WHERE id=$1`, journeyID).Scan(&ver, &status)
	if err != nil {
		return herr(404, "not_found", "journey not found")
	}
	if expected > 0 && ver != expected {
		return herr(409, "stale_plan", "stale plan version")
	}
	if status == "completed" || status == "cancelled" {
		return herr(409, "inactive_plan", "inactive plan")
	}
	_, err = app.store.pg.Exec(ctx, `UPDATE journeys SET plan_version = plan_version + 1 WHERE id=$1 AND plan_version=$2`, journeyID, ver)
	if err != nil {
		return herr(409, "concurrent_conflict", "concurrent conflict")
	}
	return nil
}

func (app *App) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			JourneyID            string `json:"journeyId"`
			ExpectedPlanVersion  int    `json:"expectedPlanVersion"`
			Reason               string `json:"reason"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		if req.ExpectedPlanVersion < 1 {
			return 0, nil, herr(400, "invalid_plan_version", "invalid plan version")
		}
		if err := app.bumpPlan(r.Context(), req.JourneyID, req.ExpectedPlanVersion); err != nil {
			return 0, nil, err
		}
		sids := app.journeySampleIDs(r.Context(), req.JourneyID)
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, req.JourneyID)
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
		for _, sid := range sids {
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='cancelled' WHERE id=$1 AND status NOT IN ('received')`, sid)
		}
		app.releaseJourneyCapacity(r.Context(), req.JourneyID)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "cancel_journey", "journey", req.JourneyID, true, map[string]interface{}{"reason": req.Reason})
		return 201, map[string]interface{}{
			"journeyId": req.JourneyID,
			"status":    "cancelled",
			"sampleIds": sids,
		}, nil
	})
}

func (app *App) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			JourneyID           string   `json:"journeyId"`
			ExpectedPlanVersion int      `json:"expectedPlanVersion"`
			SampleIDs           []string `json:"sampleIds"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		if err := app.bumpPlan(r.Context(), req.JourneyID, req.ExpectedPlanVersion); err != nil {
			return 0, nil, err
		}
		all := app.journeySampleIDs(r.Context(), req.JourneyID)
		if len(req.SampleIDs) == 0 || len(req.SampleIDs) >= len(all) {
			return 0, nil, herr(409, "invalid_split", "invalid split")
		}
		newID := newUUID()
		_, err := app.store.pg.Exec(r.Context(), `
INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, total_cost_units, valid)
SELECT $1, $2, 1, route_mode, 'planned', total_cost_units, TRUE FROM journeys WHERE id=$2`, newID, req.JourneyID)
		if err != nil {
			return 0, nil, err
		}
		for _, sid := range req.SampleIDs {
			_, _ = app.store.pg.Exec(r.Context(), `DELETE FROM journey_samples WHERE journey_id=$1 AND sample_id=$2`, req.JourneyID, sid)
			_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, newID, sid)
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET active_journey_id=$2 WHERE id=$1`, sid, newID)
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET journey_id=$2 WHERE sample_id=$1 AND journey_id=$3 AND status NOT IN ('completed')`, sid, newID, req.JourneyID)
		}
		orig, _ := app.journeyPlanPayload(r.Context(), req.JourneyID, u.ActiveRole, u.UserID)
		split, _ := app.journeyPlanPayload(r.Context(), newID, u.ActiveRole, u.UserID)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "split_journey", "journey", req.JourneyID, true, map[string]interface{}{"splitJourneyId": newID})
		return 201, map[string]interface{}{"journey": orig, "splitJourney": split}, nil
	})
}

func (app *App) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			TargetJourneyID     string   `json:"targetJourneyId"`
			ExpectedPlanVersion int      `json:"expectedPlanVersion"`
			SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		if err := app.bumpPlan(r.Context(), req.TargetJourneyID, req.ExpectedPlanVersion); err != nil {
			return 0, nil, err
		}
		// pulse cannot batch
		targetSamples := app.journeySampleIDs(r.Context(), req.TargetJourneyID)
		types := map[string]*sampleTypeRow{}
		checkPulse := func(sids []string) error {
			for _, sid := range sids {
				s, err := app.loadSample(r.Context(), sid)
				if err != nil {
					continue
				}
				st, _ := app.loadSampleType(r.Context(), s.SampleTypeID)
				if st != nil {
					types[st.ID] = st
					if !st.BatchingAllowed {
						return herr(409, "pulse_no_batch", "pulse cannot be batched")
					}
				}
			}
			return nil
		}
		if err := checkPulse(targetSamples); err != nil {
			return 0, nil, err
		}
		for _, src := range req.SourceJourneyIDs {
			sids := app.journeySampleIDs(r.Context(), src)
			if err := checkPulse(sids); err != nil {
				return 0, nil, err
			}
			// incompatibilities
			for _, sid := range sids {
				s, _ := app.loadSample(r.Context(), sid)
				if s == nil {
					continue
				}
				for _, tid := range targetSamples {
					t, _ := app.loadSample(r.Context(), tid)
					if t == nil {
						continue
					}
					if contains(s.Incompatible, t.SampleTypeID) || contains(t.Incompatible, s.SampleTypeID) {
						return 0, nil, herr(409, "incompatible_batch", "incompatible samples")
					}
				}
				_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.TargetJourneyID, sid)
				_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET active_journey_id=$2 WHERE id=$1`, sid, req.TargetJourneyID)
				_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET journey_id=$2 WHERE sample_id=$1 AND journey_id=$3 AND status NOT IN ('completed')`, sid, req.TargetJourneyID, src)
			}
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, src)
		}
		payload, err := app.journeyPlanPayload(r.Context(), req.TargetJourneyID, u.ActiveRole, u.UserID)
		if err != nil {
			return 0, nil, err
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]interface{}{"sources": req.SourceJourneyIDs})
		return 201, payload, nil
	})
}

func (app *App) handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			JourneyID           string `json:"journeyId"`
			ExpectedPlanVersion int    `json:"expectedPlanVersion"`
			Reason              string `json:"reason"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		if err := app.bumpPlan(r.Context(), req.JourneyID, req.ExpectedPlanVersion); err != nil {
			return 0, nil, err
		}
		status, replacement, err := app.replanJourney(r.Context(), u, req.JourneyID)
		if err != nil {
			return 0, nil, err
		}
		out := map[string]interface{}{"journeyId": req.JourneyID, "replanStatus": status}
		if replacement != "" {
			out["replacementPlanId"] = replacement
			plan, _ := app.journeyPlanPayload(r.Context(), replacement, u.ActiveRole, u.UserID)
			out["replacementJourney"] = plan
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "reroute_journey", "journey", req.JourneyID, true, map[string]interface{}{"status": status})
		return 201, out, nil
	})
}

func (app *App) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			JourneyID           string                 `json:"journeyId"`
			ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
			ChangeType          string                 `json:"changeType"`
			Changes             map[string]interface{} `json:"changes"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		valid := map[string]bool{
			"add_stop": true, "remove_stop": true, "reorder_stops": true, "replace_worker": true,
			"reassign_worker": true, "merge_samples": true, "split_samples": true, "split_batch": true,
			"cancel_work": true, "reroute": true, "replace_route": true,
		}
		if !valid[req.ChangeType] {
			return 0, nil, herr(400, "invalid_change_type", "invalid change type")
		}
		if err := app.bumpPlan(r.Context(), req.JourneyID, req.ExpectedPlanVersion); err != nil {
			return 0, nil, err
		}
		switch req.ChangeType {
		case "cancel_work":
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, req.JourneyID)
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
		case "reroute", "replace_route":
			_, _, _ = app.replanJourney(r.Context(), u, req.JourneyID)
		case "replace_worker", "reassign_worker":
			if wid, _ := req.Changes["workerId"].(string); wid != "" {
				if aid, _ := req.Changes["assignmentId"].(string); aid != "" {
					_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET worker_id=$2, offered_to=$2, status='offered' WHERE id=$1 AND status NOT IN ('completed','cancelled')`, aid, wid)
				}
			}
		}
		payload, err := app.journeyPlanPayload(r.Context(), req.JourneyID, u.ActiveRole, u.UserID)
		if err != nil {
			return 0, nil, err
		}
		app.audit(r.Context(), u.UserID, u.ActiveRole, "edit_active_plan", "journey", req.JourneyID, true, map[string]interface{}{"changeType": req.ChangeType})
		return 201, payload, nil
	})
}

func (app *App) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			ResourceType string `json:"resourceType"`
			ResourceID   string `json:"resourceId"`
			Reason       string `json:"reason"`
			OccurredAt   string `json:"occurredAt"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		valid := map[string]bool{"location": true, "node": true, "laboratory": true, "connection": true, "route": true, "worker": true, "capacity": true}
		if !valid[req.ResourceType] {
			return 0, nil, herr(400, "invalid_resource_type", "invalid resource type")
		}
		at, err := parseTime(req.OccurredAt)
		if err != nil {
			return 0, nil, herr(400, "invalid_time", "invalid occurredAt")
		}
		// mark resource unavailable
		switch req.ResourceType {
		case "location", "node", "laboratory":
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE locations SET active=FALSE WHERE id=$1`, req.ResourceID)
		case "connection", "route":
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE connections SET active=FALSE WHERE id=$1`, req.ResourceID)
		case "worker":
			_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET available=FALSE WHERE id=$1`, req.ResourceID)
		}
		app.bumpNetwork(r.Context())
		affected := []string{}
		replacements := []string{}
		replanStatus := "not_required"
		// find journeys touching this resource
		var q string
		switch req.ResourceType {
		case "location", "node", "laboratory":
			q = `SELECT DISTINCT journey_id FROM assignments WHERE (from_location_id=$1 OR to_location_id=$1 OR node_id=$1 OR laboratory_id=$1) AND status NOT IN ('completed','cancelled')`
		case "connection", "route":
			q = `SELECT DISTINCT a.journey_id FROM assignments a JOIN connections c ON c.from_location_id=a.from_location_id AND c.to_location_id=a.to_location_id WHERE c.id=$1 AND a.status NOT IN ('completed','cancelled')`
		case "worker":
			q = `SELECT DISTINCT journey_id FROM assignments WHERE worker_id=$1 AND status NOT IN ('completed','cancelled')`
		default:
			q = `SELECT DISTINCT journey_id FROM capacity_reservations WHERE resource_id=$1 AND active=TRUE`
		}
		rows, err := app.store.pg.Query(r.Context(), q, req.ResourceID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var jid string
				if rows.Scan(&jid) != nil {
					continue
				}
				st, repl, _ := app.replanJourney(r.Context(), u, jid)
				sids := app.journeySampleIDs(r.Context(), jid)
				affected = append(affected, sids...)
				if repl != "" {
					replacements = append(replacements, repl)
				}
				if st != "not_required" {
					replanStatus = st
				}
			}
		}
		did := newUUID()
		_, _ = app.store.pg.Exec(r.Context(), `
INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, replan_status)
VALUES ($1,$2,$3,$4,$5,$6)`, did, req.ResourceType, req.ResourceID, req.Reason, at, replanStatus)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason})
		return 201, map[string]interface{}{
			"disruptionId":       did,
			"affectedSampleIds":  affected,
			"replacementPlanIds": replacements,
			"replanStatus":       replanStatus,
		}, nil
	})
}

func (app *App) replanJourney(ctx context.Context, u *SessionUser, journeyID string) (string, string, error) {
	sids := app.journeySampleIDs(ctx, journeyID)
	if len(sids) == 0 {
		return "not_required", "", nil
	}
	// cancel unfinished assignments, keep completed
	_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
	app.releaseJourneyCapacity(ctx, journeyID)
	_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced' WHERE id=$1`, journeyID)

	// replan first unfinished sample (and attach others if possible)
	var lastStatus, lastID string
	for _, sid := range sids {
		s, err := app.loadSample(ctx, sid)
		if err != nil || s.Status == "received" || s.Status == "cancelled" {
			continue
		}
		st, _ := app.loadSampleType(ctx, s.SampleTypeID)
		plan, err := app.evaluateServiceability(ctx, Coord{s.OriginLat, s.OriginLng}, s.OriginType, "", s.SampleTypeID, time.Now(), s.Deadline, s.Earliest, s.Latest)
		if err != nil || !plan.Serviceable {
			reason := "no_valid_route"
			status := "exception"
			if plan != nil && plan.Reason == "deadline_unreachable" {
				status = "expired"
				reason = "deadline_unreachable"
			}
			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status=$2, exception=$3 WHERE id=$1`, sid, status, asJSON(map[string]interface{}{"reason": reason}))
			if status == "expired" {
				lastStatus = "expired"
			} else {
				lastStatus = "exception"
			}
			continue
		}
		req := collectionReqBody{
			Origin: Coord{s.OriginLat, s.OriginLng}, OriginType: s.OriginType, SampleTypeID: s.SampleTypeID,
			ContainerType: s.ContainerType, TemperatureMinC: s.TempMin, TemperatureMaxC: s.TempMax,
		}
		jid, _, err := app.materializeJourney(ctx, u, sid, req, plan, st, s.Sealed, time.Now())
		if err != nil {
			lastStatus = "exception"
			continue
		}
		_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2 WHERE id=$1`, jid, journeyID)
		_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE id=$1`, sid, jid, plan.TargetLab)
		lastStatus = "replaced"
		lastID = jid
	}
	if lastStatus == "" {
		lastStatus = "not_required"
	}
	return lastStatus, lastID, nil
}

func (app *App) offerAssignments(ctx context.Context) {
	// expire stale offers
	_, _ = app.store.pg.Exec(ctx, `
UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL
WHERE status='offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < now()`)
	rows, err := app.store.pg.Query(ctx, `SELECT id FROM assignments WHERE status='pending' AND worker_id IS NULL`)
	if err != nil {
		return
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		if rows.Scan(&id) == nil {
			app.offerOne(ctx, id)
		}
	}
}

func (app *App) offerOne(ctx context.Context, assignmentID string) string {
	var kind string
	var sampleID, nodeID, labID *string
	var expected *string
	err := app.store.pg.QueryRow(ctx, `SELECT kind, sample_id, node_id, laboratory_id, expected_sample_type_id FROM assignments WHERE id=$1`, assignmentID).
		Scan(&kind, &sampleID, &nodeID, &labID, &expected)
	if err != nil {
		return ""
	}
	role := RoleDeliveryPartner
	switch kind {
	case "collection":
		role = RoleCollectionProfessional
	case "node":
		role = RoleNodeHandler
	case "laboratory":
		role = RoleLaboratoryTeam
	}
	q := `
SELECT u.id FROM users u
JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
WHERE u.active=TRUE AND u.available=TRUE
  AND (u.decline_penalty_until IS NULL OR u.decline_penalty_until < now())
`
	args := []interface{}{role}
	if (kind == "node" || kind == "laboratory") && (nodeID != nil || labID != nil) {
		loc := ""
		if nodeID != nil {
			loc = *nodeID
		}
		if labID != nil {
			loc = *labID
		}
		q += ` AND u.assigned_location_id=$2`
		args = append(args, loc)
	}
	q += ` ORDER BY COALESCE(u.last_offered_at, to_timestamp(0)) ASC, COALESCE(u.last_assigned_at, to_timestamp(0)) ASC,
  (SELECT COUNT(*) FROM assignments a WHERE a.worker_id=u.id AND a.status NOT IN ('completed','cancelled')) ASC
LIMIT 5`
	wrows, err := app.store.pg.Query(ctx, q, args...)
	if err != nil {
		return ""
	}
	defer wrows.Close()
	var candidates []string
	for wrows.Next() {
		var id string
		if wrows.Scan(&id) == nil {
			candidates = append(candidates, id)
		}
	}
	if len(candidates) == 0 {
		if kind == "collection" && expected != nil {
			// no qualified collector — flag after timeout; we flag immediately only if never anyone
			var n int
			_ = app.store.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1 WHERE u.active`, RoleCollectionProfessional).Scan(&n)
			if n == 0 && sampleID != nil {
				_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`,
					*sampleID, asJSON(map[string]interface{}{"reason": "no_qualified_worker"}))
				_, _ = app.store.pg.Exec(ctx, `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,now())`,
					newUUID(), *sampleID, "no_qualified_worker")
			}
		}
		return ""
	}
	// qualification filter for collection
	chosen := candidates[0]
	if kind == "collection" && expected != nil {
		st, _ := app.loadSampleType(ctx, *expected)
		if st != nil && st.QualifiedCollector {
			found := ""
			for _, cid := range candidates {
				wu, err := app.loadUser(ctx, cid, "")
				if err != nil {
					continue
				}
				if contains(wu.Qualifications, st.RequiredQualification) || hasActiveCert(wu.Certifications, st.RequiredQualification) {
					found = cid
					break
				}
			}
			if found == "" {
				if sampleID != nil {
					// leave pending; background will eventually exception
				}
				return ""
			}
			chosen = found
		}
	}
	exp := time.Now().Add(offerTTL)
	_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3 WHERE id=$1`, assignmentID, chosen, exp)
	_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=now() WHERE id=$1`, chosen)
	app.emit("assignment.offered", "assignment", assignmentID, map[string]interface{}{"workerId": chosen})
	return chosen
}

func (app *App) handleEvents(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if r.Header.Get("Upgrade") == "websocket" || r.Header.Get("Connection") == "Upgrade" {
		app.handleWS(w, r, u)
		return
	}
	since := int64(0)
	if s := r.URL.Query().Get("since"); s != "" {
		var n int64
		if _, err := parseInt64(s, &n); err == nil {
			since = n
		}
	}
	rows, err := app.store.pg.Query(r.Context(), `
SELECT id, type, entity_type, entity_id, payload, created_at
FROM realtime_events WHERE id > $1 ORDER BY id ASC LIMIT 200`, since)
	if err != nil {
		writeErr(w, 500, "internal_error", "internal error")
		return
	}
	defer rows.Close()
	events := []map[string]interface{}{}
	var cursor int64 = since
	for rows.Next() {
		var id int64
		var typ, et, eid string
		var payload []byte
		var created time.Time
		if rows.Scan(&id, &typ, &et, &eid, &payload, &created) != nil {
			continue
		}
		var p map[string]interface{}
		_ = json.Unmarshal(payload, &p)
		if p == nil {
			p = map[string]interface{}{}
		}
		events = append(events, map[string]interface{}{
			"id": id, "type": typ, "entityType": et, "entityId": eid, "payload": p, "createdAt": rfc3339(created),
		})
		cursor = id
	}
	writeData(w, 200, map[string]interface{}{"events": events, "cursor": cursor})
}

func parseInt64(s string, out *int64) (int, error) {
	var n int64
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, herr(400, "invalid_json", "invalid since")
		}
		n = n*10 + int64(c-'0')
	}
	*out = n
	return 0, nil
}

