	mux.HandleFunc("/api/set-worker-availability", method(http.MethodPost, app.requireRole(app.handleSetWorkerAvailability)))

	mux.HandleFunc("/api/create-location", method(http.MethodPost, app.requireRole(app.handleCreateLocation)))
	mux.HandleFunc("/api/update-location", method(http.MethodPost, app.requireRole(app.handleUpdateLocation)))
