	mux.HandleFunc("/api/configure-laboratory-acceptance", method(http.MethodPost, app.requireRole(app.handleConfigureLabAcceptance)))
	mux.HandleFunc("/api/create-sample-type", method(http.MethodPost, app.requireRole(app.handleCreateSampleType)))
	mux.HandleFunc("/api/update-sample-type", method(http.MethodPost, app.requireRole(app.handleUpdateSampleType)))
	mux.HandleFunc("/api/check-serviceability", method(http.MethodPost, app.requireRole(app.handleCheckServiceability)))
	mux.HandleFunc("/api/read-serviceability-snapshot", method(http.MethodPost, app.requireRole(app.handleReadServiceabilitySnapshot)))
	mux.HandleFunc("/api/read-operations-state", method(http.MethodPost, app.requireRole(app.handleReadOperationsState)))
	mux.HandleFunc("/api/search-audit-trail", method(http.MethodPost, app.requireRole(app.handleSearchAudit)))

	mux.HandleFunc("/api/create-collection-request", method(http.MethodPost, app.requireRole(app.handleCreateCollectionRequest)))
	mux.HandleFunc("/api/ingest-presealed-sample", method(http.MethodPost, app.requireRole(app.handleIngestPresealed)))
	mux.HandleFunc("/api/read-sample-state/", method(http.MethodGet, app.requireAuth(app.handleReadSampleState)))
	mux.HandleFunc("/api/read-sample-lifecycle", method(http.MethodPost, app.requireAuth(app.handleReadSampleLifecycle)))
