func (app *App) serveFrontend(w http.ResponseWriter, r *http.Request) {
	if strings.HasPrefix(r.URL.Path, "/api/") {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	p := filepath.Join(app.frontend, filepath.Clean(r.URL.Path))
	if info, err := os.Stat(p); err == nil && !info.IsDir() {
		http.ServeFile(w, r, p)
		return
	}
	index := filepath.Join(app.frontend, "index.html")
	if _, err := os.Stat(index); err == nil {
		http.ServeFile(w, r, index)
		return
	}
	w.Header().Set("Content-Type", "text/html")
	_, _ = w.Write([]byte(`<!doctype html><html><body><p>frontend not built</p></body></html>`))
}

func (app *App) offerLoop() {
	t := time.NewTicker(offerScanInterval)
	defer t.Stop()
	for range t.C {
		app.offerAssignments(context.Background())
	}
}

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
	Subprotocols: []string{"bearer"},
}

func (app *App) handleWS(w http.ResponseWriter, r *http.Request, u *SessionUser) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()
	ch := app.subscribe()
	defer app.unsubscribe(ch)
	_ = conn.WriteJSON(map[string]interface{}{
		"id": 0, "type": "hello", "entityType": "session", "entityId": u.UserID,
		"payload": map[string]interface{}{"ok": true}, "createdAt": rfc3339(time.Now()),
	})
	for ev := range ch {
		if err := conn.WriteJSON(ev); err != nil {
			return
		}
	}
}

