   486	func parseInt64(s string, out *int64) (int, error) {
   487		var n int64
   488		for _, c := range s {
   489			if c < '0' || c > '9' {
   490				return 0, herr(400, "invalid_json", "invalid since")
   491			}
   492			n = n*10 + int64(c-'0')
   493		}
   494		*out = n
   495		return 0, nil
   496	}
