python3 - <<'PY'
import json
from pathlib import Path
d=json.loads(Path('/workspace/contracts/openapi.contract.json').read_text())
paths=d['paths']
# dump 200/201 data schemas for key ops
for p, methods in paths.items():
    for m, op in methods.items():
        print('====', op.get('operationId'), p, m, '====')
        res=op.get('responses',{})
        for code in sorted(res, key=lambda x: str(x)):
            schema=res[code].get('content',{}).get('application/json',{}).get('schema')
            if not schema: 
                print(code, 'no json')
                continue
            # print required and properties of data if wrapped
            props=schema.get('properties',{})
            req=schema.get('required')
            add=schema.get('additionalProperties', None)
            print(f'  {code}: required={req} addl={add} props={list(props.keys())}')
            if 'data' in props:
                data=props['data']
                if '$ref' in data:
                    print('    data $ref', data['$ref'])
                elif 'allOf' in data:
                    print('    data allOf', data['allOf'])
                else:
                    print('    data required', data.get('required'), 'addl', data.get('additionalProperties'), 'props', list(data.get('properties',{}).keys()))
                    for k,v in data.get('properties',{}).items():
                        if v.get('type')=='object' or 'properties' in v or '$ref' in v or 'allOf' in v:
                            print('      ', k, 'required', v.get('required'), 'addl', v.get('additionalProperties'), 'props', list(v.get('properties',{}).keys()) if 'properties' in v else v.get('$ref') or v.get('allOf'))
        print()
PY

