   338			w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Sec-WebSocket-Protocol")
   339			w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
   340			if r.Method == http.MethodOptions {
   341				w.WriteHeader(204)
   342				return
   343			}
   344			next.ServeHTTP(w, r)
   345		})
