   221	func (app *App) handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request) {
   222		u := currentUser(r)
   223		if u.ActiveRole != RoleLaboratoryTeam && !u.isDispatcher() {
   224			writeErr(w, 403, "forbidden", "forbidden")
