   227		body := readBody(r)
   228		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   229			var req struct {
   230				SampleID     string `json:"sampleId"`
   231				LaboratoryID string `json:"laboratoryId"`
   232				ReceivedAt   string `json:"receivedAt"`
   233			}
   234			if err := decodeBody(body, &req); err != nil {
