   322	func (app *App) handleRecordCheckpoint(w http.ResponseWriter, r *http.Request) {
   323		u := currentUser(r)
   324		body := readBody(r)
   325		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   326			var req struct {
   327				SampleID             string  `json:"sampleId"`
   328				AssignmentID         string  `json:"assignmentId"`
   329				LocationID           string  `json:"locationId"`
   330				ContainerType        string  `json:"containerType"`
   331				ObservedTemperatureC float64 `json:"observedTemperatureC"`
   332				RecordedAt           string  `json:"recordedAt"`
   333			}
   334			if err := decodeBody(body, &req); err != nil {
   335				return 0, nil, herr(400, "invalid_json", "invalid json")
   336			}
   337			at, err := parseTime(req.RecordedAt)
   338			if err != nil {
   339				return 0, nil, herr(400, "invalid_time", "invalid recordedAt")
   340			}
   341			s, err := app.loadSample(r.Context(), req.SampleID)
   342			if err != nil {
   343				return 0, nil, err
   344			}
   345			if s.Status == "received" || s.Status == "cancelled" {
   346				return 0, nil, herr(409, "terminal_sample", "sample is terminal")
   347			}
   348			if s.CurrentHolderID == nil || *s.CurrentHolderID != u.UserID {
   349				if !u.isDispatcher() {
   350					return 0, nil, herr(403, "forbidden", "not current holder")
   351				}
   352			}
   353			compliant := req.ObservedTemperatureC >= s.TempMin && req.ObservedTemperatureC <= s.TempMax
   354			if req.ContainerType != "" && s.ContainerType != "" && req.ContainerType != s.ContainerType {
   355				compliant = false
   356			}
   357			cid := newUUID()
   358			_, _ = app.store.pg.Exec(r.Context(), `
   359	INSERT INTO checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, recorded_at, compliant)
   360	VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, cid, s.ID, req.AssignmentID, nilIfEmpty(req.LocationID), req.ContainerType, req.ObservedTemperatureC, at, compliant)
   361			status := s.Status
   362			if !compliant {
   363				status = "exception"
   364				_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='exception', exception=$2 WHERE id=$1`, s.ID,
   365					asJSON(map[string]interface{}{"reason": "handling_violation", "checkpointId": cid}))
   366				_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,$4)`,
   367					newUUID(), s.ID, "handling_violation", at)
   368			}
   369			app.audit(r.Context(), u.UserID, u.ActiveRole, "record_handling_checkpoint", "sample", s.ID, true, map[string]interface{}{"compliant": compliant})
   370			return 201, map[string]interface{}{
   371				"checkpointId": cid,
   372				"sampleId":     s.ID,
   373				"compliant":    compliant,
   374				"sampleStatus": status,
   375			}, nil
   376		})
   377	}
