func (app *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	_ = decodeBody(body, &req)
	if req.Role != "" && req.Role != u.ActiveRole && !u.isDispatcher() {
		writeErr(w, 400, "invalid_role", "role does not match active role")
		return
	}
	role := u.ActiveRole
	if req.Role != "" && u.isDispatcher() {
		role = req.Role
	}
	pending, inProg, completed := app.roleWork(r.Context(), u, role)
	if req.Status != "" {
		switch req.Status {
		case "pending":
			inProg, completed = []map[string]interface{}{}, []map[string]interface{}{}
		case "in_progress", "accepted", "inProgress":
			pending, completed = []map[string]interface{}{}, []map[string]interface{}{}
		case "completed", "past":
			pending, inProg = []map[string]interface{}{}, []map[string]interface{}{}
		}
	}
	writeData(w, 200, map[string]interface{}{
		"role":      role,
		"pending":   pending,
		"inProgress": inProg,
		"completed": completed,
	})
}

func (app *App) roleWork(ctx context.Context, u *SessionUser, role string) (pending, inProg, completed []map[string]interface{}) {
	pending, inProg, completed = []map[string]interface{}{}, []map[string]interface{}{}, []map[string]interface{}{}
	now := time.Now()
	if role == RoleRequester {
		rows, err := app.store.pg.Query(ctx, `SELECT id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, u.UserID)
		if err != nil {
			return
		}
		defer rows.Close()
		for rows.Next() {
			var id string
			if rows.Scan(&id) != nil {
				continue
			}
			s, err := app.loadSample(ctx, id)
			if err != nil {
				continue
			}
			item := app.sampleWorkItem(ctx, s, now)
			switch s.Status {
			case "received", "cancelled", "expired":
				completed = append(completed, item)
			case "requested":
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
		return
	}
	if role == RoleDispatcher || role == RoleAdministrator {
		rows, err := app.store.pg.Query(ctx, `SELECT id FROM samples ORDER BY created_at DESC LIMIT 300`)
		if err != nil {
			return
		}
		defer rows.Close()
		for rows.Next() {
			var id string
			if rows.Scan(&id) != nil {
				continue
			}
			s, err := app.loadSample(ctx, id)
			if err != nil {
				continue
			}
			item := app.sampleWorkItem(ctx, s, now)
			switch s.Status {
			case "received", "cancelled", "expired":
				completed = append(completed, item)
			case "requested":
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
		return
	}
	// worker assignments
	rows, err := app.store.pg.Query(ctx, `
SELECT id FROM assignments
WHERE worker_id=$1 OR offered_to=$1
ORDER BY created_at DESC`, u.UserID)
	if err != nil {
		return
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		if rows.Scan(&id) != nil {
			continue
		}
		item, status, ok := app.assignmentWorkItem(ctx, id)
		if !ok {
			continue
		}
		switch status {
		case "completed", "cancelled":
			completed = append(completed, item)
		case "accepted", "in_progress", "at_pickup", "picked_up", "in_transit", "arrived", "delivered":
			inProg = append(inProg, item)
		default:
			pending = append(pending, item)
		}
	}
	return
}

func (app *App) sampleWorkItem(ctx context.Context, s *sampleRow, now time.Time) map[string]interface{} {
	ids := []string{s.ID, s.RequestID}
	hist := app.loadTimeline(ctx, ids...)
	if hist == nil {
		hist = []map[string]interface{}{}
	}
	item := map[string]interface{}{
		"kind":          "sample",
		"sampleId":      s.ID,
		"sample_id":     s.ID,
		"requestId":     s.RequestID,
		"status":        s.Status,
		"serviceability": s.Serviceability,
		"requestedAt":   rfc3339(s.RequestedAt),
		"deliveryDeadline": rfc3339(s.Deadline),
		"earliestCollectionAt": rfc3339(s.Earliest),
		"latestCollectionAt": rfc3339(s.Latest),
		"requesterId":   s.RequesterID,
		"history":       hist,
		"locationStale": isStale(s.LocationRecordedAt, now),
	}
	if s.ActiveJourneyID != nil {
		item["journeyId"] = *s.ActiveJourneyID
		item["activeJourneyId"] = *s.ActiveJourneyID
	}
	if s.TargetLabID != nil {
		item["laboratoryId"] = *s.TargetLabID
	}
	if s.CurrentHolderID != nil {
		item["currentHolderId"] = *s.CurrentHolderID
	}
	if s.LocationRecordedAt != nil {
		item["locationRecordedAt"] = rfc3339(*s.LocationRecordedAt)
	}
	return item
}

func (app *App) assignmentWorkItem(ctx context.Context, id string) (map[string]interface{}, string, bool) {
	var kind, status string
	var sampleID, journeyID, from, to, node, lab, incoming, outgoing, expected *string
	var seq int
	var offerExp *time.Time
	err := app.store.pg.QueryRow(ctx, `
SELECT kind, status, sample_id, journey_id, from_location_id, to_location_id, sequence,
  offer_expires_at, node_id, laboratory_id, incoming_from_location_id, outgoing_to_location_id, expected_sample_type_id
FROM assignments WHERE id=$1`, id).Scan(&kind, &status, &sampleID, &journeyID, &from, &to, &seq, &offerExp, &node, &lab, &incoming, &outgoing, &expected)
	if err != nil {
		return nil, "", false
	}
	sid := ""
	if sampleID != nil {
		sid = *sampleID
	}
	hist := app.loadTimeline(ctx, id, sid)
	if hist == nil {
		hist = []map[string]interface{}{}
	}
	item := map[string]interface{}{
		"kind":         kind,
		"assignmentId": id,
		"assignment_id": id,
		"sampleId":     sid,
		"sample_id":    sid,
		"status":       status,
		"history":      hist,
	}
	if journeyID != nil {
		item["journeyId"] = *journeyID
	}
	if from != nil {
		item["fromLocationId"] = *from
	}
	if to != nil {
		item["toLocationId"] = *to
	}
	item["sequence"] = seq
	if offerExp != nil {
		item["offerExpiresAt"] = rfc3339(*offerExp)
	}
	if node != nil {
		item["nodeId"] = *node
	}
	if incoming != nil {
		item["incomingFromLocationId"] = *incoming
	}
	if outgoing != nil {
		item["outgoingToLocationId"] = *outgoing
	}
	if lab != nil {
		item["laboratoryId"] = *lab
	}
	if expected != nil {
		item["expectedSampleTypeId"] = *expected
	}
	return item, status, true
}

func (app *App) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	body := readBody(r)
	app.withIdem(w, r, body, true, func() (int, interface{}, error) {
		var req struct {
			AssignmentID string `json:"assignmentId"`
		}
		if err := decodeBody(body, &req); err != nil {
			return 0, nil, herr(400, "invalid_json", "invalid json")
		}
		var status string
		var offered, worker *string
		err := app.store.pg.QueryRow(r.Context(), `SELECT status, offered_to, worker_id FROM assignments WHERE id=$1`, req.AssignmentID).
			Scan(&status, &offered, &worker)
		if err != nil {
			return 0, nil, herr(404, "not_found", "assignment not found")
		}
		if worker != nil && *worker == u.UserID && (status == "accepted" || status == "in_progress") {
			return 201, map[string]interface{}{"assignmentId": req.AssignmentID, "workerId": u.UserID, "status": "accepted"}, nil
		}
		if offered == nil || *offered != u.UserID {
			if !u.isDispatcher() {
				return 0, nil, herr(409, "offer_not_available", "offer not available")
			}
		}
		if status != "offered" && status != "pending" && !u.isDispatcher() {
			return 0, nil, herr(409, "offer_not_available", "offer not available")
		}
		_, err = app.store.pg.Exec(r.Context(), `
UPDATE assignments SET status='accepted', worker_id=$2, accepted_at=now(), offered_to=NULL WHERE id=$1`, req.AssignmentID, u.UserID)
		if err != nil {
			return 0, nil, err
		}
		_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET last_assigned_at=now() WHERE id=$1`, u.UserID)
		app.audit(r.Context(), u.UserID, u.ActiveRole, "accept_assignment", "assignment", req.AssignmentID, true, nil)
		app.emit("assignment.accepted", "assignment", req.AssignmentID, map[string]interface{}{"workerId": u.UserID})
		return 201, map[string]interface{}{
			"assignmentId": req.AssignmentID,
			"workerId":     u.UserID,
			"status":       "accepted",
		}, nil
	})
}

func (app *App) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
