	seq := 1
	est := earliest
	// pickup stop at origin / collection point
	pickupLoc := plan.CollectionPoint
	if req.OriginType == "node" && req.OriginNodeID != "" {
		pickupLoc = req.OriginNodeID
	}
	stopPickup := newUUID()
	_, _ = app.store.pg.Exec(ctx, `
INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
VALUES ($1,$2,$3,'pickup',$4,$5,0,$6,$7)`, stopPickup, jid, pickupLoc, seq, est, req.Origin.Latitude, req.Origin.Longitude)
	seq++

	// remaining path stops
	for i, locID := range plan.Path {
		stopType := "handoff"
		if i == len(plan.Path)-1 {
			stopType = "delivery"
		} else if i == 0 && req.OriginType == "node" {
			continue
		} else if i == 0 {
			stopType = "handoff"
		}
		l := locByIDMust(ctx, app, locID)
		est = est.Add(time.Duration(15) * time.Minute)
		dwell := 0
		if l != nil {
			dwell = l.HandlingMinutes
		}
		sid := newUUID()
		var lat, lng interface{}
		if l != nil {
			lat, lng = l.Lat, l.Lng
		}
		_, _ = app.store.pg.Exec(ctx, `
INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`, sid, jid, locID, stopType, seq, est, dwell, lat, lng)
		seq++
	}

	aids := []string{}
	asSeq := 1
	if !alreadySealed {
		aid := newUUID()
		_, err = app.store.pg.Exec(ctx, `
INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, expected_sample_type_id)
VALUES ($1,$2,$3,'collection',$4,'pending',$5,$6,$7)`,
			aid, jid, sampleID, asSeq, nilIfEmpty(pickupLoc), nilIfEmpty(pickupLoc), st.ID)
		if err != nil {
			return "", nil, err
		}
		aids = append(aids, aid)
		asSeq++
	}

	// transport legs along path
	path := plan.Path
	if len(path) == 0 {
		path = []string{pickupLoc}
		if plan.TargetLab != "" && plan.TargetLab != pickupLoc {
			path = append(path, plan.TargetLab)
		}
	}
	if alreadySealed && req.OriginType == "node" && req.OriginNodeID != "" && (len(path) == 0 || path[0] != req.OriginNodeID) {
		path = append([]string{req.OriginNodeID}, path...)
	}
	for i := 0; i+1 < len(path); i++ {
		aid := newUUID()
		_, err = app.store.pg.Exec(ctx, `
INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, expected_sample_type_id)
VALUES ($1,$2,$3,'transport',$4,'pending',$5,$6,$7)`,
			aid, jid, sampleID, asSeq, path[i], path[i+1], st.ID)
		if err != nil {
			return "", nil, err
		}
		aids = append(aids, aid)
		asSeq++
		// reserve connection capacity
		_ = app.reserveCapacity(ctx, path[i], path[i+1], jid, sampleID, st.RequiresCooled)
	}

	// node assignment at collection / intermediate
	if pickupLoc != "" {
		aid := newUUID()
		_, _ = app.store.pg.Exec(ctx, `
INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, node_id, expected_sample_type_id)
VALUES ($1,$2,$3,'node',$4,'pending',$5,$6)`, aid, jid, sampleID, asSeq, pickupLoc, st.ID)
		aids = append(aids, aid)
		asSeq++
		_ = app.reserveLocationCapacity(ctx, pickupLoc, jid, sampleID, st.RequiresCooled)
	}
	if plan.TargetLab != "" {
		aid := newUUID()
		_, _ = app.store.pg.Exec(ctx, `
INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, laboratory_id, expected_sample_type_id)
VALUES ($1,$2,$3,'laboratory',$4,'pending',$5,$6)`, aid, jid, sampleID, asSeq, plan.TargetLab, st.ID)
		aids = append(aids, aid)
		_ = app.reserveLocationCapacity(ctx, plan.TargetLab, jid, sampleID, st.RequiresCooled)
	}

	app.offerAssignments(ctx)
	return jid, aids, nil
}

