func (app *App) reserveCapacity(ctx context.Context, fromID, toID, journeyID, sampleID string, cooled bool) error {
	conns, err := app.loadConnections(ctx)
	if err != nil {
		return err
	}
	c := findConn(conns, fromID, toID)
	if c == nil {
		return nil
	}
	reg, cool := 1, 0
	if cooled {
		reg, cool = 0, 1
		if c.CooledCap > 0 && c.CooledCap-c.CooledReserved < 1 {
			return herr(409, "cooled_capacity_exhausted", "cooled capacity exhausted")
		}
		_, err = app.store.pg.Exec(ctx, `UPDATE connections SET cooled_reserved_units = cooled_reserved_units + 1 WHERE id=$1`, c.ID)
	} else {
		if c.CapacityUnits > 0 && c.CapacityUnits-c.ReservedUnits < 1 {
			return herr(409, "capacity_exhausted", "capacity exhausted")
		}
		if c.CapacityUnits > 0 {
			_, err = app.store.pg.Exec(ctx, `UPDATE connections SET reserved_units = reserved_units + 1 WHERE id=$1`, c.ID)
		}
	}
	if err != nil {
		return err
	}
	_, _ = app.store.pg.Exec(ctx, `
INSERT INTO capacity_reservations (id, resource_id, resource_kind, journey_id, sample_id, regular_units, cooled_units, active)
VALUES ($1,$2,'connection',$3,$4,$5,$6,TRUE)`, newUUID(), c.ID, journeyID, sampleID, reg, cool)
	return nil
}

func (app *App) reserveLocationCapacity(ctx context.Context, locID, journeyID, sampleID string, cooled bool) error {
	var cap, reserved, ccap, cres int
	err := app.store.pg.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM locations WHERE id=$1`, locID).
		Scan(&cap, &reserved, &ccap, &cres)
	if err != nil {
		return nil
	}
	reg, cool := 1, 0
	if cooled {
		reg, cool = 0, 1
		if ccap > 0 && ccap-cres < 1 {
			return herr(409, "cooled_capacity_exhausted", "cooled capacity exhausted")
		}
		if ccap > 0 {
			_, _ = app.store.pg.Exec(ctx, `UPDATE locations SET cooled_reserved_units = cooled_reserved_units + 1 WHERE id=$1`, locID)
		}
	} else {
		if cap > 0 && cap-reserved < 1 {
			return herr(409, "capacity_exhausted", "capacity exhausted")
		}
		if cap > 0 {
			_, _ = app.store.pg.Exec(ctx, `UPDATE locations SET reserved_units = reserved_units + 1 WHERE id=$1`, locID)
		}
	}
	_, _ = app.store.pg.Exec(ctx, `
INSERT INTO capacity_reservations (id, resource_id, resource_kind, journey_id, sample_id, regular_units, cooled_units, active)
VALUES ($1,$2,'location',$3,$4,$5,$6,TRUE)`, newUUID(), locID, journeyID, sampleID, reg, cool)
	return nil
}

func (app *App) releaseJourneyCapacity(ctx context.Context, journeyID string) {
	rows, err := app.store.pg.Query(ctx, `SELECT id, resource_id, resource_kind, regular_units, cooled_units FROM capacity_reservations WHERE journey_id=$1 AND active=TRUE`, journeyID)
	if err != nil {
		return
	}
	defer rows.Close()
	type resv struct {
		id, rid, kind string
		reg, cool     int
	}
	var list []resv
	for rows.Next() {
		var r resv
		if rows.Scan(&r.id, &r.rid, &r.kind, &r.reg, &r.cool) == nil {
			list = append(list, r)
		}
	}
	for _, r := range list {
		if r.kind == "location" {
			_, _ = app.store.pg.Exec(ctx, `UPDATE locations SET reserved_units = GREATEST(reserved_units-$2,0), cooled_reserved_units = GREATEST(cooled_reserved_units-$3,0) WHERE id=$1`, r.rid, r.reg, r.cool)
		} else {
			_, _ = app.store.pg.Exec(ctx, `UPDATE connections SET reserved_units = GREATEST(reserved_units-$2,0), cooled_reserved_units = GREATEST(cooled_reserved_units-$3,0) WHERE id=$1`, r.rid, r.reg, r.cool)
		}
		_, _ = app.store.pg.Exec(ctx, `UPDATE capacity_reservations SET active=FALSE WHERE id=$1`, r.id)
	}
}

