func (app *App) operationsState(ctx context.Context, u *SessionUser, sampleTypeFilter string) (map[string]interface{}, error) {
	now := time.Now()
	samples := []map[string]interface{}{}
	q := `SELECT id FROM samples ORDER BY created_at DESC LIMIT 500`
	rows, err := app.store.pg.Query(ctx, q)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var id string
			if rows.Scan(&id) != nil {
				continue
			}
			s, err := app.loadSample(ctx, id)
			if err != nil {
				continue
			}
			if sampleTypeFilter != "" && s.SampleTypeID != sampleTypeFilter {
				continue
			}
			item := map[string]interface{}{
				"sampleId":         s.ID,
				"status":           s.Status,
				"serviceability":   s.Serviceability,
				"currentHolderId":  ptrStr(s.CurrentHolderID),
				"locationStale":    isStale(s.LocationRecordedAt, now),
				"deliveryDeadline": rfc3339(s.Deadline),
			}
			if s.LatestLat != nil && s.LatestLng != nil {
				item["latestLocation"] = map[string]interface{}{"latitude": *s.LatestLat, "longitude": *s.LatestLng}
			}
			if s.LocationRecordedAt != nil {
				item["locationRecordedAt"] = rfc3339(*s.LocationRecordedAt)
			}
			if s.ActiveJourneyID != nil {
				item["activeJourneyId"] = *s.ActiveJourneyID
			}
			if s.TargetLabID != nil {
				item["targetLaboratoryId"] = *s.TargetLabID
			}
			if len(s.Exception) > 0 && string(s.Exception) != "null" {
				var ex interface{}
				_ = jsonUnmarshal(s.Exception, &ex)
				item["exception"] = ex
			}
			samples = append(samples, item)
		}
	}

	workers := []map[string]interface{}{}
	wrows, err := app.store.pg.Query(ctx, `
SELECT u.id, u.username, u.full_name, u.available, u.capacity_units, u.latest_lat, u.latest_lng, u.location_recorded_at,
  COALESCE((SELECT COUNT(*) FROM assignments a WHERE (a.worker_id=u.id OR a.offered_to=u.id) AND a.status NOT IN ('completed','cancelled')),0)
FROM users u
JOIN user_roles ur ON ur.user_id=u.id
WHERE ur.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team')
GROUP BY u.id`)
	if err == nil {
		defer wrows.Close()
		for wrows.Next() {
			var id, uname, fname string
			var avail bool
			var cap, load int
			var lat, lng *float64
			var rec *time.Time
			if wrows.Scan(&id, &uname, &fname, &avail, &cap, &lat, &lng, &rec, &load) != nil {
				continue
			}
			item := map[string]interface{}{
				"workerId": id, "username": uname, "fullName": fname,
				"available": avail, "capacityUnits": cap, "activeLoad": load,
				"locationStale": isStale(rec, now),
			}
			if lat != nil && lng != nil {
				item["latestLocation"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
			}
			if rec != nil {
				item["locationRecordedAt"] = rfc3339(*rec)
			}
			workers = append(workers, item)
		}
	}

	locations := []map[string]interface{}{}
	locs, _ := app.loadLocations(ctx)
	for _, l := range locs {
		if u.ActiveRole == RoleNodeHandler || u.ActiveRole == RoleLaboratoryTeam {
			if u.AssignedLocationID != l.ID {
				continue
			}
		}
		cap := Capacity{
			CapacityUnits: l.CapacityUnits, ReservedUnits: l.ReservedUnits,
			CooledCapacityUnits: l.CooledCap, CooledReservedUnits: l.CooledReserved,
		}.fill()
		item := map[string]interface{}{
			"id":              l.ID,
			"locationId":      l.ID,
			"name":            l.Name,
			"coordinate":      map[string]interface{}{"latitude": l.Lat, "longitude": l.Lng},
			"active":          l.Active,
			"coverageKm":      l.CoverageKm,
			"handlingMinutes": l.HandlingMinutes,
			"functions": LocationFunctions{
				CollectionPoint: l.FnCollection, TransferPoint: l.FnTransfer, Hub: l.FnHub, Laboratory: l.FnLaboratory,
			},
			"capacity":              cap,
			"acceptedSampleTypeIds": l.AcceptedTypes,
		}
		locations = append(locations, item)
	}

	routes := []map[string]interface{}{}
	conns, _ := app.loadConnections(ctx)
	for _, c := range conns {
		cap := Capacity{
			CapacityUnits: c.CapacityUnits, ReservedUnits: c.ReservedUnits,
			CooledCapacityUnits: c.CooledCap, CooledReservedUnits: c.CooledReserved,
		}.fill()
		routes = append(routes, map[string]interface{}{
			"connectionId": c.ID, "fromLocationId": c.FromID, "toLocationId": c.ToID,
			"travelMinutes": c.TravelMinutes, "costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active,
			"capacity": cap,
		})
	}

	exceptions := []map[string]interface{}{}
	erows, err := app.store.pg.Query(ctx, `SELECT id, sample_id, laboratory_id, reason, observed_at FROM exceptions ORDER BY observed_at DESC LIMIT 200`)
	if err == nil {
		defer erows.Close()
		for erows.Next() {
			var id, sid, reason string
			var lab *string
			var at time.Time
			if erows.Scan(&id, &sid, &lab, &reason, &at) != nil {
				continue
			}
			item := map[string]interface{}{"exceptionId": id, "sampleId": sid, "reason": reason, "observedAt": rfc3339(at)}
			if lab != nil {
				item["laboratoryId"] = *lab
			}
			exceptions = append(exceptions, item)
		}
	}

	return map[string]interface{}{
		"generatedAt": rfc3339(now),
		"samples":     samples,
		"workers":     workers,
		"locations":   locations,
		"routes":      routes,
		"exceptions":  exceptions,
	}, nil
}

func (app *App) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() && u.ActiveRole != RoleNodeHandler && u.ActiveRole != RoleLaboratoryTeam && u.ActiveRole != RoleAdministrator {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	var req struct {
		Filters struct {
			SampleTypeID  string `json:"sampleTypeId"`
			SampleTypeID2 string `json:"sample_type_id"`
		} `json:"filters"`
	}
	_ = decodeBody(body, &req)
	filter := req.Filters.SampleTypeID
	if filter == "" {
		filter = req.Filters.SampleTypeID2
	}
	data, err := app.operationsState(r.Context(), u, filter)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	writeData(w, 200, data)
}

func (app *App) handleSearchAudit(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if !u.isDispatcher() {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	body := readBody(r)
	var req struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := decodeBody(body, &req); err != nil && len(body) > 0 {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	q := queryAudit{
		Query: req.Query, ActorID: req.ActorID, EntityType: req.EntityType, EntityID: req.EntityID,
		Action: req.Action, Role: req.Role, Success: req.Success, Limit: req.Limit, Offset: req.Offset, Order: req.Order,
	}
	if req.FromTime != "" {
		t, err := parseTime(req.FromTime)
		if err != nil {
			writeErr(w, 400, "invalid_time", "invalid fromTime")
			return
		}
		q.FromTime = &t
	}
	if req.ToTime != "" {
		t, err := parseTime(req.ToTime)
		if err != nil {
			writeErr(w, 400, "invalid_time", "invalid toTime")
			return
		}
		q.ToTime = &t
	}
	res, err := app.searchAudit(r.Context(), q)
	if err != nil {
		app.handleErr(w, err)
		return
	}
	writeData(w, 200, res)
}
