   525			if st != nil && st.QualifiedCollector && !u.isDispatcher() {
   526				if !contains(u.Qualifications, st.RequiredQualification) && !hasActiveCert(u.Certifications, st.RequiredQualification) {
   527					return 0, nil, herr(403, "forbidden", "missing qualification")
   528				}
   529			}
   530			compliant := true
   531			if req.ObservedTemperatureC < s.TempMin || req.ObservedTemperatureC > s.TempMax {
   532				compliant = false
   533			}
   534			if req.ContainerType != s.ContainerType && req.ContainerType != "" && s.ContainerType != "" {
   535				// still record; may be non-compliant if type requires specific
   536				if st != nil && req.ContainerType != st.ContainerType {
   537					compliant = false
   538				}
   539			}
   540			now := at
   541			statusOut := "sealed"
   542			if !compliant {
   543				statusOut = "exception"
   544				_, _ = app.store.pg.Exec(r.Context(), `
   545	UPDATE samples SET status='exception', sealed=TRUE, sealed_at=$2, current_holder_id=$3,
   546	  exception=$4 WHERE id=$1`, s.ID, now, u.UserID, asJSON(map[string]interface{}{"reason": "handling_violation"}))
   547				_, _ = app.store.pg.Exec(r.Context(), `
   548	INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,$4)`,
   549					newUUID(), s.ID, "handling_violation", now)
   550			} else {
   551				_, _ = app.store.pg.Exec(r.Context(), `
   552	UPDATE samples SET status='sealed', sealed=TRUE, sealed_at=$2, current_holder_id=$3 WHERE id=$1`, s.ID, now, u.UserID)
   553			}
