   555	UPDATE assignments SET status='completed', completed_at=$2, worker_id=$3 WHERE id=$1`, req.AssignmentID, now, u.UserID)
   556			app.audit(r.Context(), u.UserID, u.ActiveRole, "collect_and_seal", "sample", s.ID, true, map[string]interface{}{
   557				"assignmentId": req.AssignmentID, "compliant": compliant,
   558			})
   559			app.emit("sample.sealed", "sample", s.ID, map[string]interface{}{"status": statusOut})
