   161	func (app *App) evaluateServiceability(ctx context.Context, origin Coord, originType, originNodeID, sampleTypeID string, requestedAt, deadline, earliest, latest time.Time) (*planResult, error) {
   162		st, err := app.loadSampleType(ctx, sampleTypeID)
   163		if err != nil {
   164			return nil, err
   165		}
   166		locs, err := app.loadLocations(ctx)
   167		if err != nil {
   168			return nil, err
   169		}
   170		conns, err := app.loadConnections(ctx)
   171		if err != nil {
