   354		}
   355	
   356		legs := []map[string]interface{}{}
   357		arows, err := app.store.pg.Query(ctx, `
   358	SELECT id, sample_id, sequence, status, from_location_id, to_location_id, worker_id, kind
   359	FROM assignments WHERE journey_id=$1 ORDER BY sequence, created_at`, journeyID)
   360		if err == nil {
   361			defer arows.Close()
   362			for arows.Next() {
