   310			"entityType":  et,
   311			"entity_type": et,
   312			"entityId":    eid,
   313			"entity_id":   eid,
   314			"success":     raw["success"] == true,
   315			"occurredAt":  occurredStr,
   316			"occurred_at": occurredStr,
   317			"details":     details,
   318		}
   319	}
