   626	func (app *App) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
   627		u := currentUser(r)
   628		if !u.isDispatcher() {
   629			writeErr(w, 403, "forbidden", "forbidden")
   630			return
   631		}
   632		body := readBody(r)
   633		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   634			var req struct {
   635				TargetJourneyID     string   `json:"targetJourneyId"`
   636				ExpectedPlanVersion int      `json:"expectedPlanVersion"`
   637				SourceJourneyIDs    []string `json:"sourceJourneyIds"`
   638			}
   639			if err := decodeBody(body, &req); err != nil {
   640				return 0, nil, herr(400, "invalid_json", "invalid json")
   641			}
   642			if err := app.bumpPlan(r.Context(), req.TargetJourneyID, req.ExpectedPlanVersion); err != nil {
   643				return 0, nil, err
   644			}
   645			// pulse cannot batch
   646			targetSamples := app.journeySampleIDs(r.Context(), req.TargetJourneyID)
   647			types := map[string]*sampleTypeRow{}
   648			checkPulse := func(sids []string) error {
   649				for _, sid := range sids {
   650					s, err := app.loadSample(r.Context(), sid)
   651					if err != nil {
   652						continue
   653					}
   654					st, _ := app.loadSampleType(r.Context(), s.SampleTypeID)
   655					if st != nil {
   656						types[st.ID] = st
   657						if !st.BatchingAllowed {
   658							return herr(409, "pulse_no_batch", "pulse cannot be batched")
   659						}
   660					}
   661				}
   662				return nil
   663			}
   664			if err := checkPulse(targetSamples); err != nil {
   665				return 0, nil, err
   666			}
   667			for _, src := range req.SourceJourneyIDs {
   668				sids := app.journeySampleIDs(r.Context(), src)
   669				if err := checkPulse(sids); err != nil {
   670					return 0, nil, err
   671				}
   672				// incompatibilities
   673				for _, sid := range sids {
   674					s, _ := app.loadSample(r.Context(), sid)
   675					if s == nil {
   676						continue
   677					}
   678					for _, tid := range targetSamples {
   679						t, _ := app.loadSample(r.Context(), tid)
   680						if t == nil {
   681							continue
   682						}
   683						if contains(s.Incompatible, t.SampleTypeID) || contains(t.Incompatible, s.SampleTypeID) {
   684							return 0, nil, herr(409, "incompatible_batch", "incompatible samples")
   685						}
   686					}
   687					_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.TargetJourneyID, sid)
   688					_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET active_journey_id=$2 WHERE id=$1`, sid, req.TargetJourneyID)
   689					_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET journey_id=$2 WHERE sample_id=$1 AND journey_id=$3 AND status NOT IN ('completed')`, sid, req.TargetJourneyID, src)
   690				}
   691				_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, src)
   692			}
   693			payload, err := app.journeyPlanPayload(r.Context(), req.TargetJourneyID, u.ActiveRole, u.UserID)
   694			if err != nil {
   695				return 0, nil, err
   696			}
   697			app.audit(r.Context(), u.UserID, u.ActiveRole, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]interface{}{"sources": req.SourceJourneyIDs})
   698			return 201, payload, nil
   699		})
   700	}
