   736	func (app *App) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
   737		u := currentUser(r)
   738		if !u.isDispatcher() {
   739			writeErr(w, 403, "forbidden", "forbidden")
   740			return
   741		}
   742		body := readBody(r)
   743		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   744			var req struct {
   745				JourneyID           string                 `json:"journeyId"`
   746				ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
   747				ChangeType          string                 `json:"changeType"`
   748				Changes             map[string]interface{} `json:"changes"`
   749			}
   750			if err := decodeBody(body, &req); err != nil {
   751				return 0, nil, herr(400, "invalid_json", "invalid json")
   752			}
   753			valid := map[string]bool{
   754				"add_stop": true, "remove_stop": true, "reorder_stops": true, "replace_worker": true,
   755				"reassign_worker": true, "merge_samples": true, "split_samples": true, "split_batch": true,
   756				"cancel_work": true, "reroute": true, "replace_route": true,
   757			}
   758			if !valid[req.ChangeType] {
   759				return 0, nil, herr(400, "invalid_change_type", "invalid change type")
   760			}
   761			if err := app.bumpPlan(r.Context(), req.JourneyID, req.ExpectedPlanVersion); err != nil {
   762				return 0, nil, err
   763			}
   764			switch req.ChangeType {
   765			case "cancel_work":
   766				_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, req.JourneyID)
   767				_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
   768			case "reroute", "replace_route":
   769				_, _, _ = app.replanJourney(r.Context(), u, req.JourneyID)
   770			case "replace_worker", "reassign_worker":
   771				if wid, _ := req.Changes["workerId"].(string); wid != "" {
   772					if aid, _ := req.Changes["assignmentId"].(string); aid != "" {
   773						_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET worker_id=$2, offered_to=$2, status='offered' WHERE id=$1 AND status NOT IN ('completed','cancelled')`, aid, wid)
   774					}
   775				}
   776			}
   777			payload, err := app.journeyPlanPayload(r.Context(), req.JourneyID, u.ActiveRole, u.UserID)
   778			if err != nil {
   779				return 0, nil, err
   780			}
   781			app.audit(r.Context(), u.UserID, u.ActiveRole, "edit_active_plan", "journey", req.JourneyID, true, map[string]interface{}{"changeType": req.ChangeType})
   782			return 201, payload, nil
   783		})
   784	}
