import json
from pathlib import Path
d=json.loads(Path('/workspace/contracts/openapi.contract.json').read_text())
s=d['components']['schemas']
print('ALL SCHEMAS:', sorted(s.keys()))
print()
# dump remaining important schemas
for name in sorted(s.keys()):
    sch=s[name]
    print(f'--- {name} type={sch.get("type")} required={sch.get("required")} addProps={sch.get("additionalProperties")} ---')
    if 'properties' in sch:
        for k,v in sch['properties'].items():
            extra=''
            if isinstance(v, dict):
                if '$ref' in v: extra=v['$ref']
                elif v.get('type')=='array': extra='[] '+str(v.get('items',{}))[:80]
                elif 'enum' in v: extra='enum '+str(v['enum'])
                else: extra=v.get('type','')
            print(f'    {k}: {extra}')
    if 'allOf' in sch:
        print('  allOf', json.dumps(sch['allOf'])[:300])
    if 'oneOf' in sch:
        print('  oneOf', json.dumps(sch['oneOf'])[:400])
    if 'anyOf' in sch:
        print('  anyOf', json.dumps(sch['anyOf'])[:400])

print('\n\n======== RESPONSE SCHEMAS PER PATH ========')
for p, methods in sorted(d['paths'].items()):
    for m, op in methods.items():
        if not isinstance(op, dict): continue
        oid=op.get('operationId')
        print(f'\n{m.upper()} {p}  ({oid})')
        for code, resp in op.get('responses',{}).items():
            content=resp.get('content',{})
            js=content.get('application/json',{}).get('schema',{})
            if '$ref' in js:
                print(f'  {code}: {js["$ref"]}')
            elif js.get('properties'):
                print(f'  {code}: props={list(js.get("properties",{}).keys())} req={js.get("required")} add={js.get("additionalProperties")}')
                data=js.get('properties',{}).get('data',{})
                if '$ref' in data:
                    print(f'       data -> {data["$ref"]}')
                elif data.get('properties'):
                    print(f'       data props={list(data["properties"].keys())} req={data.get("required")} add={data.get("additionalProperties")}')
            else:
                print(f'  {code}: {json.dumps(js)[:200]}')
