    26		pending, inProg, completed := app.roleWork(r.Context(), u, role)
    27		if req.Status != "" {
    28			switch req.Status {
    29			case "pending":
    30				inProg, completed = []map[string]interface{}{}, []map[string]interface{}{}
    31			case "in_progress", "accepted", "inProgress":
    32				pending, completed = []map[string]interface{}{}, []map[string]interface{}{}
    33			case "completed", "past":
    34				pending, inProg = []map[string]interface{}{}, []map[string]interface{}{}
    35			}
    36		}
    37		writeData(w, 200, map[string]interface{}{
    38			"role":      role,
    39			"pending":   pending,
    40			"inProgress": inProg,
    41			"completed": completed,
