   580	func (app *App) bumpPlan(ctx context.Context, journeyID string, expected int) error {
   581		var ver int
   582		var status string
   583		err := app.store.pg.QueryRow(ctx, `SELECT plan_version, status FROM journeys WHERE id=$1`, journeyID).Scan(&ver, &status)
