   783				plan, _ := app.journeyPlanPayload(r.Context(), replacement, u.ActiveRole, u.UserID)
   784				out["replacementJourney"] = plan
   785			}
   786			app.audit(r.Context(), u.UserID, u.ActiveRole, "reroute_journey", "journey", req.JourneyID, true, map[string]interface{}{"status": status})
