   791	func (app *App) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
   792		u := currentUser(r)
   793		if !u.isDispatcher() {
   794			writeErr(w, 403, "forbidden", "forbidden")
   795			return
   796		}
   797		body := readBody(r)
   798		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   799			var req struct {
   800				JourneyID           string                 `json:"journeyId"`
   801				ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
   802				ChangeType          string                 `json:"changeType"`
   803				Changes             map[string]interface{} `json:"changes"`
   804			}
   805			if err := decodeBody(body, &req); err != nil {
   806				return 0, nil, herr(400, "invalid_json", "invalid json")
   807			}
   808			valid := map[string]bool{
   809				"add_stop": true, "remove_stop": true, "reorder_stops": true, "replace_worker": true,
   810				"reassign_worker": true, "merge_samples": true, "split_samples": true, "split_batch": true,
   811				"cancel_work": true, "reroute": true, "replace_route": true,
   812			}
   813			if !valid[req.ChangeType] {
   814				return 0, nil, herr(400, "invalid_change_type", "invalid change type")
   815			}
   816			if err := app.bumpPlan(r.Context(), req.JourneyID, req.ExpectedPlanVersion); err != nil {
   817				return 0, nil, err
   818			}
   819			switch req.ChangeType {
   820			case "cancel_work":
   821				_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, req.JourneyID)
   822				_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
   823			case "reroute", "replace_route":
   824				_, _, _ = app.replanJourney(r.Context(), u, req.JourneyID)
   825			case "replace_worker", "reassign_worker":
   826				if wid, _ := req.Changes["workerId"].(string); wid != "" {
   827					if aid, _ := req.Changes["assignmentId"].(string); aid != "" {
   828						_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET worker_id=$2, offered_to=$2, status='offered' WHERE id=$1 AND status NOT IN ('completed','cancelled')`, aid, wid)
   829					}
   830				}
   831			}
   832			payload, err := app.journeyPlanPayload(r.Context(), req.JourneyID, u.ActiveRole, u.UserID)
   833			if err != nil {
   834				return 0, nil, err
   835			}
