   161	  requires_cooled_route, batching_allowed)
   162	VALUES ($1,$2,TRUE,$3,$4,$5,$6,$7,$8,$9)
   163	ON CONFLICT (id) DO NOTHING
   164	`, d.id, d.name, d.qual, d.container, d.tmin, d.tmax, incompat, d.cooled, d.batch)
   165			if err != nil {
