    27	func (app *App) parseCollectionBody(body []byte) (collectionReqBody, time.Time, time.Time, time.Time, time.Time, error) {
    28		var req collectionReqBody
    29		if err := decodeBody(body, &req); err != nil {
    30			return req, time.Time{}, time.Time{}, time.Time{}, time.Time{}, herr(400, "invalid_json", "invalid json")
    31		}
    32		if req.SampleTypeID == "" || req.ContainerType == "" {
    33			return req, time.Time{}, time.Time{}, time.Time{}, time.Time{}, herr(400, "invalid_json", "required fields missing")
    34		}
    35		if req.OriginType == "" {
    36			req.OriginType = "home"
    37		}
    38		reqAt, err := parseTime(req.RequestedAt)
    39		if err != nil {
    40			return req, time.Time{}, time.Time{}, time.Time{}, time.Time{}, herr(400, "invalid_time", "invalid requestedAt")
    41		}
    42		dead, err := parseTime(req.DeliveryDeadline)
    43		if err != nil {
    44			return req, time.Time{}, time.Time{}, time.Time{}, time.Time{}, herr(400, "invalid_deadline", "invalid deliveryDeadline")
    45		}
    46		earliest := reqAt
    47		latest := dead
    48		if req.EarliestCollectionAt != "" {
    49			earliest, err = parseTime(req.EarliestCollectionAt)
    50			if err != nil {
    51				return req, time.Time{}, time.Time{}, time.Time{}, time.Time{}, herr(400, "invalid_collection_window", "invalid earliestCollectionAt")
    52			}
    53		}
    54		if req.LatestCollectionAt != "" {
    55			latest, err = parseTime(req.LatestCollectionAt)
    56			if err != nil {
    57				return req, time.Time{}, time.Time{}, time.Time{}, time.Time{}, herr(400, "invalid_collection_window", "invalid latestCollectionAt")
    58			}
    59		}
    60		if latest.Before(earliest) {
    61			return req, time.Time{}, time.Time{}, time.Time{}, time.Time{}, herr(400, "invalid_collection_window", "collection window inverted")
    62		}
    63		if req.IncompatibleSampleTypes == nil {
    64			req.IncompatibleSampleTypes = []string{}
    65		}
    66		return req, reqAt, dead, earliest, latest, nil
    67	}
