   487	func (app *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
   488		u := currentUser(r)
   489		body := readBody(r)
   490		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   491			var req struct {
   492				HandoffID         string `json:"handoffId"`
   493				ConfirmationSide  string `json:"confirmationSide"`
   494				ConfirmedAt       string `json:"confirmedAt"`
   495			}
   496			if err := decodeBody(body, &req); err != nil {
   497				return 0, nil, herr(400, "invalid_json", "invalid json")
   498			}
   499			if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
   500				return 0, nil, herr(400, "invalid_json", "invalid confirmationSide")
   501			}
   502			at, err := parseTime(req.ConfirmedAt)
   503			if err != nil {
   504				return 0, nil, herr(400, "invalid_time", "invalid confirmedAt")
   505			}
   506			var sampleID, sender, receiver, status string
   507			var sConf, rConf bool
   508			err = app.store.pg.QueryRow(r.Context(), `
   509	SELECT sample_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed
   510	FROM handoffs WHERE id=$1`, req.HandoffID).Scan(&sampleID, &sender, &receiver, &status, &sConf, &rConf)
   511			if err != nil {
   512				return 0, nil, herr(404, "not_found", "handoff not found")
   513			}
   514			if req.ConfirmationSide == "sender" {
   515				if !u.isDispatcher() && u.UserID != sender {
   516					return 0, nil, herr(403, "forbidden", "not sender")
   517				}
   518				sConf = true
   519				_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=TRUE WHERE id=$1`, req.HandoffID)
   520			} else {
   521				if !u.isDispatcher() && u.UserID != receiver {
   522					return 0, nil, herr(403, "forbidden", "not receiver")
   523				}
   524				rConf = true
   525				_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET receiver_confirmed=TRUE WHERE id=$1`, req.HandoffID)
   526			}
   527			holder := sender
   528			st := "pending"
   529			if sConf && rConf {
   530				st = "confirmed"
   531				holder = receiver
   532				_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET status='confirmed', completed_at=$2 WHERE id=$1`, req.HandoffID, at)
   533				_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET current_holder_id=$2 WHERE id=$1`, sampleID, receiver)
   534			}
   535			app.audit(r.Context(), u.UserID, u.ActiveRole, "confirm_handoff", "handoff", req.HandoffID, true, map[string]interface{}{"side": req.ConfirmationSide})
   536			return 201, map[string]interface{}{
   537				"handoffId":          req.HandoffID,
   538				"status":             st,
   539				"senderConfirmed":    sConf,
   540				"receiverConfirmed":  rConf,
   541				"currentHolderId":    holder,
   542			}, nil
   543		})
   544	}
