   218	func hashPassword(p string) (string, error) {
   219		b, err := bcrypt.GenerateFromPassword([]byte(p), bcrypt.DefaultCost)
   220		return string(b), err
   221	}
   222	
   223	func checkPassword(hash, p string) bool {
   224		return bcrypt.CompareHashAndPassword([]byte(hash), []byte(p)) == nil
   225	}
