   295	func (app *App) withIdem(w http.ResponseWriter, r *http.Request, body []byte, required bool, fn func() (int, interface{}, error)) {
   296		u := currentUser(r)
   297		key := idemKeyFrom(body)
   298		if required && key == "" {
   299			writeErr(w, 400, "idempotency_required", "idempotency key required")
   300			return
   301		}
   302		if key != "" {
   303			var existingUser string
   304			var existingStatus int
   305			var existing []byte
   306			err := app.store.pg.QueryRow(r.Context(), `SELECT user_id::text, status_code, response FROM idempotency WHERE key=$1`, key).
   307				Scan(&existingUser, &existingStatus, &existing)
   308			if err == nil {
   309				if existingUser != u.UserID {
   310					writeErr(w, 409, "idempotency_conflict", "idempotency conflict")
   311					return
   312				}
   313				w.Header().Set("Content-Type", "application/json")
   314				w.WriteHeader(existingStatus)
   315				_, _ = w.Write(existing)
   316				return
   317			}
   318		}
   319		status, payload, e := fn()
   320		if e != nil {
   321			app.handleErr(w, e)
   322			return
   323		}
   324		bodyOut, _ := json.Marshal(map[string]interface{}{"data": payload})
   325		if key != "" {
   326			_, _ = app.store.pg.Exec(r.Context(), `
   327	INSERT INTO idempotency (key, user_id, request_hash, status_code, response)
   328	VALUES ($1,$2,'', $3, $4) ON CONFLICT (key) DO NOTHING`, key, u.UserID, status, bodyOut)
   329		}
   330		w.Header().Set("Content-Type", "application/json")
   331		w.WriteHeader(status)
   332		_, _ = w.Write(bodyOut)
   333	}
