   689	func (app *App) replanJourney(ctx context.Context, u *SessionUser, journeyID string) (string, string, error) {
   690		sids := app.journeySampleIDs(ctx, journeyID)
   691		if len(sids) == 0 {
   692			return "not_required", "", nil
   693		}
   694		// cancel unfinished assignments, keep completed
   695		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
   696		app.releaseJourneyCapacity(ctx, journeyID)
   697		_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced' WHERE id=$1`, journeyID)
   698	
   699		// replan first unfinished sample (and attach others if possible)
   700		var lastStatus, lastID string
   701		for _, sid := range sids {
   702			s, err := app.loadSample(ctx, sid)
   703			if err != nil || s.Status == "received" || s.Status == "cancelled" {
   704				continue
   705			}
   706			st, _ := app.loadSampleType(ctx, s.SampleTypeID)
   707			plan, err := app.evaluateServiceability(ctx, Coord{s.OriginLat, s.OriginLng}, s.OriginType, "", s.SampleTypeID, time.Now(), s.Deadline, s.Earliest, s.Latest)
   708			if err != nil || !plan.Serviceable {
   709				reason := "no_valid_route"
   710				status := "exception"
   711				if plan != nil && plan.Reason == "deadline_unreachable" {
   712					status = "expired"
   713					reason = "deadline_unreachable"
   714				}
   715				_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status=$2, exception=$3 WHERE id=$1`, sid, status, asJSON(map[string]interface{}{"reason": reason}))
   716				if status == "expired" {
   717					lastStatus = "expired"
   718				} else {
   719					lastStatus = "exception"
   720				}
   721				continue
   722			}
   723			req := collectionReqBody{
   724				Origin: Coord{s.OriginLat, s.OriginLng}, OriginType: s.OriginType, SampleTypeID: s.SampleTypeID,
   725				ContainerType: s.ContainerType, TemperatureMinC: s.TempMin, TemperatureMaxC: s.TempMax,
   726			}
   727			jid, _, err := app.materializeJourney(ctx, u, sid, req, plan, st, s.Sealed, time.Now())
   728			if err != nil {
   729				lastStatus = "exception"
   730				continue
   731			}
   732			_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2 WHERE id=$1`, jid, journeyID)
   733			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE id=$1`, sid, jid, plan.TargetLab)
   734			lastStatus = "replaced"
   735			lastID = jid
   736		}
   737		if lastStatus == "" {
   738			lastStatus = "not_required"
   739		}
   740		return lastStatus, lastID, nil
   741	}
