   761	func (app *App) offerOne(ctx context.Context, assignmentID string) string {
   762		var kind string
   763		var sampleID, nodeID, labID *string
   764		var expected *string
   765		err := app.store.pg.QueryRow(ctx, `SELECT kind, sample_id, node_id, laboratory_id, expected_sample_type_id FROM assignments WHERE id=$1`, assignmentID).
   766			Scan(&kind, &sampleID, &nodeID, &labID, &expected)
   767		if err != nil {
   768			return ""
   769		}
   770		role := RoleDeliveryPartner
   771		switch kind {
   772		case "collection":
   773			role = RoleCollectionProfessional
   774		case "node":
   775			role = RoleNodeHandler
   776		case "laboratory":
   777			role = RoleLaboratoryTeam
   778		}
   779		q := `
   780	SELECT u.id FROM users u
   781	JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
   782	WHERE u.active=TRUE AND u.available=TRUE
   783	  AND (u.decline_penalty_until IS NULL OR u.decline_penalty_until < now())
   784	`
   785		args := []interface{}{role}
   786		if (kind == "node" || kind == "laboratory") && (nodeID != nil || labID != nil) {
   787			loc := ""
   788			if nodeID != nil {
   789				loc = *nodeID
   790			}
   791			if labID != nil {
   792				loc = *labID
   793			}
   794			q += ` AND u.assigned_location_id=$2`
   795			args = append(args, loc)
   796		}
   797		q += ` ORDER BY COALESCE(u.last_offered_at, to_timestamp(0)) ASC, COALESCE(u.last_assigned_at, to_timestamp(0)) ASC,
   798	  (SELECT COUNT(*) FROM assignments a WHERE a.worker_id=u.id AND a.status NOT IN ('completed','cancelled')) ASC
   799	LIMIT 5`
   800		wrows, err := app.store.pg.Query(ctx, q, args...)
   801		if err != nil {
   802			return ""
   803		}
   804		defer wrows.Close()
   805		var candidates []string
   806		for wrows.Next() {
   807			var id string
   808			if wrows.Scan(&id) == nil {
   809				candidates = append(candidates, id)
   810			}
   811		}
   812		if len(candidates) == 0 {
   813			if kind == "collection" && expected != nil {
   814				// no qualified collector — flag after timeout; we flag immediately only if never anyone
   815				var n int
   816				_ = app.store.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1 WHERE u.active`, RoleCollectionProfessional).Scan(&n)
   817				if n == 0 && sampleID != nil {
   818					_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`,
   819						*sampleID, asJSON(map[string]interface{}{"reason": "no_qualified_worker"}))
   820					_, _ = app.store.pg.Exec(ctx, `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,now())`,
   821						newUUID(), *sampleID, "no_qualified_worker")
   822				}
   823			}
   824			return ""
   825		}
   826		// qualification filter for collection
   827		chosen := candidates[0]
   828		if kind == "collection" && expected != nil {
   829			st, _ := app.loadSampleType(ctx, *expected)
   830			if st != nil && st.QualifiedCollector {
   831				found := ""
   832				for _, cid := range candidates {
   833					wu, err := app.loadUser(ctx, cid, "")
   834					if err != nil {
   835						continue
   836					}
   837					if contains(wu.Qualifications, st.RequiredQualification) || hasActiveCert(wu.Certifications, st.RequiredQualification) {
   838						found = cid
   839						break
   840					}
   841				}
   842				if found == "" {
   843					if sampleID != nil {
   844						// leave pending; background will eventually exception
   845					}
   846					return ""
   847				}
   848				chosen = found
   849			}
   850		}
   851		exp := time.Now().Add(offerTTL)
   852		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3 WHERE id=$1`, assignmentID, chosen, exp)
   853		_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=now() WHERE id=$1`, chosen)
   854		app.emit("assignment.offered", "assignment", assignmentID, map[string]interface{}{"workerId": chosen})
   855		return chosen
   856	}
