   163	func formatUUID(b [16]byte) string {
   164		const hex = "0123456789abcdef"
   165		buf := make([]byte, 36)
   166		j := 0
   167		for i, v := range b {
   168			if i == 4 || i == 6 || i == 8 || i == 10 {
   169				buf[j] = '-'
   170				j++
   171			}
   172			buf[j] = hex[v>>4]
   173			buf[j+1] = hex[v&0x0f]
   174			j += 2
   175		}
   176		return string(buf)
   177	}
