   232		// prefer labs that explicitly accept
   233		explicit := []locRow{}
   234		for _, l := range labs {
   235			if contains(l.AcceptedTypes, st.ID) {
   236				explicit = append(explicit, l)
   237			}
   238		}
   239		if len(explicit) > 0 {
   240			labs = explicit
   241		}
   242		if len(labs) == 0 {
   243			res.Reason = "no_accepting_laboratory"
   244			return res
   245		}
   246	
   247		type cand struct {
   248			lab   locRow
   249			path  []string
   250			mins  int
   251			cost  float64
   252			hmin  int
   253		}
   254		var best *cand
   255		for _, lab := range labs {
   256			path, mins, cost, ok := shortestPath(locs, conns, start.ID, lab.ID, st.RequiresCooled)
   257			if !ok {
   258				continue
   259			}
   260			hmin := 0
   261			for _, id := range path {
   262				if l := locByID(locs, id); l != nil {
   263					hmin += l.HandlingMinutes
   264				}
   265			}
   266			c := cand{lab: lab, path: path, mins: mins, cost: cost, hmin: hmin}
   267			if best == nil || c.mins < best.mins || (c.mins == best.mins && c.cost < best.cost) {
   268				cp := c
   269				best = &cp
   270			}
   271		}
   272		if best == nil {
   273			res.Reason = "no_route"
   274			return res
   275		}
   276	
   277		// capacity along path
   278		for i := 0; i+1 < len(best.path); i++ {
   279			c := findConn(conns, best.path[i], best.path[i+1])
   280			if c == nil {
   281				res.Reason = "no_route"
   282				return res
   283			}
   284			if st.RequiresCooled {
   285				if c.CooledCap-c.CooledReserved < 1 && c.CooledCap > 0 {
   286					res.Reason = "insufficient_capacity"
   287					return res
   288				}
   289			} else if c.CapacityUnits > 0 && c.CapacityUnits-c.ReservedUnits < 1 {
   290				res.Reason = "insufficient_capacity"
   291				return res
   292			}
   293		}
   294		for _, id := range best.path {
   295			l := locByID(locs, id)
   296			if l == nil {
   297				continue
   298			}
   299			if st.RequiresCooled {
   300				if l.CooledCap > 0 && l.CooledCap-l.CooledReserved < 1 {
   301					res.Reason = "insufficient_capacity"
   302					return res
   303				}
   304			} else if l.CapacityUnits > 0 && l.CapacityUnits-l.ReservedUnits < 1 {
   305				res.Reason = "insufficient_capacity"
   306				return res
   307			}
   308		}
   309	
   310		startAt := requestedAt
   311		if !earliest.IsZero() && earliest.After(startAt) {
   312			startAt = earliest
   313		}
   314		arrival := startAt.Add(time.Duration(res.CollectionTravelMin+best.mins+best.hmin) * time.Minute)
   315		if !deadline.IsZero() && arrival.After(deadline) {
   316			res.Reason = "deadline_unreachable"
   317			res.TargetLab = best.lab.ID
   318			res.EstimatedArrival = arrival
   319			res.Path = best.path
   320			return res
   321		}
   322	
   323		res.Serviceable = true
   324		res.Reason = "serviceable"
   325		res.TargetLab = best.lab.ID
   326		res.EstimatedArrival = arrival
   327		res.Path = best.path
   328		res.TravelMinutes = best.mins
   329		res.HandlingMinutes = best.hmin
   330		res.TotalCost = best.cost
   331		return res
   332	}
   333	
   334	func findConn(conns []connRow, from, to string) *connRow {
   335		for i := range conns {
   336			if conns[i].FromID == from && conns[i].ToID == to && conns[i].Active {
   337				return &conns[i]
   338			}
   339		}
   340		return nil
   341	}
   342	
   343	func shortestPath(locs []locRow, conns []connRow, from, to string, needCooled bool) ([]string, int, float64, bool) {
   344		if from == to {
   345			return []string{from}, 0, 0, true
   346		}
   347		type node struct {
   348			id   string
   349			mins int
   350			cost float64
   351			prev string
   352		}
   353		dist := map[string]int{}
   354		cost := map[string]float64{}
   355		prev := map[string]string{}
   356		for _, l := range locs {
   357			dist[l.ID] = math.MaxInt32
   358		}
   359		dist[from] = 0
   360		type item struct {
   361			id   string
   362			mins int
   363		}
   364		q := []item{{from, 0}}
   365		for len(q) > 0 {
   366			sort.Slice(q, func(i, j int) bool { return q[i].mins < q[j].mins })
   367			cur := q[0]
   368			q = q[1:]
   369			if cur.mins != dist[cur.id] {
   370				continue
   371			}
   372			if cur.id == to {
   373				break
   374			}
   375			for _, c := range conns {
   376				if !c.Active || c.FromID != cur.id {
   377					continue
   378				}
   379				if needCooled && !c.Cooled {
   380					continue
   381				}
   382				nm := cur.mins + c.TravelMinutes
   383				if nm < dist[c.ToID] {
   384					dist[c.ToID] = nm
   385					cost[c.ToID] = cost[cur.id] + c.CostUnits
   386					prev[c.ToID] = cur.id
   387					q = append(q, item{c.ToID, nm})
   388				}
   389			}
   390		}
   391		if dist[to] == math.MaxInt32 {
   392			return nil, 0, 0, false
   393		}
   394		path := []string{to}
   395		for path[0] != from {
   396			p, ok := prev[path[0]]
   397			if !ok {
   398				return nil, 0, 0, false
   399			}
   400			path = append([]string{p}, path...)
   401		}
   402		return path, dist[to], cost[to], true
   403	}
   404	
   405	func (app *App) bumpNetwork(ctx context.Context) {
   406		_, _ = app.store.pg.Exec(ctx, `UPDATE network_meta SET revision = revision + 1, updated_at=now() WHERE id=1`)
   407		go app.recomputeServiceability()
   408	}
   409	
   410	func (app *App) recomputeServiceability() {
   411		app.store.mu.Lock()
   412		if app.store.svcComputing {
   413			app.store.mu.Unlock()
   414			return
   415		}
   416		app.store.svcComputing = true
   417		app.store.mu.Unlock()
   418		defer func() {
   419			app.store.mu.Lock()
   420			app.store.svcComputing = false
   421			app.store.mu.Unlock()
   422		}()
   423	
   424		ctx := context.Background()
   425		var rev int
   426		_ = app.store.pg.QueryRow(ctx, `SELECT revision FROM network_meta WHERE id=1`).Scan(&rev)
   427		locs, err := app.loadLocations(ctx)
   428		if err != nil {
   429			return
   430		}
   431		regions := []map[string]interface{}{}
   432		count := 0
   433		for _, l := range locs {
   434			if l.Active && l.FnCollection {
   435				count++
   436				cov := l.CoverageKm
   437				if cov <= 0 {
   438					cov = 5
   439				}
   440				regions = append(regions, map[string]interface{}{
   441					"locationId": l.ID,
   442					"name":       l.Name,
   443					"latitude":   l.Lat,
   444					"longitude":  l.Lng,
   445					"coverageKm": cov,
   446				})
   447			}
   448		}
   449		var ver int
   450		_ = app.store.pg.QueryRow(ctx, `SELECT COALESCE(MAX(version),0)+1 FROM serviceability_snapshots`).Scan(&ver)
   451		if ver < 1 {
   452			ver = 1
   453		}
   454		now := time.Now().UTC()
   455		_, err = app.store.pg.Exec(ctx, `
   456	INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
   457	VALUES ($1,'complete',$2,$3,$4,$5)`, ver, now, rev, asJSON(regions), count)
   458		if err != nil {
   459			return
   460		}
   461		app.store.mu.Lock()
   462		app.store.svcVersion = ver
   463		app.store.svcComputed = now
   464		app.store.svcRevision = rev
   465		app.store.mu.Unlock()
   466	}
   467	
   468	func (app *App) currentServiceability(ctx context.Context) (int, time.Time, int, []map[string]interface{}, int, error) {
   469		var ver, rev, count int
   470		var computed time.Time
   471		var raw []byte
   472		err := app.store.pg.QueryRow(ctx, `
   473	SELECT version, computed_at, network_revision, regions, active_collection_point_count
   474	FROM serviceability_snapshots WHERE status='complete' ORDER BY version DESC LIMIT 1`).
   475			Scan(&ver, &computed, &rev, &raw, &count)
   476		if err != nil {
   477			return 1, time.Now().UTC(), 0, []map[string]interface{}{}, 0, nil
   478		}
   479		regions := []map[string]interface{}{}
   480		_ = jsonUnmarshal(raw, &regions)
   481		if regions == nil {
   482			regions = []map[string]interface{}{}
   483		}
   484		return ver, computed, rev, regions, count, nil
   485	}
   486	
   487	func jsonUnmarshal(b []byte, v interface{}) error {
   488		if len(b) == 0 {
   489			return nil
   490		}
   491		return json.Unmarshal(b, v)
   492	}

