   430	func (app *App) replanJourney(ctx context.Context, u *SessionUser, journeyID string) (string, string, error) {
   431		sids := app.journeySampleIDs(ctx, journeyID)
   432		if len(sids) == 0 {
   433			return "not_required", "", nil
   434		}
   435		// cancel unfinished assignments, keep completed
   436		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
   437		app.releaseJourneyCapacity(ctx, journeyID)
   438		_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced' WHERE id=$1`, journeyID)
   439	
   440		// replan first unfinished sample (and attach others if possible)
   441		var lastStatus, lastID string
   442		for _, sid := range sids {
   443			s, err := app.loadSample(ctx, sid)
   444			if err != nil || s.Status == "received" || s.Status == "cancelled" {
   445				continue
   446			}
   447			st, _ := app.loadSampleType(ctx, s.SampleTypeID)
   448			plan, err := app.evaluateServiceability(ctx, Coord{s.OriginLat, s.OriginLng}, s.OriginType, "", s.SampleTypeID, time.Now(), s.Deadline, s.Earliest, s.Latest)
   449			if err != nil || !plan.Serviceable {
   450				reason := "no_valid_route"
   451				status := "exception"
   452				if plan != nil && plan.Reason == "deadline_unreachable" {
   453					status = "expired"
   454					reason = "deadline_unreachable"
   455				}
   456				_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status=$2, exception=$3 WHERE id=$1`, sid, status, asJSON(map[string]interface{}{"reason": reason}))
   457				if status == "expired" {
   458					lastStatus = "expired"
   459				} else {
   460					lastStatus = "exception"
   461				}
   462				continue
   463			}
   464			req := collectionReqBody{
   465				Origin: Coord{s.OriginLat, s.OriginLng}, OriginType: s.OriginType, SampleTypeID: s.SampleTypeID,
   466				ContainerType: s.ContainerType, TemperatureMinC: s.TempMin, TemperatureMaxC: s.TempMax,
   467			}
   468			jid, _, err := app.materializeJourney(ctx, u, sid, req, plan, st, s.Sealed, time.Now())
   469			if err != nil {
   470				lastStatus = "exception"
   471				continue
   472			}
   473			_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2 WHERE id=$1`, jid, journeyID)
   474			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE id=$1`, sid, jid, plan.TargetLab)
   475			lastStatus = "replaced"
   476			lastID = jid
   477		}
   478		if lastStatus == "" {
   479			lastStatus = "not_required"
   480		}
   481		return lastStatus, lastID, nil
   482	}
