   502	func (app *App) offerOne(ctx context.Context, assignmentID string) string {
   503		var kind string
   504		var sampleID, nodeID, labID *string
   505		var expected *string
   506		err := app.store.pg.QueryRow(ctx, `SELECT kind, sample_id, node_id, laboratory_id, expected_sample_type_id FROM assignments WHERE id=$1`, assignmentID).
   507			Scan(&kind, &sampleID, &nodeID, &labID, &expected)
   508		if err != nil {
   509			return ""
   510		}
   511		role := RoleDeliveryPartner
   512		switch kind {
   513		case "collection":
   514			role = RoleCollectionProfessional
   515		case "node":
   516			role = RoleNodeHandler
   517		case "laboratory":
   518			role = RoleLaboratoryTeam
   519		}
   520		q := `
   521	SELECT u.id FROM users u
   522	JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
   523	WHERE u.active=TRUE AND u.available=TRUE
   524	  AND (u.decline_penalty_until IS NULL OR u.decline_penalty_until < now())
   525	`
   526		args := []interface{}{role}
   527		if (kind == "node" || kind == "laboratory") && (nodeID != nil || labID != nil) {
   528			loc := ""
   529			if nodeID != nil {
   530				loc = *nodeID
   531			}
   532			if labID != nil {
   533				loc = *labID
   534			}
   535			q += ` AND u.assigned_location_id=$2`
   536			args = append(args, loc)
   537		}
   538		q += ` ORDER BY COALESCE(u.last_offered_at, to_timestamp(0)) ASC, COALESCE(u.last_assigned_at, to_timestamp(0)) ASC,
   539	  (SELECT COUNT(*) FROM assignments a WHERE a.worker_id=u.id AND a.status NOT IN ('completed','cancelled')) ASC
   540	LIMIT 5`
   541		wrows, err := app.store.pg.Query(ctx, q, args...)
   542		if err != nil {
   543			return ""
   544		}
   545		defer wrows.Close()
   546		var candidates []string
   547		for wrows.Next() {
   548			var id string
   549			if wrows.Scan(&id) == nil {
   550				candidates = append(candidates, id)
   551			}
   552		}
   553		if len(candidates) == 0 {
   554			if kind == "collection" && expected != nil {
   555				// no qualified collector — flag after timeout; we flag immediately only if never anyone
   556				var n int
   557				_ = app.store.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1 WHERE u.active`, RoleCollectionProfessional).Scan(&n)
   558				if n == 0 && sampleID != nil {
   559					_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`,
   560						*sampleID, asJSON(map[string]interface{}{"reason": "no_qualified_worker"}))
   561					_, _ = app.store.pg.Exec(ctx, `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,now())`,
   562						newUUID(), *sampleID, "no_qualified_worker")
   563				}
   564			}
   565			return ""
   566		}
   567		// qualification filter for collection
   568		chosen := candidates[0]
   569		if kind == "collection" && expected != nil {
   570			st, _ := app.loadSampleType(ctx, *expected)
   571			if st != nil && st.QualifiedCollector {
   572				found := ""
   573				for _, cid := range candidates {
   574					wu, err := app.loadUser(ctx, cid, "")
   575					if err != nil {
   576						continue
   577					}
   578					if contains(wu.Qualifications, st.RequiredQualification) || hasActiveCert(wu.Certifications, st.RequiredQualification) {
   579						found = cid
   580						break
   581					}
   582				}
   583				if found == "" {
   584					if sampleID != nil {
   585						// leave pending; background will eventually exception
   586					}
   587					return ""
   588				}
   589				chosen = found
   590			}
   591		}
   592		exp := time.Now().Add(offerTTL)
   593		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3 WHERE id=$1`, assignmentID, chosen, exp)
   594		_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=now() WHERE id=$1`, chosen)
   595		app.emit("assignment.offered", "assignment", assignmentID, map[string]interface{}{"workerId": chosen})
   596		return chosen
   597	}
