   602			app.handleWS(w, r, u)
   603			return
   604		}
   605		since := int64(0)
   606		if s := r.URL.Query().Get("since"); s != "" {
   607			var n int64
   608			if _, err := parseInt64(s, &n); err == nil {
   609				since = n
   610			}
   611		}
   612		rows, err := app.store.pg.Query(r.Context(), `
   613	SELECT id, type, entity_type, entity_id, payload, created_at
   614	FROM realtime_events WHERE id > $1 ORDER BY id ASC LIMIT 200`, since)
   615		if err != nil {
   616			writeErr(w, 500, "internal_error", "internal error")
   617			return
   618		}
   619		defer rows.Close()
   620		events := []map[string]interface{}{}
   621		var cursor int64 = since
   622		for rows.Next() {
   623			var id int64
   624			var typ, et, eid string
   625			var payload []byte
   626			var created time.Time
   627			if rows.Scan(&id, &typ, &et, &eid, &payload, &created) != nil {
   628				continue
   629			}
   630			var p map[string]interface{}
   631			_ = json.Unmarshal(payload, &p)
   632			if p == nil {
   633				p = map[string]interface{}{}
   634			}
   635			events = append(events, map[string]interface{}{
   636				"id": id, "type": typ, "entityType": et, "entityId": eid, "payload": p, "createdAt": rfc3339(created),
   637			})
   638			cursor = id
   639		}
   640		writeData(w, 200, map[string]interface{}{"events": events, "cursor": cursor})
   641	}
