   643	func parseInt64(s string, out *int64) (int, error) {
   644		var n int64
   645		for _, c := range s {
   646			if c < '0' || c > '9' {
   647				return 0, herr(400, "invalid_json", "invalid since")
   648			}
   649			n = n*10 + int64(c-'0')
   650		}
   651		*out = n
   652		return 0, nil
   653	}

