   526			}
   527			holder := sender
   528			st := "pending"
   529			if sConf && rConf {
   530				st = "confirmed"
   531				holder = receiver
   532				_, _ = app.store.pg.Exec(r.Context(), `UPDATE handoffs SET status='confirmed', completed_at=$2 WHERE id=$1`, req.HandoffID, at)
   533				_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET current_holder_id=$2 WHERE id=$1`, sampleID, receiver)
   534			}
