   808	func (app *App) replanJourney(ctx context.Context, u *SessionUser, journeyID string) (string, string, error) {
   809		sids := app.journeySampleIDs(ctx, journeyID)
   810		if len(sids) == 0 {
   811			return "not_required", "", nil
   812		}
   813		// cancel unfinished assignments, keep completed
   814		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
   815		app.releaseJourneyCapacity(ctx, journeyID)
   816		_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced' WHERE id=$1`, journeyID)
   817	
   818		// replan first unfinished sample (and attach others if possible)
   819		var lastStatus, lastID string
   820		for _, sid := range sids {
   821			s, err := app.loadSample(ctx, sid)
   822			if err != nil || s.Status == "received" || s.Status == "cancelled" {
   823				continue
   824			}
   825			st, _ := app.loadSampleType(ctx, s.SampleTypeID)
   826			plan, err := app.evaluateServiceability(ctx, Coord{s.OriginLat, s.OriginLng}, s.OriginType, "", s.SampleTypeID, time.Now(), s.Deadline, s.Earliest, s.Latest)
   827			if err != nil || !plan.Serviceable {
   828				reason := "no_valid_route"
   829				status := "exception"
   830				if plan != nil && plan.Reason == "deadline_unreachable" {
   831					status = "expired"
   832					reason = "deadline_unreachable"
   833				}
   834				_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status=$2, exception=$3 WHERE id=$1`, sid, status, asJSON(map[string]interface{}{"reason": reason}))
   835				if status == "expired" {
   836					lastStatus = "expired"
   837				} else {
   838					lastStatus = "exception"
   839				}
   840				continue
   841			}
   842			req := collectionReqBody{
   843				Origin: Coord{s.OriginLat, s.OriginLng}, OriginType: s.OriginType, SampleTypeID: s.SampleTypeID,
   844				ContainerType: s.ContainerType, TemperatureMinC: s.TempMin, TemperatureMaxC: s.TempMax,
   845			}
   846			jid, _, err := app.materializeJourney(ctx, u, sid, req, plan, st, s.Sealed, time.Now())
   847			if err != nil {
   848				lastStatus = "exception"
   849				continue
   850			}
   851			_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2 WHERE id=$1`, jid, journeyID)
   852			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE id=$1`, sid, jid, plan.TargetLab)
   853			lastStatus = "replaced"
   854			lastID = jid
   855		}
   856		if lastStatus == "" {
   857			lastStatus = "not_required"
   858		}
   859		return lastStatus, lastID, nil
   860	}
