   880	func (app *App) offerOne(ctx context.Context, assignmentID string) string {
   881		var kind string
   882		var sampleID, nodeID, labID *string
   883		var expected *string
   884		err := app.store.pg.QueryRow(ctx, `SELECT kind, sample_id, node_id, laboratory_id, expected_sample_type_id FROM assignments WHERE id=$1`, assignmentID).
   885			Scan(&kind, &sampleID, &nodeID, &labID, &expected)
   886		if err != nil {
   887			return ""
   888		}
   889		role := RoleDeliveryPartner
   890		switch kind {
   891		case "collection":
   892			role = RoleCollectionProfessional
   893		case "node":
   894			role = RoleNodeHandler
   895		case "laboratory":
   896			role = RoleLaboratoryTeam
   897		}
   898		q := `
   899	SELECT u.id FROM users u
   900	JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
   901	WHERE u.active=TRUE AND u.available=TRUE
   902	  AND (u.decline_penalty_until IS NULL OR u.decline_penalty_until < now())
   903	`
   904		args := []interface{}{role}
   905		if (kind == "node" || kind == "laboratory") && (nodeID != nil || labID != nil) {
   906			loc := ""
   907			if nodeID != nil {
   908				loc = *nodeID
   909			}
   910			if labID != nil {
   911				loc = *labID
   912			}
   913			q += ` AND u.assigned_location_id=$2`
   914			args = append(args, loc)
   915		}
   916		q += ` ORDER BY COALESCE(u.last_offered_at, to_timestamp(0)) ASC, COALESCE(u.last_assigned_at, to_timestamp(0)) ASC,
   917	  (SELECT COUNT(*) FROM assignments a WHERE a.worker_id=u.id AND a.status NOT IN ('completed','cancelled')) ASC
   918	LIMIT 5`
   919		wrows, err := app.store.pg.Query(ctx, q, args...)
   920		if err != nil {
   921			return ""
   922		}
   923		defer wrows.Close()
   924		var candidates []string
   925		for wrows.Next() {
   926			var id string
   927			if wrows.Scan(&id) == nil {
   928				candidates = append(candidates, id)
   929			}
   930		}
   931		if len(candidates) == 0 {
   932			if kind == "collection" && expected != nil {
   933				// no qualified collector — flag after timeout; we flag immediately only if never anyone
   934				var n int
   935				_ = app.store.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1 WHERE u.active`, RoleCollectionProfessional).Scan(&n)
   936				if n == 0 && sampleID != nil {
   937					_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`,
   938						*sampleID, asJSON(map[string]interface{}{"reason": "no_qualified_worker"}))
   939					_, _ = app.store.pg.Exec(ctx, `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,now())`,
   940						newUUID(), *sampleID, "no_qualified_worker")
   941				}
   942			}
   943			return ""
   944		}
   945		// qualification filter for collection
   946		chosen := candidates[0]
   947		if kind == "collection" && expected != nil {
   948			st, _ := app.loadSampleType(ctx, *expected)
   949			if st != nil && st.QualifiedCollector {
   950				found := ""
   951				for _, cid := range candidates {
   952					wu, err := app.loadUser(ctx, cid, "")
   953					if err != nil {
   954						continue
   955					}
   956					if contains(wu.Qualifications, st.RequiredQualification) || hasActiveCert(wu.Certifications, st.RequiredQualification) {
   957						found = cid
   958						break
   959					}
   960				}
   961				if found == "" {
   962					if sampleID != nil {
   963						// leave pending; background will eventually exception
   964					}
   965					return ""
   966				}
   967				chosen = found
   968			}
   969		}
   970		exp := time.Now().Add(offerTTL)
   971		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3 WHERE id=$1`, assignmentID, chosen, exp)
   972		_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=now() WHERE id=$1`, chosen)
   973		app.emit("assignment.offered", "assignment", assignmentID, map[string]interface{}{"workerId": chosen})
   974		return chosen
   975	}
