   306	func (app *App) journeyPlanPayload(ctx context.Context, journeyID, viewerRole, viewerID string) (map[string]interface{}, error) {
   307		j, err := app.loadJourney(ctx, journeyID)
   308		if err != nil {
   309			return nil, err
   310		}
   311		sids := app.journeySampleIDs(ctx, journeyID)
   312		if sids == nil {
   313			sids = []string{}
   314		}
   315		stops := []map[string]interface{}{}
   316		srows, err := app.store.pg.Query(ctx, `
   317	SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, completed_at
   318	FROM journey_stops WHERE journey_id=$1 ORDER BY sequence`, journeyID)
   319		if err == nil {
   320			defer srows.Close()
   321			for srows.Next() {
   322				var id, stype string
   323				var locID *string
   324				var seq, dwell int
   325				var est time.Time
   326				var lat, lng *float64
   327				var done *time.Time
   328				if err := srows.Scan(&id, &locID, &stype, &seq, &est, &dwell, &lat, &lng, &done); err != nil {
   329					continue
   330				}
   331				item := map[string]interface{}{
   332					"stopId":      id,
   333					"stopType":    stype,
   334					"stop_type":   stype,
   335					"sequence":    seq,
   336					"estimatedAt": rfc3339(est),
   337					"estimated_at": rfc3339(est),
   338					"dwellMinutes": dwell,
   339				}
   340				if locID != nil {
   341					item["locationId"] = *locID
   342					item["location_id"] = *locID
   343				} else {
   344					item["locationId"] = "00000000-0000-0000-0000-000000000000"
   345				}
   346				if lat != nil && lng != nil {
   347					item["coordinate"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
   348				}
   349				if done != nil {
   350					item["completedAt"] = rfc3339(*done)
   351				}
   352				stops = append(stops, item)
   353			}
   354		}
   355	
   356		legs := []map[string]interface{}{}
   357		arows, err := app.store.pg.Query(ctx, `
   358	SELECT id, sample_id, sequence, status, from_location_id, to_location_id, worker_id, kind
   359	FROM assignments WHERE journey_id=$1 ORDER BY sequence, created_at`, journeyID)
   360		if err == nil {
   361			defer arows.Close()
   362			for arows.Next() {
   363				var id, status, kind string
   364				var sid, from, to, worker *string
   365				var seq int
   366				if err := arows.Scan(&id, &sid, &seq, &status, &from, &to, &worker, &kind); err != nil {
   367					continue
   368				}
   369				if viewerRole == RoleDeliveryPartner || viewerRole == RoleCollectionProfessional || viewerRole == RoleNodeHandler || viewerRole == RoleLaboratoryTeam {
   370					if worker == nil || *worker != viewerID {
   371						// still include offered-to
   372						var offered *string
   373						_ = app.store.pg.QueryRow(ctx, `SELECT offered_to FROM assignments WHERE id=$1`, id).Scan(&offered)
   374						if offered == nil || *offered != viewerID {
   375							continue
   376						}
   377					}
   378				}
   379				leg := map[string]interface{}{
   380					"assignmentId":  id,
   381					"assignment_id": id,
   382					"sequence":      seq,
   383					"status":        status,
   384				}
   385				if from != nil {
   386					leg["fromLocationId"] = *from
   387					leg["from_location_id"] = *from
   388				}
   389				if to != nil {
   390					leg["toLocationId"] = *to
   391					leg["to_location_id"] = *to
   392				}
   393				if worker != nil && viewerRole != RoleRequester {
   394					leg["workerId"] = *worker
   395					leg["worker_id"] = *worker
   396				}
   397				if sid != nil {
   398					leg["sampleId"] = *sid
   399				}
   400				legs = append(legs, leg)
   401			}
   402		}
   403	
   404		out := map[string]interface{}{
   405			"journeyId":     j.ID,
   406			"planVersion":   j.PlanVersion,
   407			"routeMode":     j.RouteMode,
   408			"status":        j.Status,
   409			"totalCostUnits": j.TotalCost,
   410			"sampleIds":     sids,
   411			"orderedStops":  stops,
   412			"legs":          legs,
   413			"capacityUsed":  j.CapacityUsed,
   414			"capacityAvailable": j.CapacityAvail,
   415			"valid":         j.Valid,
   416		}
   417		if j.ParentID != "" {
   418			out["parentJourneyId"] = j.ParentID
   419		}
   420		if j.Estimated != nil {
   421			out["estimatedDeliveryAt"] = rfc3339(*j.Estimated)
   422		}
   423		if viewerRole == RoleRequester {
   424			// RequesterJourneyPlan required: journeyId, sampleIds, legs
   425			req := map[string]interface{}{
   426				"journeyId": j.ID,
   427				"sampleIds": sids,
   428				"legs":      legs,
   429			}
   430			if j.ParentID != "" {
   431				req["parentJourneyId"] = j.ParentID
   432			}
   433			req["planVersion"] = j.PlanVersion
   434			req["routeMode"] = j.RouteMode
   435			req["status"] = j.Status
   436			if j.Estimated != nil {
   437				req["estimatedDeliveryAt"] = rfc3339(*j.Estimated)
   438			}
   439			req["totalCostUnits"] = j.TotalCost
   440			req["orderedStops"] = stops
   441			return req, nil
   442		}
   443		return out, nil
   444	}
