   488				if rows.Scan(&id) != nil {
   489					continue
   490				}
   491				s, err := app.loadSample(ctx, id)
   492				if err != nil {
   493					continue
   494				}
   495				if sampleTypeFilter != "" && s.SampleTypeID != sampleTypeFilter {
   496					continue
   497				}
   498				item := map[string]interface{}{
   499					"sampleId":         s.ID,
   500					"status":           s.Status,
   501					"serviceability":   s.Serviceability,
   502					"currentHolderId":  ptrStr(s.CurrentHolderID),
   503					"locationStale":    isStale(s.LocationRecordedAt, now),
   504					"deliveryDeadline": rfc3339(s.Deadline),
   505				}
   506				if s.LatestLat != nil && s.LatestLng != nil {
   507					item["latestLocation"] = map[string]interface{}{"latitude": *s.LatestLat, "longitude": *s.LatestLng}
   508				}
   509				if s.LocationRecordedAt != nil {
   510					item["locationRecordedAt"] = rfc3339(*s.LocationRecordedAt)
   511				}
   512				if s.ActiveJourneyID != nil {
   513					item["activeJourneyId"] = *s.ActiveJourneyID
   514				}
   515				if s.TargetLabID != nil {
   516					item["targetLaboratoryId"] = *s.TargetLabID
   517				}
   518				if len(s.Exception) > 0 && string(s.Exception) != "null" {
   519					var ex interface{}
   520					_ = jsonUnmarshal(s.Exception, &ex)
   521					item["exception"] = ex
   522				}
   523				samples = append(samples, item)
   524			}
   525		}
   526	
   527		workers := []map[string]interface{}{}
   528		wrows, err := app.store.pg.Query(ctx, `
   529	SELECT u.id, u.username, u.full_name, u.available, u.capacity_units, u.latest_lat, u.latest_lng, u.location_recorded_at,
   530	  COALESCE((SELECT COUNT(*) FROM assignments a WHERE (a.worker_id=u.id OR a.offered_to=u.id) AND a.status NOT IN ('completed','cancelled')),0)
   531	FROM users u
   532	JOIN user_roles ur ON ur.user_id=u.id
   533	WHERE ur.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team')
   534	GROUP BY u.id`)
   535		if err == nil {
   536			defer wrows.Close()
   537			for wrows.Next() {
   538				var id, uname, fname string
   539				var avail bool
   540				var cap, load int
   541				var lat, lng *float64
   542				var rec *time.Time
   543				if wrows.Scan(&id, &uname, &fname, &avail, &cap, &lat, &lng, &rec, &load) != nil {
   544					continue
   545				}
   546				item := map[string]interface{}{
   547					"workerId": id, "username": uname, "fullName": fname,
   548					"available": avail, "capacityUnits": cap, "activeLoad": load,
   549					"locationStale": isStale(rec, now),
   550				}
   551				if lat != nil && lng != nil {
   552					item["latestLocation"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
   553				}
   554				if rec != nil {
   555					item["locationRecordedAt"] = rfc3339(*rec)
   556				}
   557				workers = append(workers, item)
   558			}
   559		}
   560	
   561		locations := []map[string]interface{}{}
   562		locs, _ := app.loadLocations(ctx)
   563		for _, l := range locs {
   564			if u.ActiveRole == RoleNodeHandler || u.ActiveRole == RoleLaboratoryTeam {
   565				if u.AssignedLocationID != l.ID {
   566					continue
   567				}
   568			}
   569			cap := Capacity{
   570				CapacityUnits: l.CapacityUnits, ReservedUnits: l.ReservedUnits,
   571				CooledCapacityUnits: l.CooledCap, CooledReservedUnits: l.CooledReserved,
   572			}.fill()
   573			item := map[string]interface{}{
   574				"id":              l.ID,
   575				"locationId":      l.ID,
   576				"name":            l.Name,
   577				"coordinate":      map[string]interface{}{"latitude": l.Lat, "longitude": l.Lng},
   578				"active":          l.Active,
   579				"coverageKm":      l.CoverageKm,
   580				"handlingMinutes": l.HandlingMinutes,
   581				"functions": LocationFunctions{
   582					CollectionPoint: l.FnCollection, TransferPoint: l.FnTransfer, Hub: l.FnHub, Laboratory: l.FnLaboratory,
   583				},
   584				"capacity":              cap,
   585				"acceptedSampleTypeIds": l.AcceptedTypes,
   586			}
   587			locations = append(locations, item)
   588		}
   589	
   590		routes := []map[string]interface{}{}
   591		conns, _ := app.loadConnections(ctx)
   592		for _, c := range conns {
   593			cap := Capacity{
   594				CapacityUnits: c.CapacityUnits, ReservedUnits: c.ReservedUnits,
   595				CooledCapacityUnits: c.CooledCap, CooledReservedUnits: c.CooledReserved,
   596			}.fill()
   597			routes = append(routes, map[string]interface{}{
   598				"connectionId": c.ID, "fromLocationId": c.FromID, "toLocationId": c.ToID,
   599				"travelMinutes": c.TravelMinutes, "costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active,
   600				"capacity": cap,
   601			})
   602		}
   603	
   604		exceptions := []map[string]interface{}{}
   605		erows, err := app.store.pg.Query(ctx, `SELECT id, sample_id, laboratory_id, reason, observed_at FROM exceptions ORDER BY observed_at DESC LIMIT 200`)
   606		if err == nil {
   607			defer erows.Close()
   608			for erows.Next() {
   609				var id, sid, reason string
   610				var lab *string
   611				var at time.Time
   612				if erows.Scan(&id, &sid, &lab, &reason, &at) != nil {
   613					continue
   614				}
   615				item := map[string]interface{}{"exceptionId": id, "sampleId": sid, "reason": reason, "observedAt": rfc3339(at)}
   616				if lab != nil {
   617					item["laboratoryId"] = *lab
   618				}
   619				exceptions = append(exceptions, item)
   620			}
   621		}
   622	
   623		return map[string]interface{}{
   624			"generatedAt": rfc3339(now),
   625			"samples":     samples,
   626			"workers":     workers,
   627			"locations":   locations,
   628			"routes":      routes,
   629			"exceptions":  exceptions,
   630		}, nil
   631	}
