   634		u := currentUser(r)
   635		if !u.isDispatcher() && u.ActiveRole != RoleNodeHandler && u.ActiveRole != RoleLaboratoryTeam && u.ActiveRole != RoleAdministrator {
   636			writeErr(w, 403, "forbidden", "forbidden")
