   642				SampleTypeID  string `json:"sampleTypeId"`
   643				SampleTypeID2 string `json:"sample_type_id"`
   644			} `json:"filters"`
   645		}
   646		_ = decodeBody(body, &req)
   647		filter := req.Filters.SampleTypeID
   648		if filter == "" {
   649			filter = req.Filters.SampleTypeID2
   650		}
   651		data, err := app.operationsState(r.Context(), u, filter)
   652		if err != nil {
   653			app.handleErr(w, err)
   654			return
   655		}
   656		writeData(w, 200, data)
   657	}
