   686			Action: req.Action, Role: req.Role, Success: req.Success, Limit: req.Limit, Offset: req.Offset, Order: req.Order,
   687		}
   688		if req.FromTime != "" {
   689			t, err := parseTime(req.FromTime)
   690			if err != nil {
   691				writeErr(w, 400, "invalid_time", "invalid fromTime")
   692				return
   693			}
   694			q.FromTime = &t
   695		}
   696		if req.ToTime != "" {
   697			t, err := parseTime(req.ToTime)
   698			if err != nil {
   699				writeErr(w, 400, "invalid_time", "invalid toTime")
   700				return
   701			}
   702			q.ToTime = &t
   703		}
   704		res, err := app.searchAudit(r.Context(), q)
   705		if err != nil {
   706			app.handleErr(w, err)
   707			return
   708		}
   709		writeData(w, 200, res)
   710	}

