   362	func (app *App) releaseJourneyCapacity(ctx context.Context, journeyID string) {
   363		rows, err := app.store.pg.Query(ctx, `SELECT id, resource_id, resource_kind, regular_units, cooled_units FROM capacity_reservations WHERE journey_id=$1 AND active=TRUE`, journeyID)
   364		if err != nil {
