   366		}
   367		defer rows.Close()
   368		type resv struct {
   369			id, rid, kind string
   370			reg, cool     int
   371		}
   372		var list []resv
   373		for rows.Next() {
   374			var r resv
   375			if rows.Scan(&r.id, &r.rid, &r.kind, &r.reg, &r.cool) == nil {
