   343	func shortestPath(locs []locRow, conns []connRow, from, to string, needCooled bool) ([]string, int, float64, bool) {
   344		if from == to {
   345			return []string{from}, 0, 0, true
   346		}
   347		type node struct {
   348			id   string
   349			mins int
   350			cost float64
   351			prev string
   352		}
   353		dist := map[string]int{}
   354		cost := map[string]float64{}
   355		prev := map[string]string{}
   356		for _, l := range locs {
   357			dist[l.ID] = math.MaxInt32
   358		}
   359		dist[from] = 0
   360		type item struct {
   361			id   string
   362			mins int
   363		}
   364		q := []item{{from, 0}}
   365		for len(q) > 0 {
   366			sort.Slice(q, func(i, j int) bool { return q[i].mins < q[j].mins })
   367			cur := q[0]
   368			q = q[1:]
   369			if cur.mins != dist[cur.id] {
   370				continue
   371			}
   372			if cur.id == to {
   373				break
   374			}
   375			for _, c := range conns {
   376				if !c.Active || c.FromID != cur.id {
   377					continue
   378				}
   379				if needCooled && !c.Cooled {
   380					continue
   381				}
   382				nm := cur.mins + c.TravelMinutes
   383				if nm < dist[c.ToID] {
   384					dist[c.ToID] = nm
   385					cost[c.ToID] = cost[cur.id] + c.CostUnits
   386					prev[c.ToID] = cur.id
   387					q = append(q, item{c.ToID, nm})
   388				}
   389			}
   390		}
   391		if dist[to] == math.MaxInt32 {
   392			return nil, 0, 0, false
   393		}
   394		path := []string{to}
   395		for path[0] != from {
   396			p, ok := prev[path[0]]
   397			if !ok {
   398				return nil, 0, 0, false
   399			}
   400			path = append([]string{p}, path...)
   401		}
   402		return path, dist[to], cost[to], true
   403	}
