   866	func (app *App) offerOne(ctx context.Context, assignmentID string) string {
   867		var kind string
   868		var sampleID, nodeID, labID *string
   869		var expected *string
   870		err := app.store.pg.QueryRow(ctx, `SELECT kind, sample_id, node_id, laboratory_id, expected_sample_type_id FROM assignments WHERE id=$1`, assignmentID).
   871			Scan(&kind, &sampleID, &nodeID, &labID, &expected)
   872		if err != nil {
   873			return ""
   874		}
   875		role := RoleDeliveryPartner
   876		switch kind {
   877		case "collection":
   878			role = RoleCollectionProfessional
   879		case "node":
   880			role = RoleNodeHandler
   881		case "laboratory":
   882			role = RoleLaboratoryTeam
   883		}
   884		q := `
   885	SELECT u.id FROM users u
   886	JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
   887	WHERE u.active=TRUE AND u.available=TRUE
   888	  AND (u.decline_penalty_until IS NULL OR u.decline_penalty_until < now())
   889	`
   890		args := []interface{}{role}
   891		if (kind == "node" || kind == "laboratory") && (nodeID != nil || labID != nil) {
   892			loc := ""
   893			if nodeID != nil {
   894				loc = *nodeID
   895			}
   896			if labID != nil {
   897				loc = *labID
   898			}
   899			q += ` AND u.assigned_location_id=$2`
   900			args = append(args, loc)
   901		}
   902		q += ` ORDER BY COALESCE(u.last_offered_at, to_timestamp(0)) ASC, COALESCE(u.last_assigned_at, to_timestamp(0)) ASC,
   903	  (SELECT COUNT(*) FROM assignments a WHERE a.worker_id=u.id AND a.status NOT IN ('completed','cancelled')) ASC
   904	LIMIT 5`
   905		wrows, err := app.store.pg.Query(ctx, q, args...)
   906		if err != nil {
   907			return ""
   908		}
   909		defer wrows.Close()
   910		var candidates []string
   911		for wrows.Next() {
   912			var id string
   913			if wrows.Scan(&id) == nil {
   914				candidates = append(candidates, id)
   915			}
   916		}
   917		if len(candidates) == 0 {
   918			if kind == "collection" && expected != nil {
   919				// no qualified collector — flag after timeout; we flag immediately only if never anyone
   920				var n int
   921				_ = app.store.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1 WHERE u.active`, RoleCollectionProfessional).Scan(&n)
   922				if n == 0 && sampleID != nil {
   923					_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`,
   924						*sampleID, asJSON(map[string]interface{}{"reason": "no_qualified_worker"}))
   925					_, _ = app.store.pg.Exec(ctx, `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,now())`,
   926						newUUID(), *sampleID, "no_qualified_worker")
   927				}
   928			}
   929			return ""
   930		}
   931		// qualification filter for collection
   932		chosen := candidates[0]
   933		if kind == "collection" && expected != nil {
   934			st, _ := app.loadSampleType(ctx, *expected)
   935			if st != nil && st.QualifiedCollector {
   936				found := ""
   937				for _, cid := range candidates {
   938					wu, err := app.loadUser(ctx, cid, "")
   939					if err != nil {
   940						continue
   941					}
   942					if contains(wu.Qualifications, st.RequiredQualification) || hasActiveCert(wu.Certifications, st.RequiredQualification) {
   943						found = cid
   944						break
   945					}
   946				}
   947				if found == "" {
   948					if sampleID != nil {
   949						// leave pending; background will eventually exception
   950					}
   951					return ""
   952				}
   953				chosen = found
   954			}
   955		}
   956		exp := time.Now().Add(offerTTL)
   957		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3 WHERE id=$1`, assignmentID, chosen, exp)
   958		_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=now() WHERE id=$1`, chosen)
   959		app.emit("assignment.offered", "assignment", assignmentID, map[string]interface{}{"workerId": chosen})
   960		return chosen
   961	}
