  1007	func parseInt64(s string, out *int64) (int, error) {
  1008		var n int64
  1009		for _, c := range s {
  1010			if c < '0' || c > '9' {
  1011				return 0, herr(400, "invalid_json", "invalid since")
  1012			}
  1013			n = n*10 + int64(c-'0')
  1014		}
  1015		*out = n
  1016		return 0, nil
  1017	}

