   463				return 0, nil, err
   464			}
   465			// pulse cannot batch
   466			targetSamples := app.journeySampleIDs(r.Context(), req.TargetJourneyID)
   467			types := map[string]*sampleTypeRow{}
   468			checkPulse := func(sids []string) error {
   469				for _, sid := range sids {
