	"github.com/gorilla/websocket"
)

type App struct {
	store      *Store
	frontend   string
	mapAssets  string
	httpServer *http.Server
}

func main() {
	ctx := context.Background()
	pgURL := getenv("DATABASE_URL", "postgres://arena:arena@127.0.0.1:5432/arena?sslmode=disable")
	mongoURL := getenv("MONGO_URL", "mongodb://127.0.0.1:27017")
	listen := getenv("LISTEN_ADDR", "127.0.0.1:18082")
	frontend := getenv("FRONTEND_DIR", "/workspace/frontend/dist")
	mapAssets := getenv("MAP_ASSETS_DIR", "/opt/arena/map-assets")

	if os.Getenv("ARENA_RESET") == "1" {
		store, err := NewStore(ctx, pgURL, mongoURL)
		if err != nil {
			log.Fatalf("store: %v", err)
		}
		if err := store.Reset(ctx); err != nil {
			log.Fatalf("reset: %v", err)
		}
		store.Close()
		log.Printf("reset complete")
		return
	}

	store, err := NewStore(ctx, pgURL, mongoURL)
	if err != nil {
		log.Fatalf("store: %v", err)
	}
	defer store.Close()
	if err := store.EnsureSchema(ctx); err != nil {
		log.Fatalf("schema: %v", err)
	}
	if err := store.EnsureAdmin(ctx); err != nil {
		log.Fatalf("admin: %v", err)
	}

	app := &App{store: store, frontend: frontend, mapAssets: mapAssets}
	app.recomputeServiceability()
	go app.offerLoop()

	mux := http.NewServeMux()
	app.routes(mux)

	srv := &http.Server{
		Addr:              listen,
		Handler:           cors(mux),
		ReadHeaderTimeout: 10 * time.Second,
	}
	app.httpServer = srv

	go func() {
		log.Printf("listening on %s", listen)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("listen: %v", err)
		}
	}()

	ch := make(chan os.Signal, 1)
	signal.Notify(ch, syscall.SIGINT, syscall.SIGTERM)
	<-ch
	cctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	_ = srv.Shutdown(cctx)
}

