    36		pg, err := pgxpool.New(ctx, pgURL)
    37		if err != nil {
    38			return nil, fmt.Errorf("pg connect: %w", err)
    39		}
    40		if err := pg.Ping(ctx); err != nil {
    41			return nil, fmt.Errorf("pg ping: %w", err)
    42		}
    43	
    44		mc, err := mongo.Connect(options.Client().ApplyURI(mongoURL))
    45		if err != nil {
    46			return nil, fmt.Errorf("mongo connect: %w", err)
    47		}
    48		if err := mc.Ping(ctx, nil); err != nil {
    49			return nil, fmt.Errorf("mongo ping: %w", err)
    50		}
    51		dbName := "arena"
    52		if v := os.Getenv("MONGO_DB"); v != "" {
    53			dbName = v
    54		}
    55		mdb := mc.Database(dbName)
    56		s := &Store{
    57			pg:        pg,
    58			mongo:     mc,
    59			mdb:       mdb,
    60			audit:     mdb.Collection("audit_logs"),
    61			eventSubs: map[chan RealtimeEvent]struct{}{},
    62		}
    63		return s, nil
    64	}
