   722	func (app *App) replanJourney(ctx context.Context, u *SessionUser, journeyID string) (string, string, error) {
   723		sids := app.journeySampleIDs(ctx, journeyID)
   724		if len(sids) == 0 {
   725			return "not_required", "", nil
   726		}
   727		// cancel unfinished assignments, keep completed
   728		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
   729		app.releaseJourneyCapacity(ctx, journeyID)
   730		_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced' WHERE id=$1`, journeyID)
   731	
   732		// replan first unfinished sample (and attach others if possible)
   733		var lastStatus, lastID string
   734		for _, sid := range sids {
   735			s, err := app.loadSample(ctx, sid)
   736			if err != nil || s.Status == "received" || s.Status == "cancelled" {
   737				continue
   738			}
   739			st, _ := app.loadSampleType(ctx, s.SampleTypeID)
   740			plan, err := app.evaluateServiceability(ctx, Coord{s.OriginLat, s.OriginLng}, s.OriginType, "", s.SampleTypeID, time.Now(), s.Deadline, s.Earliest, s.Latest)
   741			if err != nil || !plan.Serviceable {
   742				reason := "no_valid_route"
   743				status := "exception"
   744				if plan != nil && plan.Reason == "deadline_unreachable" {
   745					status = "expired"
   746					reason = "deadline_unreachable"
   747				}
   748				_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status=$2, exception=$3 WHERE id=$1`, sid, status, asJSON(map[string]interface{}{"reason": reason}))
   749				if status == "expired" {
   750					lastStatus = "expired"
   751				} else {
   752					lastStatus = "exception"
   753				}
   754				continue
   755			}
   756			req := collectionReqBody{
   757				Origin: Coord{s.OriginLat, s.OriginLng}, OriginType: s.OriginType, SampleTypeID: s.SampleTypeID,
   758				ContainerType: s.ContainerType, TemperatureMinC: s.TempMin, TemperatureMaxC: s.TempMax,
   759			}
   760			jid, _, err := app.materializeJourney(ctx, u, sid, req, plan, st, s.Sealed, time.Now())
   761			if err != nil {
   762				lastStatus = "exception"
   763				continue
   764			}
   765			_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2 WHERE id=$1`, jid, journeyID)
   766			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE id=$1`, sid, jid, plan.TargetLab)
   767			lastStatus = "replaced"
   768			lastID = jid
   769		}
