   177	func planServiceability(locs []locRow, conns []connRow, st *sampleTypeRow, origin Coord, originType, originNodeID string, requestedAt, deadline, earliest, latest time.Time) *planResult {
   178		res := &planResult{Serviceable: false, Reason: "outside_service_coverage", NeedsCooled: st.RequiresCooled}
   179	
   180		var start *locRow
   181		if originType == "node" && originNodeID != "" {
   182			start = locByID(locs, originNodeID)
   183			if start == nil || !start.Active {
   184				res.Reason = "outside_service_coverage"
   185				return res
   186			}
   187		} else {
   188			bestDist := math.MaxFloat64
   189			for i := range locs {
   190				l := &locs[i]
   191				if !l.Active || !l.FnCollection {
   192					continue
   193				}
   194				d := haversineKm(origin.Latitude, origin.Longitude, l.Lat, l.Lng)
   195				cov := l.CoverageKm
   196				if cov <= 0 {
   197					cov = 5
   198				}
   199				if d <= cov && d < bestDist {
   200					bestDist = d
   201					start = l
   202				}
   203			}
   204			if start == nil {
   205				res.Reason = "outside_service_coverage"
   206				return res
   207			}
   208			// home/clinic travel minutes from origin to collection point at 25 km/h
   209			res.CollectionTravelMin = int(math.Ceil(bestDist / 25.0 * 60.0))
   210			if res.CollectionTravelMin < 1 {
   211				res.CollectionTravelMin = 1
   212			}
   213		}
   214		res.CollectionPoint = start.ID
   215	
   216		labs := []locRow{}
   217		for _, l := range locs {
