   219				continue
   220			}
   221			if !contains(l.AcceptedTypes, st.ID) && len(l.AcceptedTypes) > 0 {
   222				continue
   223			}
   224			// if no acceptances configured, treat as accepting all
   225			if len(l.AcceptedTypes) == 0 {
   226				// still a laboratory; allow unless we have other labs that do accept
   227				labs = append(labs, l)
