   269	func normalizeAudit(raw bson.M) map[string]interface{} {
   270		get := func(keys ...string) interface{} {
   271			for _, k := range keys {
   272				if v, ok := raw[k]; ok && v != nil {
   273					return v
   274				}
   275			}
   276			return ""
   277		}
   278		occurred := get("occurredAt", "occurred_at")
   279		var occurredStr string
   280		switch t := occurred.(type) {
   281		case time.Time:
   282			occurredStr = t.UTC().Format(time.RFC3339)
   283		case bson.DateTime:
   284			occurredStr = t.Time().UTC().Format(time.RFC3339)
   285		default:
   286			occurredStr = stringify(occurred)
   287		}
   288		details := map[string]interface{}{}
   289		switch d := raw["details"].(type) {
   290		case bson.M:
   291			for k, v := range d {
   292				details[k] = v
   293			}
   294		case map[string]interface{}:
   295			details = d
   296		}
   297		aid := get("auditId", "audit_id")
   298		actor := get("actorId", "actor_id")
   299		et := get("entityType", "entity_type")
   300		eid := get("entityId", "entity_id")
   301		role, _ := get("role").(string)
   302		return map[string]interface{}{
   303			"auditId":     aid,
   304			"audit_id":    aid,
   305			"actorId":     actor,
   306			"actor_id":    actor,
   307			"role":        role,
   308			"actorRole":   get("actorRole", "role"),
   309			"action":      get("action"),
   310			"entityType":  et,
   311			"entity_type": et,
   312			"entityId":    eid,
   313			"entity_id":   eid,
   314			"success":     raw["success"] == true,
   315			"occurredAt":  occurredStr,
   316			"occurred_at": occurredStr,
   317			"details":     details,
   318		}
   319	}
