    45	func (app *App) roleWork(ctx context.Context, u *SessionUser, role string) (pending, inProg, completed []map[string]interface{}) {
    46		pending, inProg, completed = []map[string]interface{}{}, []map[string]interface{}{}, []map[string]interface{}{}
    47		now := time.Now()
    48		if role == RoleRequester {
    49			rows, err := app.store.pg.Query(ctx, `SELECT id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, u.UserID)
    50			if err != nil {
    51				return
    52			}
    53			defer rows.Close()
    54			for rows.Next() {
    55				var id string
    56				if rows.Scan(&id) != nil {
    57					continue
    58				}
    59				s, err := app.loadSample(ctx, id)
    60				if err != nil {
    61					continue
    62				}
    63				item := app.sampleWorkItem(ctx, s, now)
    64				switch s.Status {
    65				case "received", "cancelled", "expired":
    66					completed = append(completed, item)
    67				case "requested":
    68					pending = append(pending, item)
    69				default:
    70					inProg = append(inProg, item)
    71				}
    72			}
    73			return
    74		}
    75		if role == RoleDispatcher || role == RoleAdministrator {
    76			rows, err := app.store.pg.Query(ctx, `SELECT id FROM samples ORDER BY created_at DESC LIMIT 300`)
    77			if err != nil {
    78				return
    79			}
    80			defer rows.Close()
    81			for rows.Next() {
    82				var id string
    83				if rows.Scan(&id) != nil {
    84					continue
    85				}
    86				s, err := app.loadSample(ctx, id)
    87				if err != nil {
    88					continue
    89				}
    90				item := app.sampleWorkItem(ctx, s, now)
    91				switch s.Status {
    92				case "received", "cancelled", "expired":
    93					completed = append(completed, item)
    94				case "requested":
    95					pending = append(pending, item)
    96				default:
    97					inProg = append(inProg, item)
    98				}
    99			}
   100			return
   101		}
   102		// worker assignments
   103		rows, err := app.store.pg.Query(ctx, `
   104	SELECT id FROM assignments
   105	WHERE worker_id=$1 OR offered_to=$1
   106	ORDER BY created_at DESC`, u.UserID)
   107		if err != nil {
   108			return
   109		}
