    75		if role == RoleDispatcher || role == RoleAdministrator {
    76			rows, err := app.store.pg.Query(ctx, `SELECT id FROM samples ORDER BY created_at DESC LIMIT 300`)
    77			if err != nil {
    78				return
    79			}
    80			defer rows.Close()
    81			for rows.Next() {
    82				var id string
    83				if rows.Scan(&id) != nil {
    84					continue
    85				}
    86				s, err := app.loadSample(ctx, id)
    87				if err != nil {
    88					continue
    89				}
    90				item := app.sampleWorkItem(ctx, s, now)
    91				switch s.Status {
    92				case "received", "cancelled", "expired":
    93					completed = append(completed, item)
    94				case "requested":
    95					pending = append(pending, item)
    96				default:
    97					inProg = append(inProg, item)
    98				}
    99			}
   100			return
   101		}
   102		// worker assignments
   103		rows, err := app.store.pg.Query(ctx, `
   104	SELECT id FROM assignments
   105	WHERE worker_id=$1 OR offered_to=$1
   106	ORDER BY created_at DESC`, u.UserID)
   107		if err != nil {
   108			return
   109		}
   110		defer rows.Close()
   111		for rows.Next() {
   112			var id string
   113			if rows.Scan(&id) != nil {
   114				continue
   115			}
   116			item, status, ok := app.assignmentWorkItem(ctx, id)
   117			if !ok {
   118				continue
   119			}
   120			switch status {
   121			case "completed", "cancelled":
   122				completed = append(completed, item)
   123			case "accepted", "in_progress", "at_pickup", "picked_up", "in_transit", "arrived", "delivered":
   124				inProg = append(inProg, item)
   125			default:
   126				pending = append(pending, item)
   127			}
   128		}
   129		return
   130	}
