   376	func (app *App) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
   377		u := currentUser(r)
   378		body := readBody(r)
   379		var req struct {
   380			AssignmentID string `json:"assignmentId"`
   381			Coordinate   Coord  `json:"coordinate"`
   382			Sequence     int    `json:"sequence"`
   383			RecordedAt   string `json:"recordedAt"`
   384		}
   385		if err := decodeBody(body, &req); err != nil {
   386			writeErr(w, 400, "invalid_json", "invalid json")
   387			return
   388		}
   389		if req.Sequence < 1 {
   390			writeErr(w, 400, "invalid_sequence", "invalid sequence")
   391			return
   392		}
   393		at, err := parseTime(req.RecordedAt)
   394		if err != nil {
   395			writeErr(w, 400, "invalid_time", "invalid recordedAt")
   396			return
   397		}
   398		var worker, sampleID *string
   399		err = app.store.pg.QueryRow(r.Context(), `SELECT worker_id, sample_id FROM assignments WHERE id=$1`, req.AssignmentID).Scan(&worker, &sampleID)
   400		if err != nil {
   401			writeErr(w, 404, "not_found", "assignment not found")
   402			return
   403		}
   404		if !u.isDispatcher() && (worker == nil || *worker != u.UserID) {
   405			writeErr(w, 403, "forbidden", "not assigned worker")
   406			return
   407		}
   408		var maxSeq int
   409		_ = app.store.pg.QueryRow(r.Context(), `SELECT COALESCE(MAX(sequence),0) FROM worker_location_updates WHERE assignment_id=$1`, req.AssignmentID).Scan(&maxSeq)
   410		if req.Sequence <= maxSeq {
   411			writeErr(w, 409, "stale_location", "stale location sequence")
   412			return
   413		}
   414		_, err = app.store.pg.Exec(r.Context(), `
   415	INSERT INTO worker_location_updates (id, worker_id, assignment_id, latitude, longitude, sequence, recorded_at)
   416	VALUES ($1,$2,$3,$4,$5,$6,$7)`, newUUID(), u.UserID, req.AssignmentID, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, at)
   417		if err != nil {
   418			writeErr(w, 409, "concurrent_conflict", "location conflict")
   419			return
   420		}
   421		_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1`,
   422			u.UserID, req.Coordinate.Latitude, req.Coordinate.Longitude, at)
   423		if sampleID != nil {
   424			_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1`,
   425				*sampleID, req.Coordinate.Latitude, req.Coordinate.Longitude, at)
   426		}
   427		app.audit(r.Context(), u.UserID, u.ActiveRole, "record_worker_location", "assignment", req.AssignmentID, true, map[string]interface{}{"sequence": req.Sequence})
   428		app.emit("worker.location", "assignment", req.AssignmentID, map[string]interface{}{"coordinate": req.Coordinate})
   429		writeData(w, 201, map[string]interface{}{
   430			"assignmentId": req.AssignmentID,
   431			"coordinate":   req.Coordinate,
   432			"sequence":     req.Sequence,
   433			"recordedAt":   rfc3339(at),
   434		})
   435	}
