   479		samples := []map[string]interface{}{}
   480		q := `SELECT id FROM samples ORDER BY created_at DESC LIMIT 500`
   481		rows, err := app.store.pg.Query(ctx, q)
   482		if err == nil {
   483			defer rows.Close()
   484			for rows.Next() {
   485				var id string
   486				if rows.Scan(&id) != nil {
   487					continue
   488				}
   489				s, err := app.loadSample(ctx, id)
   490				if err != nil {
   491					continue
   492				}
   493				if sampleTypeFilter != "" && s.SampleTypeID != sampleTypeFilter {
   494					continue
   495				}
   496				item := map[string]interface{}{
   497					"sampleId":         s.ID,
