   499					"serviceability":   s.Serviceability,
   500					"currentHolderId":  ptrStr(s.CurrentHolderID),
   501					"locationStale":    isStale(s.LocationRecordedAt, now),
   502					"deliveryDeadline": rfc3339(s.Deadline),
   503				}
