   519					item["exception"] = ex
   520				}
   521				samples = append(samples, item)
   522			}
   523		}
   524	
   525		workers := []map[string]interface{}{}
   526		wrows, err := app.store.pg.Query(ctx, `
   527	SELECT u.id, u.username, u.full_name, u.available, u.capacity_units, u.latest_lat, u.latest_lng, u.location_recorded_at,
   528	  COALESCE((SELECT COUNT(*) FROM assignments a WHERE (a.worker_id=u.id OR a.offered_to=u.id) AND a.status NOT IN ('completed','cancelled')),0)
   529	FROM users u
   530	JOIN user_roles ur ON ur.user_id=u.id
   531	WHERE ur.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team')
   532	GROUP BY u.id`)
   533		if err == nil {
   534			defer wrows.Close()
   535			for wrows.Next() {
   536				var id, uname, fname string
   537				var avail bool
   538				var cap, load int
   539				var lat, lng *float64
   540				var rec *time.Time
   541				if wrows.Scan(&id, &uname, &fname, &avail, &cap, &lat, &lng, &rec, &load) != nil {
   542					continue
   543				}
   544				item := map[string]interface{}{
   545					"workerId": id, "username": uname, "fullName": fname,
   546					"available": avail, "capacityUnits": cap, "activeLoad": load,
   547					"locationStale": isStale(rec, now),
   548				}
   549				if lat != nil && lng != nil {
   550					item["latestLocation"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
   551				}
   552				if rec != nil {
   553					item["locationRecordedAt"] = rfc3339(*rec)
   554				}
   555				workers = append(workers, item)
   556			}
   557		}
   558	
   559		locations := []map[string]interface{}{}
   560		locs, _ := app.loadLocations(ctx)
   561		for _, l := range locs {
   562			if u.ActiveRole == RoleNodeHandler || u.ActiveRole == RoleLaboratoryTeam {
   563				if u.AssignedLocationID != l.ID {
   564					continue
   565				}
   566			}
   567			cap := Capacity{
   568				CapacityUnits: l.CapacityUnits, ReservedUnits: l.ReservedUnits,
   569				CooledCapacityUnits: l.CooledCap, CooledReservedUnits: l.CooledReserved,
   570			}.fill()
   571			item := map[string]interface{}{
   572				"id":              l.ID,
   573				"locationId":      l.ID,
   574				"name":            l.Name,
   575				"coordinate":      map[string]interface{}{"latitude": l.Lat, "longitude": l.Lng},
   576				"active":          l.Active,
   577				"coverageKm":      l.CoverageKm,
   578				"handlingMinutes": l.HandlingMinutes,
   579				"functions": LocationFunctions{
   580					CollectionPoint: l.FnCollection, TransferPoint: l.FnTransfer, Hub: l.FnHub, Laboratory: l.FnLaboratory,
