   601	
   602		exceptions := []map[string]interface{}{}
   603		erows, err := app.store.pg.Query(ctx, `SELECT id, sample_id, laboratory_id, reason, observed_at FROM exceptions ORDER BY observed_at DESC LIMIT 200`)
