   610				if erows.Scan(&id, &sid, &lab, &reason, &at) != nil {
   611					continue
   612				}
   613				item := map[string]interface{}{"exceptionId": id, "sampleId": sid, "reason": reason, "observedAt": rfc3339(at)}
   614				if lab != nil {
   615					item["laboratoryId"] = *lab
   616				}
   617				exceptions = append(exceptions, item)
   618			}
   619		}
   620	
   621		return map[string]interface{}{
   622			"generatedAt": rfc3339(now),
   623			"samples":     samples,
   624			"workers":     workers,
   625			"locations":   locations,
   626			"routes":      routes,
