   920	func (app *App) replanJourney(ctx context.Context, u *SessionUser, journeyID string) (string, string, error) {
   921		sids := app.journeySampleIDs(ctx, journeyID)
   922		if len(sids) == 0 {
   923			return "not_required", "", nil
   924		}
   925		// cancel unfinished assignments, keep completed
   926		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
   927		app.releaseJourneyCapacity(ctx, journeyID)
   928		_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced' WHERE id=$1`, journeyID)
   929	
   930		// replan first unfinished sample (and attach others if possible)
   931		var lastStatus, lastID string
   932		for _, sid := range sids {
   933			s, err := app.loadSample(ctx, sid)
   934			if err != nil || s.Status == "received" || s.Status == "cancelled" {
   935				continue
   936			}
   937			st, _ := app.loadSampleType(ctx, s.SampleTypeID)
   938			plan, err := app.evaluateServiceability(ctx, Coord{s.OriginLat, s.OriginLng}, s.OriginType, "", s.SampleTypeID, time.Now(), s.Deadline, s.Earliest, s.Latest)
   939			if err != nil || !plan.Serviceable {
   940				reason := "no_valid_route"
   941				status := "exception"
   942				if plan != nil && plan.Reason == "deadline_unreachable" {
   943					status = "expired"
   944					reason = "deadline_unreachable"
   945				}
   946				_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status=$2, exception=$3 WHERE id=$1`, sid, status, asJSON(map[string]interface{}{"reason": reason}))
   947				if status == "expired" {
   948					lastStatus = "expired"
   949				} else {
   950					lastStatus = "exception"
   951				}
   952				continue
   953			}
   954			req := collectionReqBody{
   955				Origin: Coord{s.OriginLat, s.OriginLng}, OriginType: s.OriginType, SampleTypeID: s.SampleTypeID,
   956				ContainerType: s.ContainerType, TemperatureMinC: s.TempMin, TemperatureMaxC: s.TempMax,
   957			}
   958			jid, _, err := app.materializeJourney(ctx, u, sid, req, plan, st, s.Sealed, time.Now())
   959			if err != nil {
   960				lastStatus = "exception"
   961				continue
   962			}
   963			_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2 WHERE id=$1`, jid, journeyID)
   964			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE id=$1`, sid, jid, plan.TargetLab)
   965			lastStatus = "replaced"
   966			lastID = jid
   967		}
   968		if lastStatus == "" {
   969			lastStatus = "not_required"
   970		}
   971		return lastStatus, lastID, nil
   972	}
