   992	func (app *App) offerOne(ctx context.Context, assignmentID string) string {
   993		var kind string
   994		var sampleID, nodeID, labID *string
   995		var expected *string
   996		err := app.store.pg.QueryRow(ctx, `SELECT kind, sample_id, node_id, laboratory_id, expected_sample_type_id FROM assignments WHERE id=$1`, assignmentID).
   997			Scan(&kind, &sampleID, &nodeID, &labID, &expected)
   998		if err != nil {
   999			return ""
  1000		}
  1001		role := RoleDeliveryPartner
  1002		switch kind {
  1003		case "collection":
  1004			role = RoleCollectionProfessional
  1005		case "node":
  1006			role = RoleNodeHandler
  1007		case "laboratory":
  1008			role = RoleLaboratoryTeam
  1009		}
  1010		q := `
  1011	SELECT u.id FROM users u
  1012	JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
  1013	WHERE u.active=TRUE AND u.available=TRUE
  1014	  AND (u.decline_penalty_until IS NULL OR u.decline_penalty_until < now())
  1015	`
  1016		args := []interface{}{role}
  1017		if (kind == "node" || kind == "laboratory") && (nodeID != nil || labID != nil) {
  1018			loc := ""
  1019			if nodeID != nil {
  1020				loc = *nodeID
  1021			}
  1022			if labID != nil {
  1023				loc = *labID
  1024			}
  1025			q += ` AND u.assigned_location_id=$2`
  1026			args = append(args, loc)
  1027		}
  1028		q += ` ORDER BY COALESCE(u.last_offered_at, to_timestamp(0)) ASC, COALESCE(u.last_assigned_at, to_timestamp(0)) ASC,
  1029	  (SELECT COUNT(*) FROM assignments a WHERE a.worker_id=u.id AND a.status NOT IN ('completed','cancelled')) ASC
  1030	LIMIT 5`
  1031		wrows, err := app.store.pg.Query(ctx, q, args...)
  1032		if err != nil {
  1033			return ""
  1034		}
  1035		defer wrows.Close()
  1036		var candidates []string
  1037		for wrows.Next() {
  1038			var id string
  1039			if wrows.Scan(&id) == nil {
  1040				candidates = append(candidates, id)
  1041			}
  1042		}
  1043		if len(candidates) == 0 {
  1044			if kind == "collection" && expected != nil {
  1045				// no qualified collector — flag after timeout; we flag immediately only if never anyone
  1046				var n int
  1047				_ = app.store.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1 WHERE u.active`, RoleCollectionProfessional).Scan(&n)
  1048				if n == 0 && sampleID != nil {
  1049					_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`,
  1050						*sampleID, asJSON(map[string]interface{}{"reason": "no_qualified_worker"}))
  1051					_, _ = app.store.pg.Exec(ctx, `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,now())`,
  1052						newUUID(), *sampleID, "no_qualified_worker")
  1053				}
  1054			}
  1055			return ""
  1056		}
  1057		// qualification filter for collection
  1058		chosen := candidates[0]
  1059		if kind == "collection" && expected != nil {
  1060			st, _ := app.loadSampleType(ctx, *expected)
  1061			if st != nil && st.QualifiedCollector {
  1062				found := ""
  1063				for _, cid := range candidates {
  1064					wu, err := app.loadUser(ctx, cid, "")
  1065					if err != nil {
  1066						continue
  1067					}
  1068					if contains(wu.Qualifications, st.RequiredQualification) || hasActiveCert(wu.Certifications, st.RequiredQualification) {
  1069						found = cid
  1070						break
  1071					}
  1072				}
  1073				if found == "" {
  1074					if sampleID != nil {
  1075						// leave pending; background will eventually exception
  1076					}
  1077					return ""
  1078				}
  1079				chosen = found
  1080			}
  1081		}
  1082		exp := time.Now().Add(offerTTL)
  1083		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3 WHERE id=$1`, assignmentID, chosen, exp)
  1084		_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=now() WHERE id=$1`, chosen)
  1085		app.emit("assignment.offered", "assignment", assignmentID, map[string]interface{}{"workerId": chosen})
  1086		return chosen
  1087	}
