  1089	func (app *App) handleEvents(w http.ResponseWriter, r *http.Request) {
  1090		u := currentUser(r)
  1091		if r.Header.Get("Upgrade") == "websocket" || r.Header.Get("Connection") == "Upgrade" {
  1092			app.handleWS(w, r, u)
  1093			return
  1094		}
  1095		since := int64(0)
  1096		if s := r.URL.Query().Get("since"); s != "" {
  1097			var n int64
  1098			if _, err := parseInt64(s, &n); err == nil {
  1099				since = n
  1100			}
  1101		}
  1102		rows, err := app.store.pg.Query(r.Context(), `
  1103	SELECT id, type, entity_type, entity_id, payload, created_at
  1104	FROM realtime_events WHERE id > $1 ORDER BY id ASC LIMIT 200`, since)
  1105		if err != nil {
  1106			writeErr(w, 500, "internal_error", "internal error")
  1107			return
  1108		}
  1109		defer rows.Close()
  1110		events := []map[string]interface{}{}
  1111		var cursor int64 = since
  1112		for rows.Next() {
  1113			var id int64
  1114			var typ, et, eid string
  1115			var payload []byte
  1116			var created time.Time
  1117			if rows.Scan(&id, &typ, &et, &eid, &payload, &created) != nil {
  1118				continue
  1119			}
  1120			var p map[string]interface{}
  1121			_ = json.Unmarshal(payload, &p)
  1122			if p == nil {
  1123				p = map[string]interface{}{}
  1124			}
  1125			events = append(events, map[string]interface{}{
  1126				"id": id, "type": typ, "entityType": et, "entityId": eid, "payload": p, "createdAt": rfc3339(created),
  1127			})
  1128			cursor = id
  1129		}
  1130		writeData(w, 200, map[string]interface{}{"events": events, "cursor": cursor})
  1131	}
  1132	
  1133	func parseInt64(s string, out *int64) (int, error) {
  1134		var n int64
  1135		for _, c := range s {
  1136			if c < '0' || c > '9' {
  1137				return 0, herr(400, "invalid_json", "invalid since")
  1138			}
  1139			n = n*10 + int64(c-'0')
  1140		}
  1141		*out = n
  1142		return 0, nil
  1143	}

