   101	func tokenFromWSProtocol(r *http.Request) string {
   102		raw := r.Header.Get("Sec-WebSocket-Protocol")
   103		if raw == "" {
   104			return ""
   105		}
   106		for _, p := range strings.Split(raw, ",") {
   107			p = strings.TrimSpace(p)
   108			if !strings.HasPrefix(strings.ToLower(p), "bearer.") {
   109				continue
   110			}
   111			enc := p[len("bearer."):]
   112			if b, err := decodeWSToken(enc); err == nil && len(b) > 0 {
   113				return string(b)
   114			}
   115			if enc != "" {
   116				return enc
   117			}
   118		}
   119		return ""
   120	}
