   580	func (app *App) bumpPlan(ctx context.Context, journeyID string, expected int) error {
   581		var ver int
   582		var status string
   583		err := app.store.pg.QueryRow(ctx, `SELECT plan_version, status FROM journeys WHERE id=$1`, journeyID).Scan(&ver, &status)
   584		if err != nil {
   585			return herr(404, "not_found", "journey not found")
   586		}
   587		if expected > 0 && ver != expected {
   588			return herr(409, "stale_plan", "stale plan version")
   589		}
   590		if status == "completed" || status == "cancelled" {
   591			return herr(409, "inactive_plan", "inactive plan")
   592		}
   593		_, err = app.store.pg.Exec(ctx, `UPDATE journeys SET plan_version = plan_version + 1 WHERE id=$1 AND plan_version=$2`, journeyID, ver)
   594		if err != nil {
   595			return herr(409, "concurrent_conflict", "concurrent conflict")
   596		}
   597		return nil
   598	}
