   144			{"33333333-3333-3333-3333-333333333333", "Frost", "Frost", "cooled", 2, 8, true, true},
   145			{"44444444-4444-4444-4444-444444444444", "Pulse", "Pulse", "standard", 2, 25, false, false},
   146		}
   147		// Amber incompatible with Indigo and vice versa
   148		amberID := "11111111-1111-1111-1111-111111111111"
   149		indigoID := "22222222-2222-2222-2222-222222222222"
   150		for _, d := range defaults {
