   449		}
   450		if u.ActiveRole == RoleRequester {
   451			return s.RequesterID == u.UserID
   452		}
   453		// workers see samples they hold or are assigned
   454		if s.CurrentHolderID != nil && *s.CurrentHolderID == u.UserID {
   455			return true
   456		}
   457		var n int
   458		_ = app.store.pg.QueryRow(context.Background(), `
   459	SELECT COUNT(*) FROM assignments
   460	WHERE sample_id=$1 AND (worker_id=$2 OR offered_to=$2)`, s.ID, u.UserID).Scan(&n)
   461		return n > 0
   462	}
