   376	func cors(next http.Handler) http.Handler {
   377		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   378			w.Header().Set("Access-Control-Allow-Origin", "*")
   379			w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Sec-WebSocket-Protocol")
   380			w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
   381			if r.Method == http.MethodOptions {
   382				w.WriteHeader(204)
   383				return
   384			}
   385			next.ServeHTTP(w, r)
   386		})
   387	}
