   362	func (app *App) releaseJourneyCapacity(ctx context.Context, journeyID string) {
   363		rows, err := app.store.pg.Query(ctx, `SELECT id, resource_id, resource_kind, regular_units, cooled_units FROM capacity_reservations WHERE journey_id=$1 AND active=TRUE`, journeyID)
   364		if err != nil {
   365			return
   366		}
   367		defer rows.Close()
   368		type resv struct {
   369			id, rid, kind string
   370			reg, cool     int
   371		}
   372		var list []resv
   373		for rows.Next() {
   374			var r resv
   375			if rows.Scan(&r.id, &r.rid, &r.kind, &r.reg, &r.cool) == nil {
   376				list = append(list, r)
   377			}
   378		}
   379		for _, r := range list {
   380			if r.kind == "location" {
   381				_, _ = app.store.pg.Exec(ctx, `UPDATE locations SET reserved_units = GREATEST(reserved_units-$2,0), cooled_reserved_units = GREATEST(cooled_reserved_units-$3,0) WHERE id=$1`, r.rid, r.reg, r.cool)
   382			} else {
   383				_, _ = app.store.pg.Exec(ctx, `UPDATE connections SET reserved_units = GREATEST(reserved_units-$2,0), cooled_reserved_units = GREATEST(cooled_reserved_units-$3,0) WHERE id=$1`, r.rid, r.reg, r.cool)
   384			}
   385			_, _ = app.store.pg.Exec(ctx, `UPDATE capacity_reservations SET active=FALSE WHERE id=$1`, r.id)
   386		}
   387	}
