   273	func (app *App) replanJourney(ctx context.Context, u *SessionUser, journeyID string) (string, string, error) {
   274		sids := app.journeySampleIDs(ctx, journeyID)
   275		if len(sids) == 0 {
   276			return "not_required", "", nil
   277		}
   278		// cancel unfinished assignments, keep completed
   279		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
   280		app.releaseJourneyCapacity(ctx, journeyID)
   281		_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced' WHERE id=$1`, journeyID)
   282	
   283		// replan first unfinished sample (and attach others if possible)
   284		var lastStatus, lastID string
   285		for _, sid := range sids {
   286			s, err := app.loadSample(ctx, sid)
   287			if err != nil || s.Status == "received" || s.Status == "cancelled" {
   288				continue
   289			}
   290			st, _ := app.loadSampleType(ctx, s.SampleTypeID)
   291			plan, err := app.evaluateServiceability(ctx, Coord{s.OriginLat, s.OriginLng}, s.OriginType, "", s.SampleTypeID, time.Now(), s.Deadline, s.Earliest, s.Latest)
   292			if err != nil || !plan.Serviceable {
   293				reason := "no_valid_route"
   294				status := "exception"
   295				if plan != nil && plan.Reason == "deadline_unreachable" {
   296					status = "expired"
   297					reason = "deadline_unreachable"
   298				}
   299				_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status=$2, exception=$3 WHERE id=$1`, sid, status, asJSON(map[string]interface{}{"reason": reason}))
   300				if status == "expired" {
   301					lastStatus = "expired"
   302				} else {
   303					lastStatus = "exception"
   304				}
   305				continue
   306			}
   307			req := collectionReqBody{
   308				Origin: Coord{s.OriginLat, s.OriginLng}, OriginType: s.OriginType, SampleTypeID: s.SampleTypeID,
   309				ContainerType: s.ContainerType, TemperatureMinC: s.TempMin, TemperatureMaxC: s.TempMax,
   310			}
   311			jid, _, err := app.materializeJourney(ctx, u, sid, req, plan, st, s.Sealed, time.Now())
   312			if err != nil {
   313				lastStatus = "exception"
   314				continue
   315			}
   316			_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2 WHERE id=$1`, jid, journeyID)
   317			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE id=$1`, sid, jid, plan.TargetLab)
   318			lastStatus = "replaced"
   319			lastID = jid
   320		}
   321		if lastStatus == "" {
   322			lastStatus = "not_required"
   323		}
   324		return lastStatus, lastID, nil
   325	}
