   350			Scan(&kind, &sampleID, &nodeID, &labID, &expected)
   351		if err != nil {
   352			return ""
   353		}
   354		role := RoleDeliveryPartner
   355		switch kind {
   356		case "collection":
   357			role = RoleCollectionProfessional
   358		case "node":
   359			role = RoleNodeHandler
   360		case "laboratory":
   361			role = RoleLaboratoryTeam
   362		}
   363		q := `
   364	SELECT u.id FROM users u
   365	JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
   366	WHERE u.active=TRUE AND u.available=TRUE
   367	  AND (u.decline_penalty_until IS NULL OR u.decline_penalty_until < now())
   368	`
   369		args := []interface{}{role}
   370		if (kind == "node" || kind == "laboratory") && (nodeID != nil || labID != nil) {
   371			loc := ""
   372			if nodeID != nil {
   373				loc = *nodeID
   374			}
   375			if labID != nil {
   376				loc = *labID
   377			}
   378			q += ` AND u.assigned_location_id=$2`
   379			args = append(args, loc)
   380		}
   381		q += ` ORDER BY COALESCE(u.last_offered_at, to_timestamp(0)) ASC, COALESCE(u.last_assigned_at, to_timestamp(0)) ASC,
   382	  (SELECT COUNT(*) FROM assignments a WHERE a.worker_id=u.id AND a.status NOT IN ('completed','cancelled')) ASC
   383	LIMIT 5`
   384		wrows, err := app.store.pg.Query(ctx, q, args...)
   385		if err != nil {
   386			return ""
   387		}
   388		defer wrows.Close()
   389		var candidates []string
   390		for wrows.Next() {
   391			var id string
   392			if wrows.Scan(&id) == nil {
   393				candidates = append(candidates, id)
   394			}
   395		}
   396		if len(candidates) == 0 {
   397			if kind == "collection" && expected != nil {
   398				// no qualified collector — flag after timeout; we flag immediately only if never anyone
   399				var n int
   400				_ = app.store.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1 WHERE u.active`, RoleCollectionProfessional).Scan(&n)
   401				if n == 0 && sampleID != nil {
   402					_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`,
   403						*sampleID, asJSON(map[string]interface{}{"reason": "no_qualified_worker"}))
   404					_, _ = app.store.pg.Exec(ctx, `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,now())`,
   405						newUUID(), *sampleID, "no_qualified_worker")
   406				}
   407			}
   408			return ""
   409		}
   410		// qualification filter for collection
   411		chosen := candidates[0]
   412		if kind == "collection" && expected != nil {
   413			st, _ := app.loadSampleType(ctx, *expected)
   414			if st != nil && st.QualifiedCollector {
   415				found := ""
   416				for _, cid := range candidates {
   417					wu, err := app.loadUser(ctx, cid, "")
   418					if err != nil {
   419						continue
   420					}
   421					if contains(wu.Qualifications, st.RequiredQualification) || hasActiveCert(wu.Certifications, st.RequiredQualification) {
   422						found = cid
   423						break
   424					}
   425				}
   426				if found == "" {
   427					if sampleID != nil {
   428						// leave pending; background will eventually exception
   429					}
   430					return ""
   431				}
   432				chosen = found
   433			}
   434		}
   435		exp := time.Now().Add(offerTTL)
   436		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3 WHERE id=$1`, assignmentID, chosen, exp)
