   340			}
   341			s, err := app.loadSample(r.Context(), req.SampleID)
   342			if err != nil {
   343				return 0, nil, err
   344			}
   345			if s.Status == "received" || s.Status == "cancelled" {
   346				return 0, nil, herr(409, "terminal_sample", "sample is terminal")
   347			}
   348			if s.CurrentHolderID == nil || *s.CurrentHolderID != u.UserID {
   349				if !u.isDispatcher() {
   350					return 0, nil, herr(403, "forbidden", "not current holder")
   351				}
   352			}
   353			compliant := req.ObservedTemperatureC >= s.TempMin && req.ObservedTemperatureC <= s.TempMax
   354			if req.ContainerType != "" && s.ContainerType != "" && req.ContainerType != s.ContainerType {
   355				compliant = false
   356			}
   357			cid := newUUID()
