   360	VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, cid, s.ID, req.AssignmentID, nilIfEmpty(req.LocationID), req.ContainerType, req.ObservedTemperatureC, at, compliant)
   361			status := s.Status
   362			if !compliant {
