   389	func (app *App) handleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
   390		u := currentUser(r)
   391		if u.ActiveRole != RoleRequester && !u.isDispatcher() && u.ActiveRole != RoleAdministrator {
   392			writeErr(w, 403, "forbidden", "forbidden")
