   394		}
   395		body := readBody(r)
   396		app.withIdem(w, r, body, false, func() (int, interface{}, error) {
   397			req, reqAt, dead, earliest, latest, err := app.parseCollectionBody(body)
   398			if err != nil {
   399				return 0, nil, err
   400			}
   401			out, err := app.createSampleAndPlan(r.Context(), u, req, reqAt, dead, earliest, latest, false)
   402			if err != nil {
