   412			RoleCollectionProfessional: true, RoleDeliveryPartner: true,
   413			RoleNodeHandler: true, RoleLaboratoryTeam: true, RoleAdministrator: true, RoleDispatcher: true,
   414		}
   415		if !allowed[u.ActiveRole] {
   416			writeErr(w, 403, "forbidden", "forbidden")
