   422			if err != nil {
   423				return 0, nil, err
   424			}
   425			if req.OriginType == "" {
   426				req.OriginType = "node"
   427			}
   428			if req.OriginType == "home" {
   429				return 0, nil, herr(400, "invalid_origin_type", "pre-sealed origin cannot be home")
   430			}
   431			out, err := app.createSampleAndPlan(r.Context(), u, req, reqAt, dead, earliest, latest, true)
   432			if err != nil {
   433				return 0, nil, err
   434			}
   435			return 201, out, nil
   436		})
