   359		dist[from] = 0
   360		type item struct {
   361			id   string
   362			mins int
   363		}
   364		q := []item{{from, 0}}
   365		for len(q) > 0 {
   366			sort.Slice(q, func(i, j int) bool { return q[i].mins < q[j].mins })
   367			cur := q[0]
   368			q = q[1:]
   369			if cur.mins != dist[cur.id] {
   370				continue
   371			}
   372			if cur.id == to {
