   229	func (app *App) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
   230		u := currentUser(r)
   231		body := readBody(r)
   232		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   233			var req struct {
   234				AssignmentID string `json:"assignmentId"`
   235			}
   236			if err := decodeBody(body, &req); err != nil {
   237				return 0, nil, herr(400, "invalid_json", "invalid json")
   238			}
   239			var status string
   240			var offered, worker *string
   241			err := app.store.pg.QueryRow(r.Context(), `SELECT status, offered_to, worker_id FROM assignments WHERE id=$1`, req.AssignmentID).
   242				Scan(&status, &offered, &worker)
   243			if err != nil {
   244				return 0, nil, herr(404, "not_found", "assignment not found")
   245			}
   246			if worker != nil && *worker == u.UserID && (status == "accepted" || status == "in_progress") {
   247				return 201, map[string]interface{}{"assignmentId": req.AssignmentID, "workerId": u.UserID, "status": "accepted"}, nil
   248			}
   249			if offered == nil || *offered != u.UserID {
   250				if !u.isDispatcher() {
   251					return 0, nil, herr(409, "offer_not_available", "offer not available")
   252				}
   253			}
   254			if status != "offered" && status != "pending" && !u.isDispatcher() {
   255				return 0, nil, herr(409, "offer_not_available", "offer not available")
   256			}
   257			_, err = app.store.pg.Exec(r.Context(), `
   258	UPDATE assignments SET status='accepted', worker_id=$2, accepted_at=now(), offered_to=NULL WHERE id=$1`, req.AssignmentID, u.UserID)
   259			if err != nil {
   260				return 0, nil, err
   261			}
   262			_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET last_assigned_at=now() WHERE id=$1`, u.UserID)
   263			app.audit(r.Context(), u.UserID, u.ActiveRole, "accept_assignment", "assignment", req.AssignmentID, true, nil)
   264			app.emit("assignment.accepted", "assignment", req.AssignmentID, map[string]interface{}{"workerId": u.UserID})
   265			return 201, map[string]interface{}{
   266				"assignmentId": req.AssignmentID,
   267				"workerId":     u.UserID,
   268				"status":       "accepted",
   269			}, nil
   270		})
   271	}
