   273	func (app *App) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
   274		u := currentUser(r)
   275		body := readBody(r)
   276		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   277			var req struct {
   278				AssignmentID string `json:"assignmentId"`
   279				Reason       string `json:"reason"`
   280				DeclinedAt   string `json:"declinedAt"`
   281			}
   282			if err := decodeBody(body, &req); err != nil {
   283				return 0, nil, herr(400, "invalid_json", "invalid json")
   284			}
   285			at := time.Now().UTC()
   286			if req.DeclinedAt != "" {
   287				t, err := parseTime(req.DeclinedAt)
   288				if err != nil {
   289					return 0, nil, herr(400, "invalid_time", "invalid declinedAt")
   290				}
   291				at = t
   292			}
   293			var status string
   294			var offered *string
   295			err := app.store.pg.QueryRow(r.Context(), `SELECT status, offered_to FROM assignments WHERE id=$1`, req.AssignmentID).
   296				Scan(&status, &offered)
   297			if err != nil {
   298				return 0, nil, herr(404, "not_found", "assignment not found")
   299			}
   300			if offered == nil || *offered != u.UserID {
   301				if !u.isDispatcher() {
   302					return 0, nil, herr(409, "offer_not_available", "offer not available")
   303				}
   304			}
   305			_, _ = app.store.pg.Exec(r.Context(), `
   306	UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$2, declined_at=$3 WHERE id=$1`,
   307				req.AssignmentID, u.UserID, at)
   308			_, _ = app.store.pg.Exec(r.Context(), `
   309	UPDATE users SET decline_count = decline_count + 1, decline_penalty_until=$2 WHERE id=$1`,
   310				u.UserID, time.Now().Add(declinePenalty))
   311			next := app.offerOne(r.Context(), req.AssignmentID)
   312			app.audit(r.Context(), u.UserID, u.ActiveRole, "decline_assignment", "assignment", req.AssignmentID, true, map[string]interface{}{"reason": req.Reason})
   313			out := map[string]interface{}{
   314				"assignmentId": req.AssignmentID,
   315				"status":       "pending",
   316				"declinedBy":   u.UserID,
   317				"declinedAt":   rfc3339(at),
   318			}
   319			if next != "" {
   320				out["reofferedTo"] = next
   321			}
   322			return 201, out, nil
   323		})
   324	}
