   446	func (app *App) canSeeSample(u *SessionUser, s *sampleRow) bool {
   447		if u.isDispatcher() {
   448			return true
   449		}
   450		if u.ActiveRole == RoleRequester {
   451			return s.RequesterID == u.UserID
   452		}
   453		// workers see samples they hold or are assigned
   454		if s.CurrentHolderID != nil && *s.CurrentHolderID == u.UserID {
