   299	func (app *App) reserveCapacity(ctx context.Context, fromID, toID, journeyID, sampleID string, cooled bool) error {
   300		conns, err := app.loadConnections(ctx)
   301		if err != nil {
   302			return err
   303		}
   304		c := findConn(conns, fromID, toID)
   305		if c == nil {
   306			return nil
   307		}
   308		reg, cool := 1, 0
   309		if cooled {
   310			reg, cool = 0, 1
   311			if c.CooledCap > 0 && c.CooledCap-c.CooledReserved < 1 {
   312				return herr(409, "cooled_capacity_exhausted", "cooled capacity exhausted")
   313			}
   314			_, err = app.store.pg.Exec(ctx, `UPDATE connections SET cooled_reserved_units = cooled_reserved_units + 1 WHERE id=$1`, c.ID)
   315		} else {
   316			if c.CapacityUnits > 0 && c.CapacityUnits-c.ReservedUnits < 1 {
   317				return herr(409, "capacity_exhausted", "capacity exhausted")
   318			}
   319			if c.CapacityUnits > 0 {
   320				_, err = app.store.pg.Exec(ctx, `UPDATE connections SET reserved_units = reserved_units + 1 WHERE id=$1`, c.ID)
   321			}
   322		}
   323		if err != nil {
   324			return err
   325		}
   326		_, _ = app.store.pg.Exec(ctx, `
   327	INSERT INTO capacity_reservations (id, resource_id, resource_kind, journey_id, sample_id, regular_units, cooled_units, active)
   328	VALUES ($1,$2,'connection',$3,$4,$5,$6,TRUE)`, newUUID(), c.ID, journeyID, sampleID, reg, cool)
