   332	func (app *App) reserveLocationCapacity(ctx context.Context, locID, journeyID, sampleID string, cooled bool) error {
   333		var cap, reserved, ccap, cres int
   334		err := app.store.pg.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM locations WHERE id=$1`, locID).
   335			Scan(&cap, &reserved, &ccap, &cres)
   336		if err != nil {
   337			return nil
   338		}
   339		reg, cool := 1, 0
   340		if cooled {
   341			reg, cool = 0, 1
   342			if ccap > 0 && ccap-cres < 1 {
   343				return herr(409, "cooled_capacity_exhausted", "cooled capacity exhausted")
   344			}
   345			if ccap > 0 {
   346				_, _ = app.store.pg.Exec(ctx, `UPDATE locations SET cooled_reserved_units = cooled_reserved_units + 1 WHERE id=$1`, locID)
   347			}
   348		} else {
   349			if cap > 0 && cap-reserved < 1 {
   350				return herr(409, "capacity_exhausted", "capacity exhausted")
   351			}
   352			if cap > 0 {
   353				_, _ = app.store.pg.Exec(ctx, `UPDATE locations SET reserved_units = reserved_units + 1 WHERE id=$1`, locID)
   354			}
   355		}
   356		_, _ = app.store.pg.Exec(ctx, `
   357	INSERT INTO capacity_reservations (id, resource_id, resource_kind, journey_id, sample_id, regular_units, cooled_units, active)
   358	VALUES ($1,$2,'location',$3,$4,$5,$6,TRUE)`, newUUID(), locID, journeyID, sampleID, reg, cool)
   359		return nil
   360	}
