   289				"username":               u.Username,
   290				"fullName":               u.FullName,
   291				"roles":                  u.Roles,
   292				"activeRole":             u.ActiveRole,
   293				"roleSelectionRequired":  u.ActiveRole == "" && len(u.Roles) > 1,
   294			},
   295			"serverTime": rfc3339(time.Now()),
   296		}
   297		if u.ActiveRole == RoleRequester || u.isDispatcher() {
   298			samples := []map[string]interface{}{}
   299			q := `SELECT id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC LIMIT 200`
   300			args := []interface{}{u.UserID}
   301			if u.isDispatcher() {
   302				q = `SELECT id FROM samples ORDER BY created_at DESC LIMIT 200`
   303				args = nil
   304			}
   305			rows, err := app.store.pg.Query(r.Context(), q, args...)
   306			if err == nil {
   307				defer rows.Close()
   308				for rows.Next() {
   309					var sid string
   310					if rows.Scan(&sid) != nil {
   311						continue
   312					}
   313					s, err := app.loadSample(r.Context(), sid)
   314					if err != nil {
   315						continue
   316					}
   317					samples = append(samples, app.sampleStatePayload(r.Context(), s))
   318				}
   319			}
   320			data["requesterSamples"] = samples
   321		}
   322		if u.isDispatcher() || u.ActiveRole == RoleNodeHandler || u.ActiveRole == RoleLaboratoryTeam {
   323			ops, _ := app.operationsState(r.Context(), u, "")
   324			data["operations"] = ops
   325		}
   326		writeData(w, 200, data)
   327	}
