   658		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   659			var req struct {
   660				TargetJourneyID     string   `json:"targetJourneyId"`
   661				ExpectedPlanVersion int      `json:"expectedPlanVersion"`
   662				SourceJourneyIDs    []string `json:"sourceJourneyIds"`
   663			}
   664			if err := decodeBody(body, &req); err != nil {
   665				return 0, nil, herr(400, "invalid_json", "invalid json")
   666			}
   667			if err := app.bumpPlan(r.Context(), req.TargetJourneyID, req.ExpectedPlanVersion); err != nil {
   668				return 0, nil, err
   669			}
   670			// pulse cannot batch
   671			targetSamples := app.journeySampleIDs(r.Context(), req.TargetJourneyID)
   672			types := map[string]*sampleTypeRow{}
   673			checkPulse := func(sids []string) error {
   674				for _, sid := range sids {
   675					s, err := app.loadSample(r.Context(), sid)
   676					if err != nil {
   677						continue
   678					}
   679					st, _ := app.loadSampleType(r.Context(), s.SampleTypeID)
   680					if st != nil {
   681						types[st.ID] = st
   682						if !st.BatchingAllowed {
   683							return herr(409, "pulse_no_batch", "pulse cannot be batched")
   684						}
   685					}
   686				}
   687				return nil
   688			}
   689			if err := checkPulse(targetSamples); err != nil {
   690				return 0, nil, err
   691			}
   692			for _, src := range req.SourceJourneyIDs {
   693				sids := app.journeySampleIDs(r.Context(), src)
   694				if err := checkPulse(sids); err != nil {
   695					return 0, nil, err
   696				}
   697				// incompatibilities
   698				for _, sid := range sids {
   699					s, _ := app.loadSample(r.Context(), sid)
   700					if s == nil {
   701						continue
   702					}
   703					for _, tid := range targetSamples {
   704						t, _ := app.loadSample(r.Context(), tid)
   705						if t == nil {
   706							continue
   707						}
   708						if contains(s.Incompatible, t.SampleTypeID) || contains(t.Incompatible, s.SampleTypeID) {
   709							return 0, nil, herr(409, "incompatible_batch", "incompatible samples")
   710						}
   711					}
   712					_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.TargetJourneyID, sid)
   713					_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET active_journey_id=$2 WHERE id=$1`, sid, req.TargetJourneyID)
   714					_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET journey_id=$2 WHERE sample_id=$1 AND journey_id=$3 AND status NOT IN ('completed')`, sid, req.TargetJourneyID, src)
   715				}
   716				_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, src)
   717			}
   718			payload, err := app.journeyPlanPayload(r.Context(), req.TargetJourneyID, u.ActiveRole, u.UserID)
   719			if err != nil {
   720				return 0, nil, err
   721			}
   722			app.audit(r.Context(), u.UserID, u.ActiveRole, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]interface{}{"sources": req.SourceJourneyIDs})
   723			return 201, payload, nil
   724		})
