   642			return
   643		}
   644		body := readBody(r)
   645		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   646			var req struct {
   647				JourneyID           string   `json:"journeyId"`
   648				ExpectedPlanVersion int      `json:"expectedPlanVersion"`
   649				SampleIDs           []string `json:"sampleIds"`
   650			}
   651			if err := decodeBody(body, &req); err != nil {
   652				return 0, nil, herr(400, "invalid_json", "invalid json")
   653			}
   654			if err := app.bumpPlan(r.Context(), req.JourneyID, req.ExpectedPlanVersion); err != nil {
   655				return 0, nil, err
   656			}
   657			all := app.journeySampleIDs(r.Context(), req.JourneyID)
   658			if len(req.SampleIDs) == 0 || len(req.SampleIDs) >= len(all) {
   659				return 0, nil, herr(409, "invalid_split", "invalid split")
   660			}
   661			newID := newUUID()
   662			_, err := app.store.pg.Exec(r.Context(), `
   663	INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, total_cost_units, valid)
   664	SELECT $1, $2, 1, route_mode, 'planned', total_cost_units, TRUE FROM journeys WHERE id=$2`, newID, req.JourneyID)
   665			if err != nil {
   666				return 0, nil, err
   667			}
   668			for _, sid := range req.SampleIDs {
   669				_, _ = app.store.pg.Exec(r.Context(), `DELETE FROM journey_samples WHERE journey_id=$1 AND sample_id=$2`, req.JourneyID, sid)
   670				_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, newID, sid)
   671				_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET active_journey_id=$2 WHERE id=$1`, sid, newID)
   672				_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET journey_id=$2 WHERE sample_id=$1 AND journey_id=$3 AND status NOT IN ('completed')`, sid, newID, req.JourneyID)
   673			}
   674			orig, _ := app.journeyPlanPayload(r.Context(), req.JourneyID, u.ActiveRole, u.UserID)
   675			split, _ := app.journeyPlanPayload(r.Context(), newID, u.ActiveRole, u.UserID)
   676			app.audit(r.Context(), u.UserID, u.ActiveRole, "split_journey", "journey", req.JourneyID, true, map[string]interface{}{"splitJourneyId": newID})
   677			return 201, map[string]interface{}{"journey": orig, "splitJourney": split}, nil
   678		})
   679	}
