   229	func (app *App) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
   230		u := currentUser(r)
   231		body := readBody(r)
   232		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   233			var req struct {
   234				AssignmentID string `json:"assignmentId"`
   235			}
   236			if err := decodeBody(body, &req); err != nil {
   237				return 0, nil, herr(400, "invalid_json", "invalid json")
   238			}
   239			var status string
   240			var offered, worker *string
   241			err := app.store.pg.QueryRow(r.Context(), `SELECT status, offered_to, worker_id FROM assignments WHERE id=$1`, req.AssignmentID).
