   176		if q.Role != "" {
   177			ands = append(ands, bson.M{"role": q.Role})
   178		}
   179		if q.Success != nil {
   180			ands = append(ands, bson.M{"success": *q.Success})
   181		}
   182		if q.FromTime != nil || q.ToTime != nil {
   183			rng := bson.M{}
   184			if q.FromTime != nil {
   185				rng["$gte"] = *q.FromTime
   186			}
   187			if q.ToTime != nil {
   188				rng["$lte"] = *q.ToTime
   189			}
   190			ands = append(ands, bson.M{"occurredAt": rng})
   191		}
   192		if len(ands) == 1 {
   193			filter = ands[0]
   194		} else if len(ands) > 1 {
   195			filter = bson.M{"$and": ands}
   196		}
   197		limit := q.Limit
   198		if limit <= 0 {
   199			limit = 500
   200		}
   201		if limit > 5000 {
   202			return nil, herr(400, "invalid_limit", "invalid limit")
   203		}
   204		offset := q.Offset
   205		if offset < 0 {
   206			return nil, herr(400, "invalid_offset", "invalid offset")
   207		}
   208		order := q.Order
   209		if order == "" {
   210			order = "newest_first"
   211		}
   212		if order != "newest_first" && order != "oldest_first" {
   213			return nil, herr(400, "invalid_order", "invalid order")
   214		}
   215		sort := bson.D{{Key: "occurredAt", Value: -1}}
   216		if order == "oldest_first" {
   217			sort = bson.D{{Key: "occurredAt", Value: 1}}
   218		}
   219		total, err := app.store.audit.CountDocuments(ctx, filter)
   220		if err != nil {
   221			return nil, err
   222		}
   223		opts := options.Find().SetSort(sort).SetSkip(int64(offset)).SetLimit(int64(limit))
   224		cur, err := app.store.audit.Find(ctx, filter, opts)
   225		if err != nil {
   226			return nil, err
   227		}
   228		defer cur.Close(ctx)
   229		entries := []map[string]interface{}{}
   230		for cur.Next(ctx) {
   231			var raw bson.M
   232			if err := cur.Decode(&raw); err != nil {
   233				continue
   234			}
   235			entries = append(entries, normalizeAudit(raw))
   236		}
   237		returned := len(entries)
   238		hasMore := int64(offset+returned) < total
   239		res := map[string]interface{}{
   240			"entries":  entries,
   241			"total":    total,
   242			"returned": returned,
   243			"offset":   offset,
   244			"limit":    limit,
   245			"order":    order,
   246			"hasMore":  hasMore,
   247		}
   248		if hasMore {
   249			res["nextOffset"] = offset + returned
   250		}
