   884	func (app *App) replanJourney(ctx context.Context, u *SessionUser, journeyID string) (string, string, error) {
   885		sids := app.journeySampleIDs(ctx, journeyID)
   886		if len(sids) == 0 {
   887			return "not_required", "", nil
   888		}
   889		// cancel unfinished assignments, keep completed
   890		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
   891		app.releaseJourneyCapacity(ctx, journeyID)
   892		_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced' WHERE id=$1`, journeyID)
   893	
   894		// replan first unfinished sample (and attach others if possible)
   895		var lastStatus, lastID string
   896		for _, sid := range sids {
   897			s, err := app.loadSample(ctx, sid)
   898			if err != nil || s.Status == "received" || s.Status == "cancelled" {
   899				continue
   900			}
   901			st, _ := app.loadSampleType(ctx, s.SampleTypeID)
   902			plan, err := app.evaluateServiceability(ctx, Coord{s.OriginLat, s.OriginLng}, s.OriginType, "", s.SampleTypeID, time.Now(), s.Deadline, s.Earliest, s.Latest)
   903			if err != nil || !plan.Serviceable {
   904				reason := "no_valid_route"
   905				status := "exception"
   906				if plan != nil && plan.Reason == "deadline_unreachable" {
   907					status = "expired"
   908					reason = "deadline_unreachable"
   909				}
   910				_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status=$2, exception=$3 WHERE id=$1`, sid, status, asJSON(map[string]interface{}{"reason": reason}))
   911				if status == "expired" {
   912					lastStatus = "expired"
   913				} else {
   914					lastStatus = "exception"
   915				}
   916				continue
   917			}
   918			req := collectionReqBody{
   919				Origin: Coord{s.OriginLat, s.OriginLng}, OriginType: s.OriginType, SampleTypeID: s.SampleTypeID,
   920				ContainerType: s.ContainerType, TemperatureMinC: s.TempMin, TemperatureMaxC: s.TempMax,
   921			}
   922			jid, _, err := app.materializeJourney(ctx, u, sid, req, plan, st, s.Sealed, time.Now())
   923			if err != nil {
   924				lastStatus = "exception"
   925				continue
   926			}
   927			_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2 WHERE id=$1`, jid, journeyID)
   928			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE id=$1`, sid, jid, plan.TargetLab)
   929			lastStatus = "replaced"
   930			lastID = jid
   931		}
   932		if lastStatus == "" {
   933			lastStatus = "not_required"
   934		}
   935		return lastStatus, lastID, nil
   936	}
