   956	func (app *App) offerOne(ctx context.Context, assignmentID string) string {
   957		var kind string
   958		var sampleID, nodeID, labID *string
   959		var expected *string
   960		err := app.store.pg.QueryRow(ctx, `SELECT kind, sample_id, node_id, laboratory_id, expected_sample_type_id FROM assignments WHERE id=$1`, assignmentID).
   961			Scan(&kind, &sampleID, &nodeID, &labID, &expected)
   962		if err != nil {
   963			return ""
   964		}
   965		role := RoleDeliveryPartner
   966		switch kind {
   967		case "collection":
   968			role = RoleCollectionProfessional
   969		case "node":
   970			role = RoleNodeHandler
   971		case "laboratory":
   972			role = RoleLaboratoryTeam
   973		}
   974		q := `
   975	SELECT u.id FROM users u
   976	JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
   977	WHERE u.active=TRUE AND u.available=TRUE
   978	  AND (u.decline_penalty_until IS NULL OR u.decline_penalty_until < now())
   979	`
   980		args := []interface{}{role}
   981		if (kind == "node" || kind == "laboratory") && (nodeID != nil || labID != nil) {
   982			loc := ""
   983			if nodeID != nil {
   984				loc = *nodeID
   985			}
   986			if labID != nil {
   987				loc = *labID
   988			}
   989			q += ` AND u.assigned_location_id=$2`
   990			args = append(args, loc)
   991		}
   992		q += ` ORDER BY COALESCE(u.last_offered_at, to_timestamp(0)) ASC, COALESCE(u.last_assigned_at, to_timestamp(0)) ASC,
   993	  (SELECT COUNT(*) FROM assignments a WHERE a.worker_id=u.id AND a.status NOT IN ('completed','cancelled')) ASC
   994	LIMIT 5`
   995		wrows, err := app.store.pg.Query(ctx, q, args...)
   996		if err != nil {
   997			return ""
   998		}
   999		defer wrows.Close()
  1000		var candidates []string
  1001		for wrows.Next() {
  1002			var id string
  1003			if wrows.Scan(&id) == nil {
  1004				candidates = append(candidates, id)
  1005			}
  1006		}
  1007		if len(candidates) == 0 {
  1008			if kind == "collection" && expected != nil {
  1009				// no qualified collector — flag after timeout; we flag immediately only if never anyone
  1010				var n int
  1011				_ = app.store.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1 WHERE u.active`, RoleCollectionProfessional).Scan(&n)
  1012				if n == 0 && sampleID != nil {
  1013					_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`,
  1014						*sampleID, asJSON(map[string]interface{}{"reason": "no_qualified_worker"}))
  1015					_, _ = app.store.pg.Exec(ctx, `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,now())`,
  1016						newUUID(), *sampleID, "no_qualified_worker")
  1017				}
  1018			}
  1019			return ""
  1020		}
  1021		// qualification filter for collection
  1022		chosen := candidates[0]
  1023		if kind == "collection" && expected != nil {
  1024			st, _ := app.loadSampleType(ctx, *expected)
  1025			if st != nil && st.QualifiedCollector {
  1026				found := ""
  1027				for _, cid := range candidates {
  1028					wu, err := app.loadUser(ctx, cid, "")
  1029					if err != nil {
  1030						continue
  1031					}
  1032					if contains(wu.Qualifications, st.RequiredQualification) || hasActiveCert(wu.Certifications, st.RequiredQualification) {
  1033						found = cid
  1034						break
  1035					}
  1036				}
  1037				if found == "" {
  1038					if sampleID != nil {
  1039						// leave pending; background will eventually exception
  1040					}
  1041					return ""
  1042				}
  1043				chosen = found
  1044			}
  1045		}
  1046		exp := time.Now().Add(offerTTL)
  1047		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3 WHERE id=$1`, assignmentID, chosen, exp)
  1048		_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=now() WHERE id=$1`, chosen)
  1049		app.emit("assignment.offered", "assignment", assignmentID, map[string]interface{}{"workerId": chosen})
  1050		return chosen
