  1097	func parseInt64(s string, out *int64) (int, error) {
  1098		var n int64
  1099		for _, c := range s {
  1100			if c < '0' || c > '9' {
  1101				return 0, herr(400, "invalid_json", "invalid since")
  1102			}
  1103			n = n*10 + int64(c-'0')
  1104		}
  1105		*out = n
  1106		return 0, nil
  1107	}

