   410	func (app *App) recomputeServiceability() {
   411		app.store.mu.Lock()
   412		if app.store.svcComputing {
   413			app.store.mu.Unlock()
   414			return
   415		}
   416		app.store.svcComputing = true
   417		app.store.mu.Unlock()
   418		defer func() {
   419			app.store.mu.Lock()
   420			app.store.svcComputing = false
   421			app.store.mu.Unlock()
   422		}()
   423	
   424		ctx := context.Background()
   425		var rev int
   426		_ = app.store.pg.QueryRow(ctx, `SELECT revision FROM network_meta WHERE id=1`).Scan(&rev)
   427		locs, err := app.loadLocations(ctx)
   428		if err != nil {
   429			return
   430		}
   431		regions := []map[string]interface{}{}
   432		count := 0
   433		for _, l := range locs {
   434			if l.Active && l.FnCollection {
   435				count++
   436				cov := l.CoverageKm
   437				if cov <= 0 {
   438					cov = 5
   439				}
   440				regions = append(regions, map[string]interface{}{
   441					"locationId": l.ID,
   442					"name":       l.Name,
   443					"latitude":   l.Lat,
   444					"longitude":  l.Lng,
   445					"coverageKm": cov,
   446				})
   447			}
   448		}
   449		var ver int
   450		_ = app.store.pg.QueryRow(ctx, `SELECT COALESCE(MAX(version),0)+1 FROM serviceability_snapshots`).Scan(&ver)
   451		if ver < 1 {
   452			ver = 1
   453		}
   454		now := time.Now().UTC()
   455		_, err = app.store.pg.Exec(ctx, `
   456	INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
   457	VALUES ($1,'complete',$2,$3,$4,$5)`, ver, now, rev, asJSON(regions), count)
   458		if err != nil {
   459			return
   460		}
   461		app.store.mu.Lock()
   462		app.store.svcVersion = ver
   463		app.store.svcComputed = now
   464		app.store.svcRevision = rev
   465		app.store.mu.Unlock()
   466	}
