   113	func (app *App) loadTimeline(ctx context.Context, entityIds ...string) []map[string]interface{} {
   114		if len(entityIds) == 0 {
   115			return []map[string]interface{}{}
   116		}
   117		rows, err := app.store.pg.Query(ctx, `
   118	SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
   119	FROM timeline WHERE entity_id = ANY($1) ORDER BY event_id ASC`, entityIds)
   120		if err != nil {
   121			return []map[string]interface{}{}
   122		}
   123		defer rows.Close()
   124		out := []map[string]interface{}{}
   125		for rows.Next() {
   126			var e TimelineEntry
   127			var details []byte
   128			if err := rows.Scan(&e.EventID, &e.Action, &e.ActorID, &e.Role, &e.EntityType, &e.EntityID, &e.Success, &e.OccurredAt, &details); err != nil {
   129				continue
   130			}
   131			e.Details = map[string]interface{}{}
   132			if len(details) > 0 {
   133				_ = json.Unmarshal(details, &e.Details)
   134			}
   135			if e.Details == nil {
   136				e.Details = map[string]interface{}{}
   137			}
   138			out = append(out, map[string]interface{}{
   139				"eventId":    e.EventID,
   140				"action":     e.Action,
   141				"actorId":    e.ActorID,
   142				"role":       e.Role,
   143				"entityType": e.EntityType,
   144				"entityId":   e.EntityID,
   145				"success":    e.Success,
   146				"occurredAt": rfc3339(e.OccurredAt),
   147				"details":    e.Details,
   148			})
   149		}
   150		return out
   151	}
   152	
   153	func (app *App) searchAudit(ctx context.Context, q queryAudit) (map[string]interface{}, error) {
   154		filter := bson.M{}
   155		ands := []bson.M{}
   156		if q.Query != "" {
   157			ands = append(ands, bson.M{"$or": []bson.M{
   158				{"$text": bson.M{"$search": q.Query}},
   159				{"action": bson.M{"$regex": q.Query, "$options": "i"}},
   160				{"entityId": bson.M{"$regex": q.Query, "$options": "i"}},
   161				{"searchText": bson.M{"$regex": q.Query, "$options": "i"}},
   162			}})
   163		}
   164		if q.ActorID != "" {
   165			ands = append(ands, bson.M{"actorId": q.ActorID})
   166		}
   167		if q.EntityType != "" {
   168			ands = append(ands, bson.M{"entityType": q.EntityType})
   169		}
   170		if q.EntityID != "" {
   171			ands = append(ands, bson.M{"entityId": q.EntityID})
   172		}
   173		if q.Action != "" {
   174			ands = append(ands, bson.M{"action": q.Action})
   175		}
   176		if q.Role != "" {
   177			ands = append(ands, bson.M{"role": q.Role})
   178		}
   179		if q.Success != nil {
   180			ands = append(ands, bson.M{"success": *q.Success})
   181		}
   182		if q.FromTime != nil || q.ToTime != nil {
   183			rng := bson.M{}
   184			if q.FromTime != nil {
   185				rng["$gte"] = *q.FromTime
   186			}
   187			if q.ToTime != nil {
   188				rng["$lte"] = *q.ToTime
   189			}
   190			ands = append(ands, bson.M{"occurredAt": rng})
   191		}
   192		if len(ands) == 1 {
   193			filter = ands[0]
   194		} else if len(ands) > 1 {
   195			filter = bson.M{"$and": ands}
   196		}
   197		limit := q.Limit
   198		if limit <= 0 {
   199			limit = 500
   200		}
   201		if limit > 5000 {
   202			return nil, herr(400, "invalid_limit", "invalid limit")
   203		}
   204		offset := q.Offset
   205		if offset < 0 {
   206			return nil, herr(400, "invalid_offset", "invalid offset")
   207		}
   208		order := q.Order
   209		if order == "" {
   210			order = "newest_first"
   211		}
   212		if order != "newest_first" && order != "oldest_first" {
   213			return nil, herr(400, "invalid_order", "invalid order")
   214		}
   215		sort := bson.D{{Key: "occurredAt", Value: -1}}
   216		if order == "oldest_first" {
   217			sort = bson.D{{Key: "occurredAt", Value: 1}}
   218		}
   219		total, err := app.store.audit.CountDocuments(ctx, filter)
   220		if err != nil {
   221			return nil, err
   222		}
   223		opts := options.Find().SetSort(sort).SetSkip(int64(offset)).SetLimit(int64(limit))
   224		cur, err := app.store.audit.Find(ctx, filter, opts)
   225		if err != nil {
   226			return nil, err
   227		}
   228		defer cur.Close(ctx)
   229		entries := []map[string]interface{}{}
   230		for cur.Next(ctx) {
   231			var raw bson.M
   232			if err := cur.Decode(&raw); err != nil {
   233				continue
   234			}
   235			entries = append(entries, normalizeAudit(raw))
   236		}
   237		returned := len(entries)
   238		hasMore := int64(offset+returned) < total
   239		res := map[string]interface{}{
   240			"entries":  entries,
   241			"total":    total,
   242			"returned": returned,
   243			"offset":   offset,
   244			"limit":    limit,
   245			"order":    order,
   246			"hasMore":  hasMore,
   247		}
   248		if hasMore {
   249			res["nextOffset"] = offset + returned
   250		}
   251		return res, nil
   252	}
   253	
   254	type queryAudit struct {
   255		Query      string
   256		ActorID    string
   257		EntityType string
   258		EntityID   string
   259		Action     string
   260		Role       string
   261		Success    *bool
   262		FromTime   *time.Time
   263		ToTime     *time.Time
   264		Limit      int
   265		Offset     int
   266		Order      string
   267	}
   268	
   269	func normalizeAudit(raw bson.M) map[string]interface{} {
   270		get := func(keys ...string) interface{} {
   271			for _, k := range keys {
   272				if v, ok := raw[k]; ok && v != nil {
   273					return v
   274				}
   275			}
   276			return ""
   277		}
   278		occurred := get("occurredAt", "occurred_at")
   279		var occurredStr string
   280		switch t := occurred.(type) {
   281		case time.Time:
   282			occurredStr = t.UTC().Format(time.RFC3339)
   283		case bson.DateTime:
   284			occurredStr = t.Time().UTC().Format(time.RFC3339)
   285		default:
   286			occurredStr = stringify(occurred)
   287		}
   288		details := map[string]interface{}{}
   289		switch d := raw["details"].(type) {
   290		case bson.M:
   291			for k, v := range d {
   292				details[k] = v
   293			}
   294		case map[string]interface{}:
   295			details = d
   296		}
   297		aid := get("auditId", "audit_id")
   298		actor := get("actorId", "actor_id")
   299		et := get("entityType", "entity_type")
   300		eid := get("entityId", "entity_id")
   301		role, _ := get("role").(string)
   302		return map[string]interface{}{
   303			"auditId":     aid,
   304			"audit_id":    aid,
   305			"actorId":     actor,
   306			"actor_id":    actor,
   307			"role":        role,
   308			"actorRole":   get("actorRole", "role"),
   309			"action":      get("action"),
   310			"entityType":  et,
   311			"entity_type": et,
   312			"entityId":    eid,
   313			"entity_id":   eid,
   314			"success":     raw["success"] == true,
   315			"occurredAt":  occurredStr,
   316			"occurred_at": occurredStr,
   317			"details":     details,
   318		}
   319	}
