   604	func (app *App) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
   605		u := currentUser(r)
   606		if !u.isDispatcher() {
   607			writeErr(w, 403, "forbidden", "forbidden")
   608			return
   609		}
   610		body := readBody(r)
   611		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   612			var req struct {
   613				TargetJourneyID     string   `json:"targetJourneyId"`
   614				ExpectedPlanVersion int      `json:"expectedPlanVersion"`
   615				SourceJourneyIDs    []string `json:"sourceJourneyIds"`
   616			}
   617			if err := decodeBody(body, &req); err != nil {
   618				return 0, nil, herr(400, "invalid_json", "invalid json")
   619			}
   620			if err := app.bumpPlan(r.Context(), req.TargetJourneyID, req.ExpectedPlanVersion); err != nil {
   621				return 0, nil, err
   622			}
   623			// pulse cannot batch
   624			targetSamples := app.journeySampleIDs(r.Context(), req.TargetJourneyID)
   625			types := map[string]*sampleTypeRow{}
   626			checkPulse := func(sids []string) error {
   627				for _, sid := range sids {
   628					s, err := app.loadSample(r.Context(), sid)
   629					if err != nil {
   630						continue
   631					}
   632					st, _ := app.loadSampleType(r.Context(), s.SampleTypeID)
   633					if st != nil {
   634						types[st.ID] = st
   635						if !st.BatchingAllowed {
   636							return herr(409, "pulse_no_batch", "pulse cannot be batched")
   637						}
   638					}
   639				}
   640				return nil
   641			}
   642			if err := checkPulse(targetSamples); err != nil {
   643				return 0, nil, err
   644			}
   645			for _, src := range req.SourceJourneyIDs {
   646				sids := app.journeySampleIDs(r.Context(), src)
   647				if err := checkPulse(sids); err != nil {
   648					return 0, nil, err
   649				}
   650				// incompatibilities
   651				for _, sid := range sids {
   652					s, _ := app.loadSample(r.Context(), sid)
   653					if s == nil {
   654						continue
   655					}
   656					for _, tid := range targetSamples {
   657						t, _ := app.loadSample(r.Context(), tid)
   658						if t == nil {
   659							continue
   660						}
   661						if contains(s.Incompatible, t.SampleTypeID) || contains(t.Incompatible, s.SampleTypeID) {
   662							return 0, nil, herr(409, "incompatible_batch", "incompatible samples")
   663						}
   664					}
   665					_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.TargetJourneyID, sid)
   666					_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET active_journey_id=$2 WHERE id=$1`, sid, req.TargetJourneyID)
   667					_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET journey_id=$2 WHERE sample_id=$1 AND journey_id=$3 AND status NOT IN ('completed')`, sid, req.TargetJourneyID, src)
   668				}
   669				_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, src)
   670			}
   671			payload, err := app.journeyPlanPayload(r.Context(), req.TargetJourneyID, u.ActiveRole, u.UserID)
   672			if err != nil {
   673				return 0, nil, err
   674			}
   675			app.audit(r.Context(), u.UserID, u.ActiveRole, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]interface{}{"sources": req.SourceJourneyIDs})
   676			return 201, payload, nil
   677		})
   678	}
