   238			out["currentHolderId"] = *s.CurrentHolderID
   239		}
   240		if s.ReceivedLabID != nil {
   241			out["receivedLaboratoryId"] = *s.ReceivedLabID
   242		}
   243		if len(s.Exception) > 0 && string(s.Exception) != "null" {
   244			var ex interface{}
   245			if json.Unmarshal(s.Exception, &ex) == nil && ex != nil {
   246				out["exception"] = ex
   247			}
   248		}
   249		var hid *string
   250		_ = app.store.pg.QueryRow(ctx, `SELECT id FROM handoffs WHERE sample_id=$1 AND status='pending' ORDER BY created_at DESC LIMIT 1`, s.ID).Scan(&hid)
   251		if hid != nil {
   252			out["pendingHandoffId"] = *hid
   253			out["pendingHandoff"] = map[string]interface{}{"handoffId": *hid, "status": "pending"}
   254		}
   255		if s.LatestLat != nil && s.LatestLng != nil {
   256			out["latestLocation"] = map[string]interface{}{"latitude": *s.LatestLat, "longitude": *s.LatestLng}
   257		}
