   136	func (s *Store) seedSampleTypes(ctx context.Context) error {
   137		defaults := []struct {
   138			id, name, qual, container string
   139			tmin, tmax                float64
   140			cooled, batch             bool
   141		}{
   142			{"11111111-1111-1111-1111-111111111111", "Amber", "Amber", "standard", 2, 25, false, true},
   143			{"22222222-2222-2222-2222-222222222222", "Indigo", "Indigo", "standard", 2, 25, false, true},
   144			{"33333333-3333-3333-3333-333333333333", "Frost", "Frost", "cooled", 2, 8, true, true},
   145			{"44444444-4444-4444-4444-444444444444", "Pulse", "Pulse", "standard", 2, 25, false, false},
   146		}
   147		// Amber incompatible with Indigo and vice versa
   148		amberID := "11111111-1111-1111-1111-111111111111"
   149		indigoID := "22222222-2222-2222-2222-222222222222"
   150		for _, d := range defaults {
   151			incompat := []string{}
   152			if d.name == "Amber" {
   153				incompat = []string{indigoID}
   154			}
   155			if d.name == "Indigo" {
   156				incompat = []string{amberID}
   157			}
   158			_, err := s.pg.Exec(ctx, `
   159	INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification,
   160	  container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
   161	  requires_cooled_route, batching_allowed)
   162	VALUES ($1,$2,TRUE,$3,$4,$5,$6,$7,$8,$9)
   163	ON CONFLICT (id) DO NOTHING
   164	`, d.id, d.name, d.qual, d.container, d.tmin, d.tmax, incompat, d.cooled, d.batch)
   165			if err != nil {
