   437	func (app *App) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
   438		u := currentUser(r)
   439		body := readBody(r)
   440		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   441			var req struct {
   442				SampleID         string `json:"sampleId"`
   443				FromAssignmentID string `json:"fromAssignmentId"`
   444				ToAssignmentID   string `json:"toAssignmentId"`
   445				ReceiverID       string `json:"receiverId"`
   446				InitiatedAt      string `json:"initiatedAt"`
   447			}
   448			if err := decodeBody(body, &req); err != nil {
   449				return 0, nil, herr(400, "invalid_json", "invalid json")
   450			}
   451			at, err := parseTime(req.InitiatedAt)
   452			if err != nil {
   453				return 0, nil, herr(400, "invalid_time", "invalid initiatedAt")
   454			}
   455			s, err := app.loadSample(r.Context(), req.SampleID)
   456			if err != nil {
   457				return 0, nil, err
   458			}
   459			if s.CurrentHolderID == nil || *s.CurrentHolderID != u.UserID {
   460				if !u.isDispatcher() {
   461					return 0, nil, herr(409, "not_current_holder", "not current holder")
   462				}
   463			}
   464			var pending string
   465			_ = app.store.pg.QueryRow(r.Context(), `SELECT id FROM handoffs WHERE sample_id=$1 AND status='pending' LIMIT 1`, s.ID).Scan(&pending)
   466			if pending != "" {
   467				return 0, nil, herr(409, "pending_handoff_exists", "pending handoff exists")
   468			}
   469			hid := newUUID()
   470			_, err = app.store.pg.Exec(r.Context(), `
   471	INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at)
   472	VALUES ($1,$2,$3,$4,$5,$6,'pending',$7)`, hid, s.ID, req.FromAssignmentID, req.ToAssignmentID, u.UserID, req.ReceiverID, at)
   473			if err != nil {
   474				return 0, nil, err
   475			}
   476			app.audit(r.Context(), u.UserID, u.ActiveRole, "initiate_handoff", "handoff", hid, true, map[string]interface{}{"sampleId": s.ID})
   477			return 201, map[string]interface{}{
   478				"handoffId":       hid,
   479				"senderId":        u.UserID,
   480				"receiverId":      req.ReceiverID,
   481				"currentHolderId": ptrStr(s.CurrentHolderID),
   482				"status":          "pending",
   483			}, nil
   484		})
   485	}
