   546	func (app *App) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
   547		u := currentUser(r)
   548		body := readBody(r)
   549		var req struct {
   550			JourneyID string `json:"journeyId"`
   551		}
   552		if err := decodeBody(body, &req); err != nil || req.JourneyID == "" {
   553			writeErr(w, 400, "invalid_json", "journeyId required")
   554			return
   555		}
   556		payload, err := app.journeyPlanPayload(r.Context(), req.JourneyID, u.ActiveRole, u.UserID)
   557		if err != nil {
   558			app.handleErr(w, err)
   559			return
   560		}
   561		// requester may only see journeys of their samples
   562		if u.ActiveRole == RoleRequester {
   563			sids := app.journeySampleIDs(r.Context(), req.JourneyID)
   564			ok := false
   565			for _, sid := range sids {
   566				s, err := app.loadSample(r.Context(), sid)
   567				if err == nil && s.RequesterID == u.UserID {
   568					ok = true
   569					break
   570				}
   571			}
   572			if !ok {
   573				writeErr(w, 403, "forbidden", "forbidden")
   574				return
   575			}
   576		}
   577		writeData(w, 200, payload)
   578	}
