    63	func (app *App) emit(typ, entityType, entityId string, payload map[string]interface{}) {
    64		if payload == nil {
    65			payload = map[string]interface{}{}
    66		}
    67		var id int64
    68		err := app.store.pg.QueryRow(context.Background(), `
    69	INSERT INTO realtime_events (type, entity_type, entity_id, payload)
    70	VALUES ($1,$2,$3,$4) RETURNING id`, typ, entityType, entityId, asJSON(payload)).Scan(&id)
    71		if err != nil {
    72			log.Printf("emit: %v", err)
    73			return
    74		}
    75		ev := RealtimeEvent{
    76			ID: id, Type: typ, EntityType: entityType, EntityID: entityId,
    77			Payload: payload, CreatedAt: time.Now().UTC(),
    78		}
    79		app.store.mu.RLock()
    80		defer app.store.mu.RUnlock()
    81		for ch := range app.store.eventSubs {
    82			select {
    83			case ch <- ev:
    84			default:
    85			}
    86		}
    87	}
