    89	type RealtimeEvent struct {
    90		ID         int64                  `json:"id"`
    91		Type       string                 `json:"type"`
    92		EntityType string                 `json:"entityType"`
    93		EntityID   string                 `json:"entityId"`
    94		Payload    map[string]interface{} `json:"payload"`
    95		CreatedAt  time.Time              `json:"createdAt"`
    96	}
