    98	func (app *App) subscribe() chan RealtimeEvent {
    99		ch := make(chan RealtimeEvent, 32)
   100		app.store.mu.Lock()
   101		app.store.eventSubs[ch] = struct{}{}
   102		app.store.mu.Unlock()
   103		return ch
   104	}
