    45	func (app *App) roleWork(ctx context.Context, u *SessionUser, role string) (pending, inProg, completed []map[string]interface{}) {
    46		pending, inProg, completed = []map[string]interface{}{}, []map[string]interface{}{}, []map[string]interface{}{}
    47		now := time.Now()
    48		if role == RoleRequester {
    49			rows, err := app.store.pg.Query(ctx, `SELECT id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, u.UserID)
    50			if err != nil {
    51				return
    52			}
    53			defer rows.Close()
    54			for rows.Next() {
    55				var id string
    56				if rows.Scan(&id) != nil {
    57					continue
    58				}
    59				s, err := app.loadSample(ctx, id)
    60				if err != nil {
    61					continue
    62				}
    63				item := app.sampleWorkItem(ctx, s, now)
    64				switch s.Status {
    65				case "received", "cancelled", "expired":
    66					completed = append(completed, item)
    67				case "requested":
    68					pending = append(pending, item)
    69				default:
    70					inProg = append(inProg, item)
