   924	func (app *App) replanJourney(ctx context.Context, u *SessionUser, journeyID string) (string, string, error) {
   925		sids := app.journeySampleIDs(ctx, journeyID)
   926		if len(sids) == 0 {
   927			return "not_required", "", nil
   928		}
   929		// cancel unfinished assignments, keep completed
   930		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
   931		app.releaseJourneyCapacity(ctx, journeyID)
   932		_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced' WHERE id=$1`, journeyID)
   933	
   934		// replan first unfinished sample (and attach others if possible)
   935		var lastStatus, lastID string
   936		for _, sid := range sids {
   937			s, err := app.loadSample(ctx, sid)
   938			if err != nil || s.Status == "received" || s.Status == "cancelled" {
   939				continue
   940			}
   941			st, _ := app.loadSampleType(ctx, s.SampleTypeID)
   942			plan, err := app.evaluateServiceability(ctx, Coord{s.OriginLat, s.OriginLng}, s.OriginType, "", s.SampleTypeID, time.Now(), s.Deadline, s.Earliest, s.Latest)
   943			if err != nil || !plan.Serviceable {
   944				reason := "no_valid_route"
   945				status := "exception"
   946				if plan != nil && plan.Reason == "deadline_unreachable" {
   947					status = "expired"
   948					reason = "deadline_unreachable"
   949				}
   950				_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status=$2, exception=$3 WHERE id=$1`, sid, status, asJSON(map[string]interface{}{"reason": reason}))
   951				if status == "expired" {
   952					lastStatus = "expired"
   953				} else {
   954					lastStatus = "exception"
   955				}
   956				continue
   957			}
   958			req := collectionReqBody{
   959				Origin: Coord{s.OriginLat, s.OriginLng}, OriginType: s.OriginType, SampleTypeID: s.SampleTypeID,
   960				ContainerType: s.ContainerType, TemperatureMinC: s.TempMin, TemperatureMaxC: s.TempMax,
   961			}
   962			jid, _, err := app.materializeJourney(ctx, u, sid, req, plan, st, s.Sealed, time.Now())
   963			if err != nil {
   964				lastStatus = "exception"
   965				continue
   966			}
   967			_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2 WHERE id=$1`, jid, journeyID)
   968			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE id=$1`, sid, jid, plan.TargetLab)
   969			lastStatus = "replaced"
   970			lastID = jid
   971		}
   972		if lastStatus == "" {
   973			lastStatus = "not_required"
   974		}
   975		return lastStatus, lastID, nil
   976	}
