   282		}
   283		if assigned != nil {
   284			u.AssignedLocationID = *assigned
   285		}
   286		rows, err := app.store.pg.Query(ctx, `SELECT role FROM user_roles WHERE user_id=$1 ORDER BY role`, userID)
   287		if err != nil {
   288			return nil, err
   289		}
   290		defer rows.Close()
   291		for rows.Next() {
