   978	func (app *App) offerAssignments(ctx context.Context) {
   979		// expire stale offers
   980		_, _ = app.store.pg.Exec(ctx, `
   981	UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL
   982	WHERE status='offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < now()`)
   983		rows, err := app.store.pg.Query(ctx, `SELECT id FROM assignments WHERE status='pending' AND worker_id IS NULL`)
   984		if err != nil {
   985			return
   986		}
   987		defer rows.Close()
   988		for rows.Next() {
   989			var id string
   990			if rows.Scan(&id) == nil {
   991				app.offerOne(ctx, id)
   992			}
   993		}
   994	}
   995	
   996	func (app *App) offerOne(ctx context.Context, assignmentID string) string {
   997		var kind string
   998		var sampleID, nodeID, labID *string
   999		var expected *string
  1000		err := app.store.pg.QueryRow(ctx, `SELECT kind, sample_id, node_id, laboratory_id, expected_sample_type_id FROM assignments WHERE id=$1`, assignmentID).
  1001			Scan(&kind, &sampleID, &nodeID, &labID, &expected)
  1002		if err != nil {
  1003			return ""
  1004		}
  1005		role := RoleDeliveryPartner
  1006		switch kind {
  1007		case "collection":
  1008			role = RoleCollectionProfessional
  1009		case "node":
  1010			role = RoleNodeHandler
  1011		case "laboratory":
  1012			role = RoleLaboratoryTeam
  1013		}
  1014		q := `
  1015	SELECT u.id FROM users u
  1016	JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
  1017	WHERE u.active=TRUE AND u.available=TRUE
  1018	  AND (u.decline_penalty_until IS NULL OR u.decline_penalty_until < now())
  1019	`
  1020		args := []interface{}{role}
  1021		if (kind == "node" || kind == "laboratory") && (nodeID != nil || labID != nil) {
  1022			loc := ""
  1023			if nodeID != nil {
  1024				loc = *nodeID
  1025			}
  1026			if labID != nil {
  1027				loc = *labID
  1028			}
  1029			q += ` AND u.assigned_location_id=$2`
  1030			args = append(args, loc)
  1031		}
  1032		q += ` ORDER BY COALESCE(u.last_offered_at, to_timestamp(0)) ASC, COALESCE(u.last_assigned_at, to_timestamp(0)) ASC,
  1033	  (SELECT COUNT(*) FROM assignments a WHERE a.worker_id=u.id AND a.status NOT IN ('completed','cancelled')) ASC
  1034	LIMIT 5`
  1035		wrows, err := app.store.pg.Query(ctx, q, args...)
  1036		if err != nil {
  1037			return ""
  1038		}
  1039		defer wrows.Close()
  1040		var candidates []string
  1041		for wrows.Next() {
  1042			var id string
  1043			if wrows.Scan(&id) == nil {
  1044				candidates = append(candidates, id)
  1045			}
  1046		}
  1047		if len(candidates) == 0 {
  1048			if kind == "collection" && expected != nil {
  1049				// no qualified collector — flag after timeout; we flag immediately only if never anyone
  1050				var n int
  1051				_ = app.store.pg.QueryRow(ctx, `SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1 WHERE u.active`, RoleCollectionProfessional).Scan(&n)
  1052				if n == 0 && sampleID != nil {
  1053					_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status='exception', exception=$2 WHERE id=$1 AND status NOT IN ('received','cancelled')`,
  1054						*sampleID, asJSON(map[string]interface{}{"reason": "no_qualified_worker"}))
  1055					_, _ = app.store.pg.Exec(ctx, `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,now())`,
  1056						newUUID(), *sampleID, "no_qualified_worker")
  1057				}
  1058			}
  1059			return ""
  1060		}
  1061		// qualification filter for collection
  1062		chosen := candidates[0]
  1063		if kind == "collection" && expected != nil {
  1064			st, _ := app.loadSampleType(ctx, *expected)
  1065			if st != nil && st.QualifiedCollector {
  1066				found := ""
  1067				for _, cid := range candidates {
  1068					wu, err := app.loadUser(ctx, cid, "")
  1069					if err != nil {
  1070						continue
  1071					}
  1072					if contains(wu.Qualifications, st.RequiredQualification) || hasActiveCert(wu.Certifications, st.RequiredQualification) {
  1073						found = cid
  1074						break
  1075					}
  1076				}
  1077				if found == "" {
  1078					if sampleID != nil {
  1079						// leave pending; background will eventually exception
  1080					}
  1081					return ""
  1082				}
  1083				chosen = found
  1084			}
  1085		}
  1086		exp := time.Now().Add(offerTTL)
  1087		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3 WHERE id=$1`, assignmentID, chosen, exp)
  1088		_, _ = app.store.pg.Exec(ctx, `UPDATE users SET last_offered_at=now() WHERE id=$1`, chosen)
  1089		app.emit("assignment.offered", "assignment", assignmentID, map[string]interface{}{"workerId": chosen})
  1090		return chosen
  1091	}
  1092	
  1093	func (app *App) handleEvents(w http.ResponseWriter, r *http.Request) {
  1094		u := currentUser(r)
  1095		if r.Header.Get("Upgrade") == "websocket" || r.Header.Get("Connection") == "Upgrade" {
  1096			app.handleWS(w, r, u)
  1097			return
  1098		}
  1099		since := int64(0)
  1100		if s := r.URL.Query().Get("since"); s != "" {
  1101			var n int64
  1102			if _, err := parseInt64(s, &n); err == nil {
  1103				since = n
  1104			}
  1105		}
  1106		rows, err := app.store.pg.Query(r.Context(), `
  1107	SELECT id, type, entity_type, entity_id, payload, created_at
  1108	FROM realtime_events WHERE id > $1 ORDER BY id ASC LIMIT 200`, since)
  1109		if err != nil {
  1110			writeErr(w, 500, "internal_error", "internal error")
  1111			return
  1112		}
  1113		defer rows.Close()
  1114		events := []map[string]interface{}{}
  1115		var cursor int64 = since
  1116		for rows.Next() {
  1117			var id int64
  1118			var typ, et, eid string
  1119			var payload []byte
  1120			var created time.Time
  1121			if rows.Scan(&id, &typ, &et, &eid, &payload, &created) != nil {
  1122				continue
  1123			}
  1124			var p map[string]interface{}
  1125			_ = json.Unmarshal(payload, &p)
  1126			if p == nil {
  1127				p = map[string]interface{}{}
  1128			}
  1129			events = append(events, map[string]interface{}{
  1130				"id": id, "type": typ, "entityType": et, "entityId": eid, "payload": p, "createdAt": rfc3339(created),
  1131			})
  1132			cursor = id
  1133		}
  1134		writeData(w, 200, map[string]interface{}{"events": events, "cursor": cursor})
  1135	}
  1136	
  1137	func parseInt64(s string, out *int64) (int, error) {
  1138		var n int64
  1139		for _, c := range s {
  1140			if c < '0' || c > '9' {
  1141				return 0, herr(400, "invalid_json", "invalid since")
  1142			}
  1143			n = n*10 + int64(c-'0')
  1144		}
  1145		*out = n
  1146		return 0, nil
  1147	}

