   194	func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
   195		const R = 6371.0
   196		p1 := lat1 * math.Pi / 180
   197		p2 := lat2 * math.Pi / 180
   198		dphi := (lat2 - lat1) * math.Pi / 180
   199		dl := (lng2 - lng1) * math.Pi / 180
   200		a := math.Sin(dphi/2)*math.Sin(dphi/2) + math.Cos(p1)*math.Cos(p2)*math.Sin(dl/2)*math.Sin(dl/2)
   201		c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
   202		return R * c
   203	}
