   204	func newUUID() string {
   205		b := make([]byte, 16)
   206		_, _ = rand.Read(b)
   207		b[6] = (b[6] & 0x0f) | 0x40
   208		b[8] = (b[8] & 0x3f) | 0x80
   209		return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
   210	}
   211	
   212	func newToken() string {
   213		b := make([]byte, 32)
   214		_, _ = rand.Read(b)
   215		return hex.EncodeToString(b)
   216	}
   217	
   218	func hashPassword(p string) (string, error) {
   219		b, err := bcrypt.GenerateFromPassword([]byte(p), bcrypt.DefaultCost)
   220		return string(b), err
   221	}
   222	
   223	func checkPassword(hash, p string) bool {
   224		return bcrypt.CompareHashAndPassword([]byte(hash), []byte(p)) == nil
   225	}
