   841	func (app *App) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
   842		u := currentUser(r)
   843		if !u.isDispatcher() {
   844			writeErr(w, 403, "forbidden", "forbidden")
   845			return
   846		}
   847		body := readBody(r)
   848		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   849			var req struct {
   850				ResourceType string `json:"resourceType"`
   851				ResourceID   string `json:"resourceId"`
   852				Reason       string `json:"reason"`
   853				OccurredAt   string `json:"occurredAt"`
   854			}
   855			if err := decodeBody(body, &req); err != nil {
   856				return 0, nil, herr(400, "invalid_json", "invalid json")
   857			}
   858			valid := map[string]bool{"location": true, "node": true, "laboratory": true, "connection": true, "route": true, "worker": true, "capacity": true}
   859			if !valid[req.ResourceType] {
   860				return 0, nil, herr(400, "invalid_resource_type", "invalid resource type")
   861			}
   862			at, err := parseTime(req.OccurredAt)
   863			if err != nil {
   864				return 0, nil, herr(400, "invalid_time", "invalid occurredAt")
   865			}
   866			// mark resource unavailable
   867			switch req.ResourceType {
   868			case "location", "node", "laboratory":
   869				_, _ = app.store.pg.Exec(r.Context(), `UPDATE locations SET active=FALSE WHERE id=$1`, req.ResourceID)
   870			case "connection", "route":
   871				_, _ = app.store.pg.Exec(r.Context(), `UPDATE connections SET active=FALSE WHERE id=$1`, req.ResourceID)
   872			case "worker":
   873				_, _ = app.store.pg.Exec(r.Context(), `UPDATE users SET available=FALSE WHERE id=$1`, req.ResourceID)
   874			}
   875			app.bumpNetwork(r.Context())
   876			affected := []string{}
   877			replacements := []string{}
   878			replanStatus := "not_required"
   879			// find journeys touching this resource
   880			var q string
   881			switch req.ResourceType {
   882			case "location", "node", "laboratory":
   883				q = `SELECT DISTINCT journey_id FROM assignments WHERE (from_location_id=$1 OR to_location_id=$1 OR node_id=$1 OR laboratory_id=$1) AND status NOT IN ('completed','cancelled')`
   884			case "connection", "route":
   885				q = `SELECT DISTINCT a.journey_id FROM assignments a JOIN connections c ON c.from_location_id=a.from_location_id AND c.to_location_id=a.to_location_id WHERE c.id=$1 AND a.status NOT IN ('completed','cancelled')`
   886			case "worker":
   887				q = `SELECT DISTINCT journey_id FROM assignments WHERE worker_id=$1 AND status NOT IN ('completed','cancelled')`
   888			default:
   889				q = `SELECT DISTINCT journey_id FROM capacity_reservations WHERE resource_id=$1 AND active=TRUE`
   890			}
   891			rows, err := app.store.pg.Query(r.Context(), q, req.ResourceID)
   892			if err == nil {
   893				defer rows.Close()
   894				for rows.Next() {
   895					var jid string
   896					if rows.Scan(&jid) != nil {
   897						continue
   898					}
   899					st, repl, _ := app.replanJourney(r.Context(), u, jid)
   900					sids := app.journeySampleIDs(r.Context(), jid)
   901					affected = append(affected, sids...)
   902					if repl != "" {
   903						replacements = append(replacements, repl)
   904					}
   905					if st != "not_required" {
   906						replanStatus = st
   907					}
   908				}
   909			}
   910			did := newUUID()
   911			_, _ = app.store.pg.Exec(r.Context(), `
   912	INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, replan_status)
   913	VALUES ($1,$2,$3,$4,$5,$6)`, did, req.ResourceType, req.ResourceID, req.Reason, at, replanStatus)
   914			app.audit(r.Context(), u.UserID, u.ActiveRole, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason})
   915			return 201, map[string]interface{}{
   916				"disruptionId":       did,
   917				"affectedSampleIds":  affected,
   918				"replacementPlanIds": replacements,
   919				"replanStatus":       replanStatus,
   920			}, nil
   921		})
   922	}
