   336	func (app *App) withIdem(w http.ResponseWriter, r *http.Request, body []byte, required bool, fn func() (int, interface{}, error)) {
   337		u := currentUser(r)
   338		key := idemKeyFrom(body)
   339		if required && key == "" {
   340			writeErr(w, 400, "idempotency_required", "idempotency key required")
   341			return
   342		}
   343		if key != "" {
   344			var existingUser string
   345			var existingStatus int
   346			var existing []byte
   347			err := app.store.pg.QueryRow(r.Context(), `SELECT user_id::text, status_code, response FROM idempotency WHERE key=$1`, key).
   348				Scan(&existingUser, &existingStatus, &existing)
   349			if err == nil {
   350				if existingUser != u.UserID {
   351					writeErr(w, 409, "idempotency_conflict", "idempotency conflict")
   352					return
   353				}
   354				w.Header().Set("Content-Type", "application/json")
   355				w.WriteHeader(existingStatus)
   356				_, _ = w.Write(existing)
   357				return
   358			}
   359		}
   360		status, payload, e := fn()
   361		if e != nil {
   362			app.handleErr(w, e)
   363			return
   364		}
   365		bodyOut, _ := json.Marshal(map[string]interface{}{"data": payload})
   366		if key != "" {
   367			_, _ = app.store.pg.Exec(r.Context(), `
   368	INSERT INTO idempotency (key, user_id, request_hash, status_code, response)
   369	VALUES ($1,$2,'', $3, $4) ON CONFLICT (key) DO NOTHING`, key, u.UserID, status, bodyOut)
   370		}
   371		w.Header().Set("Content-Type", "application/json")
   372		w.WriteHeader(status)
   373		_, _ = w.Write(bodyOut)
   374	}
