   570	func (app *App) handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request) {
   571		u := currentUser(r)
   572		if u.ActiveRole != RoleLaboratoryTeam && !u.isDispatcher() {
   573			writeErr(w, 403, "forbidden", "forbidden")
   574			return
   575		}
   576		body := readBody(r)
   577		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   578			var req struct {
   579				SampleID     string `json:"sampleId"`
   580				LaboratoryID string `json:"laboratoryId"`
   581				ReceivedAt   string `json:"receivedAt"`
   582			}
   583			if err := decodeBody(body, &req); err != nil {
   584				return 0, nil, herr(400, "invalid_json", "invalid json")
   585			}
   586			at, err := parseTime(req.ReceivedAt)
   587			if err != nil {
   588				return 0, nil, herr(400, "invalid_time", "invalid receivedAt")
   589			}
   590			s, err := app.loadSample(r.Context(), req.SampleID)
   591			if err != nil {
   592				return 0, nil, err
   593			}
   594			if u.ActiveRole == RoleLaboratoryTeam && u.AssignedLocationID != "" && u.AssignedLocationID != req.LaboratoryID {
   595				return 0, nil, herr(403, "wrong_laboratory_operator", "wrong laboratory")
   596			}
   597			if s.TargetLabID != nil && *s.TargetLabID != req.LaboratoryID {
   598				return 0, nil, herr(409, "wrong_laboratory", "wrong laboratory")
   599			}
   600			_, err = app.store.pg.Exec(r.Context(), `
   601	UPDATE samples SET status='received', received_laboratory_id=$2, current_holder_id=$3 WHERE id=$1`,
   602				s.ID, req.LaboratoryID, u.UserID)
   603			if err != nil {
   604				return 0, nil, err
   605			}
   606			_, _ = app.store.pg.Exec(r.Context(), `
   607	UPDATE assignments SET status='completed', completed_at=$2, worker_id=$3
   608	WHERE sample_id=$1 AND kind='laboratory' AND status NOT IN ('completed','cancelled')`, s.ID, at, u.UserID)
   609			if s.ActiveJourneyID != nil {
   610				_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='completed' WHERE id=$1`, *s.ActiveJourneyID)
   611				app.releaseJourneyCapacity(r.Context(), *s.ActiveJourneyID)
   612			}
   613			app.audit(r.Context(), u.UserID, u.ActiveRole, "confirm_laboratory_receipt", "sample", s.ID, true, map[string]interface{}{"laboratoryId": req.LaboratoryID})
   614			app.emit("sample.received", "sample", s.ID, map[string]interface{}{"laboratoryId": req.LaboratoryID})
   615			return 201, map[string]interface{}{
   616				"sampleId":     s.ID,
   617				"laboratoryId": req.LaboratoryID,
   618				"status":       "received",
   619				"receivedAt":   rfc3339(at),
   620			}, nil
   621		})
   622	}
