   671	func (app *App) handleRecordCheckpoint(w http.ResponseWriter, r *http.Request) {
   672		u := currentUser(r)
   673		body := readBody(r)
   674		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   675			var req struct {
   676				SampleID             string  `json:"sampleId"`
   677				AssignmentID         string  `json:"assignmentId"`
   678				LocationID           string  `json:"locationId"`
   679				ContainerType        string  `json:"containerType"`
   680				ObservedTemperatureC float64 `json:"observedTemperatureC"`
   681				RecordedAt           string  `json:"recordedAt"`
   682			}
   683			if err := decodeBody(body, &req); err != nil {
   684				return 0, nil, herr(400, "invalid_json", "invalid json")
   685			}
   686			at, err := parseTime(req.RecordedAt)
   687			if err != nil {
   688				return 0, nil, herr(400, "invalid_time", "invalid recordedAt")
   689			}
   690			s, err := app.loadSample(r.Context(), req.SampleID)
   691			if err != nil {
   692				return 0, nil, err
   693			}
   694			if s.Status == "received" || s.Status == "cancelled" {
   695				return 0, nil, herr(409, "terminal_sample", "sample is terminal")
   696			}
   697			if s.CurrentHolderID == nil || *s.CurrentHolderID != u.UserID {
   698				if !u.isDispatcher() {
   699					return 0, nil, herr(403, "forbidden", "not current holder")
   700				}
   701			}
   702			compliant := req.ObservedTemperatureC >= s.TempMin && req.ObservedTemperatureC <= s.TempMax
   703			if req.ContainerType != "" && s.ContainerType != "" && req.ContainerType != s.ContainerType {
   704				compliant = false
   705			}
   706			cid := newUUID()
   707			_, _ = app.store.pg.Exec(r.Context(), `
   708	INSERT INTO checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, recorded_at, compliant)
   709	VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, cid, s.ID, req.AssignmentID, nilIfEmpty(req.LocationID), req.ContainerType, req.ObservedTemperatureC, at, compliant)
   710			status := s.Status
   711			if !compliant {
   712				status = "exception"
   713				_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET status='exception', exception=$2 WHERE id=$1`, s.ID,
   714					asJSON(map[string]interface{}{"reason": "handling_violation", "checkpointId": cid}))
   715				_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO exceptions (id, sample_id, reason, observed_at) VALUES ($1,$2,$3,$4)`,
   716					newUUID(), s.ID, "handling_violation", at)
   717			}
   718			app.audit(r.Context(), u.UserID, u.ActiveRole, "record_handling_checkpoint", "sample", s.ID, true, map[string]interface{}{"compliant": compliant})
   719			return 201, map[string]interface{}{
   720				"checkpointId": cid,
   721				"sampleId":     s.ID,
   722				"compliant":    compliant,
   723				"sampleStatus": status,
   724			}, nil
   725		})
   726	}

