   688		app.withIdem(w, r, body, true, func() (int, interface{}, error) {
   689			var req struct {
   690				TargetJourneyID     string   `json:"targetJourneyId"`
   691				ExpectedPlanVersion int      `json:"expectedPlanVersion"`
   692				SourceJourneyIDs    []string `json:"sourceJourneyIds"`
   693			}
   694			if err := decodeBody(body, &req); err != nil {
   695				return 0, nil, herr(400, "invalid_json", "invalid json")
   696			}
   697			if err := app.bumpPlan(r.Context(), req.TargetJourneyID, req.ExpectedPlanVersion); err != nil {
   698				return 0, nil, err
   699			}
   700			// pulse cannot batch
   701			targetSamples := app.journeySampleIDs(r.Context(), req.TargetJourneyID)
   702			types := map[string]*sampleTypeRow{}
   703			checkPulse := func(sids []string) error {
   704				for _, sid := range sids {
   705					s, err := app.loadSample(r.Context(), sid)
   706					if err != nil {
   707						continue
   708					}
   709					st, _ := app.loadSampleType(r.Context(), s.SampleTypeID)
   710					if st != nil {
   711						types[st.ID] = st
   712						if !st.BatchingAllowed {
   713							return herr(409, "pulse_no_batch", "pulse cannot be batched")
   714						}
   715					}
   716				}
   717				return nil
   718			}
   719			if err := checkPulse(targetSamples); err != nil {
   720				return 0, nil, err
   721			}
   722			for _, src := range req.SourceJourneyIDs {
   723				sids := app.journeySampleIDs(r.Context(), src)
   724				if err := checkPulse(sids); err != nil {
   725					return 0, nil, err
   726				}
   727				// incompatibilities
   728				for _, sid := range sids {
   729					s, _ := app.loadSample(r.Context(), sid)
   730					if s == nil {
   731						continue
   732					}
   733					for _, tid := range targetSamples {
   734						t, _ := app.loadSample(r.Context(), tid)
   735						if t == nil {
   736							continue
   737						}
   738						if contains(s.Incompatible, t.SampleTypeID) || contains(t.Incompatible, s.SampleTypeID) {
   739							return 0, nil, herr(409, "incompatible_batch", "incompatible samples")
   740						}
   741					}
   742					_, _ = app.store.pg.Exec(r.Context(), `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.TargetJourneyID, sid)
   743					_, _ = app.store.pg.Exec(r.Context(), `UPDATE samples SET active_journey_id=$2 WHERE id=$1`, sid, req.TargetJourneyID)
   744					_, _ = app.store.pg.Exec(r.Context(), `UPDATE assignments SET journey_id=$2 WHERE sample_id=$1 AND journey_id=$3 AND status NOT IN ('completed')`, sid, req.TargetJourneyID, src)
   745				}
   746				_, _ = app.store.pg.Exec(r.Context(), `UPDATE journeys SET status='cancelled' WHERE id=$1`, src)
   747			}
   748			payload, err := app.journeyPlanPayload(r.Context(), req.TargetJourneyID, u.ActiveRole, u.UserID)
   749			if err != nil {
   750				return 0, nil, err
   751			}
   752			app.audit(r.Context(), u.UserID, u.ActiveRole, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]interface{}{"sources": req.SourceJourneyIDs})
   753			return 201, payload, nil
   754		})
