   149	func uuidStr(u pgtype.UUID) string {
   150		if !u.Valid {
   151			return ""
   152		}
   153		b, _ := u.Value()
   154		if s, ok := b.(string); ok {
   155			return s
   156		}
   157		if bts, ok := b.([16]byte); ok {
   158			return formatUUID(bts)
   159		}
   160		return ""
   161	}
   162	
   163	func formatUUID(b [16]byte) string {
   164		const hex = "0123456789abcdef"
   165		buf := make([]byte, 36)
   166		j := 0
   167		for i, v := range b {
   168			if i == 4 || i == 6 || i == 8 || i == 10 {
   169				buf[j] = '-'
   170				j++
   171			}
   172			buf[j] = hex[v>>4]
   173			buf[j+1] = hex[v&0x0f]
   174			j += 2
   175		}
   176		return string(buf)
   177	}
