   176	func (app *App) materializeJourney(ctx context.Context, u *SessionUser, sampleID string, req collectionReqBody, plan *planResult, st *sampleTypeRow, alreadySealed bool, earliest time.Time) (string, []string, error) {
   177		jid := newUUID()
   178		mode := "direct"
   179		if len(plan.Path) > 2 {
   180			mode = "multi_stop"
   181		}
   182		_, err := app.store.pg.Exec(ctx, `
   183	INSERT INTO journeys (id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, valid)
   184	VALUES ($1,1,$2,'planned',$3,$4,1,0,TRUE)`, jid, mode, plan.EstimatedArrival, plan.TotalCost)
   185		if err != nil {
   186			return "", nil, err
   187		}
   188		_, _ = app.store.pg.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, jid, sampleID)
   189	
   190		seq := 1
   191		est := earliest
   192		// pickup stop at origin / collection point
   193		pickupLoc := plan.CollectionPoint
   194		if req.OriginType == "node" && req.OriginNodeID != "" {
   195			pickupLoc = req.OriginNodeID
   196		}
   197		stopPickup := newUUID()
   198		_, _ = app.store.pg.Exec(ctx, `
   199	INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
   200	VALUES ($1,$2,$3,'pickup',$4,$5,0,$6,$7)`, stopPickup, jid, pickupLoc, seq, est, req.Origin.Latitude, req.Origin.Longitude)
   201		seq++
   202	
   203		// remaining path stops
   204		for i, locID := range plan.Path {
   205			stopType := "handoff"
   206			if i == len(plan.Path)-1 {
   207				stopType = "delivery"
   208			} else if i == 0 && req.OriginType == "node" {
   209				continue
   210			} else if i == 0 {
   211				stopType = "handoff"
   212			}
   213			l := locByIDMust(ctx, app, locID)
   214			est = est.Add(time.Duration(15) * time.Minute)
   215			dwell := 0
   216			if l != nil {
   217				dwell = l.HandlingMinutes
   218			}
   219			sid := newUUID()
   220			var lat, lng interface{}
   221			if l != nil {
   222				lat, lng = l.Lat, l.Lng
   223			}
   224			_, _ = app.store.pg.Exec(ctx, `
   225	INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
   226	VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`, sid, jid, locID, stopType, seq, est, dwell, lat, lng)
   227			seq++
   228		}
   229	
   230		aids := []string{}
   231		asSeq := 1
   232		if !alreadySealed {
   233			aid := newUUID()
   234			_, err = app.store.pg.Exec(ctx, `
   235	INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, expected_sample_type_id)
   236	VALUES ($1,$2,$3,'collection',$4,'pending',$5,$6,$7)`,
   237				aid, jid, sampleID, asSeq, nilIfEmpty(pickupLoc), nilIfEmpty(pickupLoc), st.ID)
   238			if err != nil {
   239				return "", nil, err
   240			}
   241			aids = append(aids, aid)
   242			asSeq++
   243		}
   244	
   245		// transport legs along path
   246		path := plan.Path
   247		if len(path) == 0 {
   248			path = []string{pickupLoc}
   249			if plan.TargetLab != "" && plan.TargetLab != pickupLoc {
   250				path = append(path, plan.TargetLab)
   251			}
   252		}
   253		if alreadySealed && req.OriginType == "node" && req.OriginNodeID != "" && (len(path) == 0 || path[0] != req.OriginNodeID) {
   254			path = append([]string{req.OriginNodeID}, path...)
   255		}
   256		for i := 0; i+1 < len(path); i++ {
   257			aid := newUUID()
   258			_, err = app.store.pg.Exec(ctx, `
   259	INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, expected_sample_type_id)
   260	VALUES ($1,$2,$3,'transport',$4,'pending',$5,$6,$7)`,
   261				aid, jid, sampleID, asSeq, path[i], path[i+1], st.ID)
   262			if err != nil {
   263				return "", nil, err
   264			}
   265			aids = append(aids, aid)
   266			asSeq++
   267			// reserve connection capacity
   268			_ = app.reserveCapacity(ctx, path[i], path[i+1], jid, sampleID, st.RequiresCooled)
   269		}
   270	
   271		// node assignment at collection / intermediate
   272		if pickupLoc != "" {
   273			aid := newUUID()
   274			_, _ = app.store.pg.Exec(ctx, `
   275	INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, node_id, expected_sample_type_id)
   276	VALUES ($1,$2,$3,'node',$4,'pending',$5,$6)`, aid, jid, sampleID, asSeq, pickupLoc, st.ID)
   277			aids = append(aids, aid)
   278			asSeq++
   279			_ = app.reserveLocationCapacity(ctx, pickupLoc, jid, sampleID, st.RequiresCooled)
   280		}
   281		if plan.TargetLab != "" {
   282			aid := newUUID()
   283			_, _ = app.store.pg.Exec(ctx, `
   284	INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, laboratory_id, expected_sample_type_id)
   285	VALUES ($1,$2,$3,'laboratory',$4,'pending',$5,$6)`, aid, jid, sampleID, asSeq, plan.TargetLab, st.ID)
   286			aids = append(aids, aid)
   287			_ = app.reserveLocationCapacity(ctx, plan.TargetLab, jid, sampleID, st.RequiresCooled)
   288		}
   289	
   290		app.offerAssignments(ctx)
   291		return jid, aids, nil
   292	}
