   259			}
   260			hmin := 0
   261			for _, id := range path {
   262				if l := locByID(locs, id); l != nil {
   263					hmin += l.HandlingMinutes
   264				}
   265			}
   266			c := cand{lab: lab, path: path, mins: mins, cost: cost, hmin: hmin}
   267			if best == nil || c.mins < best.mins || (c.mins == best.mins && c.cost < best.cost) {
   268				cp := c
   269				best = &cp
   270			}
   271		}
   272		if best == nil {
   273			res.Reason = "no_route"
   274			return res
   275		}
   276	
   277		// capacity along path
   278		for i := 0; i+1 < len(best.path); i++ {
   279			c := findConn(conns, best.path[i], best.path[i+1])
   280			if c == nil {
   281				res.Reason = "no_route"
   282				return res
   283			}
   284			if st.RequiresCooled {
   285				if c.CooledCap-c.CooledReserved < 1 && c.CooledCap > 0 {
   286					res.Reason = "insufficient_capacity"
   287					return res
   288				}
   289			} else if c.CapacityUnits > 0 && c.CapacityUnits-c.ReservedUnits < 1 {
   290				res.Reason = "insufficient_capacity"
   291				return res
   292			}
   293		}
   294		for _, id := range best.path {
   295			l := locByID(locs, id)
   296			if l == nil {
   297				continue
   298			}
   299			if st.RequiresCooled {
   300				if l.CooledCap > 0 && l.CooledCap-l.CooledReserved < 1 {
   301					res.Reason = "insufficient_capacity"
   302					return res
   303				}
   304			} else if l.CapacityUnits > 0 && l.CapacityUnits-l.ReservedUnits < 1 {
   305				res.Reason = "insufficient_capacity"
   306				return res
   307			}
   308		}
   309	
   310		startAt := requestedAt
   311		if !earliest.IsZero() && earliest.After(startAt) {
   312			startAt = earliest
   313		}
   314		arrival := startAt.Add(time.Duration(res.CollectionTravelMin+best.mins+best.hmin) * time.Minute)
   315		if !deadline.IsZero() && arrival.After(deadline) {
   316			res.Reason = "deadline_unreachable"
   317			res.TargetLab = best.lab.ID
   318			res.EstimatedArrival = arrival
   319			res.Path = best.path
   320			return res
   321		}
   322	
   323		res.Serviceable = true
   324		res.Reason = "serviceable"
   325		res.TargetLab = best.lab.ID
   326		res.EstimatedArrival = arrival
   327		res.Path = best.path
   328		res.TravelMinutes = best.mins
   329		res.HandlingMinutes = best.hmin
   330		res.TotalCost = best.cost
   331		return res
   332	}
