   278	func (app *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
   279		u := currentUser(r)
   280		body := readBody(r)
   281		var req struct {
   282			ResourceID          string `json:"resourceId"`
   283			CapacityUnits       int    `json:"capacityUnits"`
   284			CooledCapacityUnits int    `json:"cooledCapacityUnits"`
   285		}
   286		if err := decodeBody(body, &req); err != nil {
   287			writeErr(w, 400, "invalid_json", "invalid json")
   288			return
   289		}
   290		if req.ResourceID == "" || req.CapacityUnits < 0 || req.CooledCapacityUnits < 0 {
   291			writeErr(w, 400, "invalid_capacity", "invalid capacity")
   292			return
   293		}
   294		// node handlers / lab team may configure their assigned location only
   295		if !u.isDispatcher() && u.ActiveRole != RoleAdministrator {
   296			if u.AssignedLocationID == "" || u.AssignedLocationID != req.ResourceID {
   297				writeErr(w, 403, "forbidden", "forbidden")
   298				return
   299			}
   300			if u.ActiveRole != RoleNodeHandler && u.ActiveRole != RoleLaboratoryTeam {
   301				writeErr(w, 403, "forbidden", "forbidden")
   302				return
   303			}
   304		} else if u.ActiveRole != RoleAdministrator && !u.isDispatcher() {
   305			writeErr(w, 403, "forbidden", "forbidden")
   306			return
   307		}
   308		// try location then connection
   309		tag, err := app.store.pg.Exec(r.Context(), `
   310	UPDATE locations SET capacity_units=$2, cooled_capacity_units=$3 WHERE id=$1`,
   311			req.ResourceID, req.CapacityUnits, req.CooledCapacityUnits)
   312		if err != nil {
   313			writeErr(w, 500, "internal_error", "internal error")
   314			return
   315		}
   316		if tag.RowsAffected() == 0 {
   317			tag, err = app.store.pg.Exec(r.Context(), `
   318	UPDATE connections SET capacity_units=$2, cooled_capacity_units=$3 WHERE id=$1`,
   319				req.ResourceID, req.CapacityUnits, req.CooledCapacityUnits)
   320			if err != nil || tag.RowsAffected() == 0 {
   321				writeErr(w, 404, "not_found", "resource not found")
   322				return
   323			}
   324		}
   325		app.audit(r.Context(), u.UserID, u.ActiveRole, "configure_capacity", "capacity", req.ResourceID, true, map[string]interface{}{
   326			"capacityUnits": req.CapacityUnits, "cooledCapacityUnits": req.CooledCapacityUnits,
   327		})
   328		app.bumpNetwork(r.Context())
   329		writeData(w, 200, map[string]interface{}{
   330			"resourceId":            req.ResourceID,
   331			"capacityUnits":         req.CapacityUnits,
   332			"cooledCapacityUnits":   req.CooledCapacityUnits,
   333		})
   334	}
