   177	func planServiceability(locs []locRow, conns []connRow, st *sampleTypeRow, origin Coord, originType, originNodeID string, requestedAt, deadline, earliest, latest time.Time) *planResult {
   178		res := &planResult{Serviceable: false, Reason: "outside_service_coverage", NeedsCooled: st.RequiresCooled}
   179	
   180		var start *locRow
   181		if originType == "node" && originNodeID != "" {
   182			start = locByID(locs, originNodeID)
   183			if start == nil || !start.Active {
   184				res.Reason = "outside_service_coverage"
   185				return res
   186			}
   187		} else {
   188			bestDist := math.MaxFloat64
   189			for i := range locs {
   190				l := &locs[i]
   191				if !l.Active || !l.FnCollection {
   192					continue
   193				}
   194				d := haversineKm(origin.Latitude, origin.Longitude, l.Lat, l.Lng)
   195				cov := l.CoverageKm
   196				if cov <= 0 {
   197					cov = 5
   198				}
   199				if d <= cov && d < bestDist {
   200					bestDist = d
   201					start = l
   202				}
   203			}
   204			if start == nil {
   205				res.Reason = "outside_service_coverage"
   206				return res
   207			}
   208			// home/clinic travel minutes from origin to collection point at 25 km/h
   209			res.CollectionTravelMin = int(math.Ceil(bestDist / 25.0 * 60.0))
   210			if res.CollectionTravelMin < 1 {
   211				res.CollectionTravelMin = 1
   212			}
   213		}
   214		res.CollectionPoint = start.ID
   215	
   216		labs := []locRow{}
   217		for _, l := range locs {
   218			if !l.Active || !l.FnLaboratory {
   219				continue
   220			}
   221			if !contains(l.AcceptedTypes, st.ID) && len(l.AcceptedTypes) > 0 {
   222				continue
   223			}
   224			// if no acceptances configured, treat as accepting all
   225			if len(l.AcceptedTypes) == 0 {
   226				// still a laboratory; allow unless we have other labs that do accept
   227				labs = append(labs, l)
   228				continue
   229			}
   230			labs = append(labs, l)
   231		}
   232		// prefer labs that explicitly accept
   233		explicit := []locRow{}
   234		for _, l := range labs {
   235			if contains(l.AcceptedTypes, st.ID) {
   236				explicit = append(explicit, l)
   237			}
   238		}
   239		if len(explicit) > 0 {
   240			labs = explicit
   241		}
   242		if len(labs) == 0 {
   243			res.Reason = "no_accepting_laboratory"
   244			return res
   245		}
   246	
   247		type cand struct {
   248			lab   locRow
   249			path  []string
   250			mins  int
   251			cost  float64
   252			hmin  int
   253		}
   254		var best *cand
   255		for _, lab := range labs {
   256			path, mins, cost, ok := shortestPath(locs, conns, start.ID, lab.ID, st.RequiresCooled)
   257			if !ok {
   258				continue
   259			}
   260			hmin := 0
   261			for _, id := range path {
   262				if l := locByID(locs, id); l != nil {
   263					hmin += l.HandlingMinutes
   264				}
   265			}
   266			c := cand{lab: lab, path: path, mins: mins, cost: cost, hmin: hmin}
   267			if best == nil || c.mins < best.mins || (c.mins == best.mins && c.cost < best.cost) {
   268				cp := c
   269				best = &cp
   270			}
   271		}
   272		if best == nil {
   273			res.Reason = "no_route"
   274			return res
   275		}
   276	
   277		// capacity along path
   278		for i := 0; i+1 < len(best.path); i++ {
   279			c := findConn(conns, best.path[i], best.path[i+1])
   280			if c == nil {
   281				res.Reason = "no_route"
   282				return res
   283			}
   284			if st.RequiresCooled {
   285				if c.CooledCap-c.CooledReserved < 1 && c.CooledCap > 0 {
   286					res.Reason = "insufficient_capacity"
   287					return res
   288				}
   289			} else if c.CapacityUnits > 0 && c.CapacityUnits-c.ReservedUnits < 1 {
   290				res.Reason = "insufficient_capacity"
   291				return res
   292			}
   293		}
   294		for _, id := range best.path {
   295			l := locByID(locs, id)
   296			if l == nil {
   297				continue
   298			}
   299			if st.RequiresCooled {
   300				if l.CooledCap > 0 && l.CooledCap-l.CooledReserved < 1 {
   301					res.Reason = "insufficient_capacity"
   302					return res
   303				}
   304			} else if l.CapacityUnits > 0 && l.CapacityUnits-l.ReservedUnits < 1 {
   305				res.Reason = "insufficient_capacity"
   306				return res
   307			}
   308		}
   309	
   310		startAt := requestedAt
   311		if !earliest.IsZero() && earliest.After(startAt) {
   312			startAt = earliest
   313		}
   314		arrival := startAt.Add(time.Duration(res.CollectionTravelMin+best.mins+best.hmin) * time.Minute)
   315		if !deadline.IsZero() && arrival.After(deadline) {
   316			res.Reason = "deadline_unreachable"
   317			res.TargetLab = best.lab.ID
   318			res.EstimatedArrival = arrival
   319			res.Path = best.path
   320			return res
   321		}
   322	
   323		res.Serviceable = true
   324		res.Reason = "serviceable"
   325		res.TargetLab = best.lab.ID
   326		res.EstimatedArrival = arrival
   327		res.Path = best.path
   328		res.TravelMinutes = best.mins
   329		res.HandlingMinutes = best.hmin
   330		res.TotalCost = best.cost
   331		return res
   332	}
