   499	func (app *App) operationsState(ctx context.Context, u *SessionUser, sampleTypeFilter string) (map[string]interface{}, error) {
   500		now := time.Now()
   501		samples := []map[string]interface{}{}
   502		q := `SELECT id FROM samples ORDER BY created_at DESC LIMIT 500`
   503		rows, err := app.store.pg.Query(ctx, q)
   504		if err == nil {
   505			defer rows.Close()
   506			for rows.Next() {
   507				var id string
   508				if rows.Scan(&id) != nil {
   509					continue
   510				}
   511				s, err := app.loadSample(ctx, id)
   512				if err != nil {
   513					continue
   514				}
   515				if sampleTypeFilter != "" && s.SampleTypeID != sampleTypeFilter {
   516					continue
   517				}
   518				item := map[string]interface{}{
   519					"sampleId":         s.ID,
   520					"status":           s.Status,
   521					"serviceability":   s.Serviceability,
   522					"currentHolderId":  ptrStr(s.CurrentHolderID),
   523					"locationStale":    isStale(s.LocationRecordedAt, now),
   524					"deliveryDeadline": rfc3339(s.Deadline),
   525				}
   526				if s.LatestLat != nil && s.LatestLng != nil {
   527					item["latestLocation"] = map[string]interface{}{"latitude": *s.LatestLat, "longitude": *s.LatestLng}
   528				}
   529				if s.LocationRecordedAt != nil {
   530					item["locationRecordedAt"] = rfc3339(*s.LocationRecordedAt)
   531				}
   532				if s.ActiveJourneyID != nil {
   533					item["activeJourneyId"] = *s.ActiveJourneyID
   534				}
   535				if s.TargetLabID != nil {
   536					item["targetLaboratoryId"] = *s.TargetLabID
   537				}
   538				if len(s.Exception) > 0 && string(s.Exception) != "null" {
   539					var ex interface{}
   540					_ = jsonUnmarshal(s.Exception, &ex)
   541					item["exception"] = ex
   542				}
   543				samples = append(samples, item)
   544			}
   545		}
   546	
   547		workers := []map[string]interface{}{}
   548		wrows, err := app.store.pg.Query(ctx, `
   549	SELECT u.id, u.username, u.full_name, u.available, u.capacity_units, u.latest_lat, u.latest_lng, u.location_recorded_at,
   550	  COALESCE((SELECT COUNT(*) FROM assignments a WHERE (a.worker_id=u.id OR a.offered_to=u.id) AND a.status NOT IN ('completed','cancelled')),0)
   551	FROM users u
   552	JOIN user_roles ur ON ur.user_id=u.id
   553	WHERE ur.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team')
   554	GROUP BY u.id`)
   555		if err == nil {
   556			defer wrows.Close()
   557			for wrows.Next() {
   558				var id, uname, fname string
   559				var avail bool
   560				var cap, load int
   561				var lat, lng *float64
   562				var rec *time.Time
   563				if wrows.Scan(&id, &uname, &fname, &avail, &cap, &lat, &lng, &rec, &load) != nil {
   564					continue
   565				}
   566				item := map[string]interface{}{
   567					"workerId": id, "username": uname, "fullName": fname,
   568					"available": avail, "capacityUnits": cap, "activeLoad": load,
   569					"locationStale": isStale(rec, now),
   570				}
   571				if lat != nil && lng != nil {
   572					item["latestLocation"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
   573				}
   574				if rec != nil {
   575					item["locationRecordedAt"] = rfc3339(*rec)
   576				}
   577				workers = append(workers, item)
   578			}
   579		}
   580	
   581		locations := []map[string]interface{}{}
   582		locs, _ := app.loadLocations(ctx)
   583		for _, l := range locs {
   584			if u.ActiveRole == RoleNodeHandler || u.ActiveRole == RoleLaboratoryTeam {
   585				if u.AssignedLocationID != l.ID {
   586					continue
   587				}
   588			}
   589			cap := Capacity{
   590				CapacityUnits: l.CapacityUnits, ReservedUnits: l.ReservedUnits,
   591				CooledCapacityUnits: l.CooledCap, CooledReservedUnits: l.CooledReserved,
   592			}.fill()
   593			item := map[string]interface{}{
   594				"id":              l.ID,
   595				"locationId":      l.ID,
   596				"name":            l.Name,
   597				"coordinate":      map[string]interface{}{"latitude": l.Lat, "longitude": l.Lng},
   598				"active":          l.Active,
   599				"coverageKm":      l.CoverageKm,
   600				"handlingMinutes": l.HandlingMinutes,
   601				"functions": LocationFunctions{
   602					CollectionPoint: l.FnCollection, TransferPoint: l.FnTransfer, Hub: l.FnHub, Laboratory: l.FnLaboratory,
   603				},
   604				"capacity":              cap,
   605				"acceptedSampleTypeIds": l.AcceptedTypes,
   606			}
   607			locations = append(locations, item)
   608		}
   609	
   610		routes := []map[string]interface{}{}
   611		conns, _ := app.loadConnections(ctx)
   612		for _, c := range conns {
   613			cap := Capacity{
   614				CapacityUnits: c.CapacityUnits, ReservedUnits: c.ReservedUnits,
   615				CooledCapacityUnits: c.CooledCap, CooledReservedUnits: c.CooledReserved,
   616			}.fill()
   617			routes = append(routes, map[string]interface{}{
   618				"connectionId": c.ID, "fromLocationId": c.FromID, "toLocationId": c.ToID,
   619				"travelMinutes": c.TravelMinutes, "costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active,
   620				"capacity": cap,
   621			})
   622		}
   623	
   624		exceptions := []map[string]interface{}{}
   625		erows, err := app.store.pg.Query(ctx, `SELECT id, sample_id, laboratory_id, reason, observed_at FROM exceptions ORDER BY observed_at DESC LIMIT 200`)
   626		if err == nil {
   627			defer erows.Close()
   628			for erows.Next() {
   629				var id, sid, reason string
   630				var lab *string
   631				var at time.Time
   632				if erows.Scan(&id, &sid, &lab, &reason, &at) != nil {
   633					continue
   634				}
   635				item := map[string]interface{}{"exceptionId": id, "sampleId": sid, "reason": reason, "observedAt": rfc3339(at)}
   636				if lab != nil {
   637					item["laboratoryId"] = *lab
   638				}
   639				exceptions = append(exceptions, item)
   640			}
   641		}
   642	
   643		return map[string]interface{}{
   644			"generatedAt": rfc3339(now),
   645			"samples":     samples,
   646			"workers":     workers,
   647			"locations":   locations,
   648			"routes":      routes,
   649			"exceptions":  exceptions,
   650		}, nil
   651	}
