   832	func (app *App) replanJourney(ctx context.Context, u *SessionUser, journeyID string) (string, string, error) {
   833		sids := app.journeySampleIDs(ctx, journeyID)
   834		if len(sids) == 0 {
   835			return "not_required", "", nil
   836		}
   837		// cancel unfinished assignments, keep completed
   838		_, _ = app.store.pg.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
   839		app.releaseJourneyCapacity(ctx, journeyID)
   840		_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced' WHERE id=$1`, journeyID)
   841	
   842		// replan first unfinished sample (and attach others if possible)
   843		var lastStatus, lastID string
   844		for _, sid := range sids {
   845			s, err := app.loadSample(ctx, sid)
   846			if err != nil || s.Status == "received" || s.Status == "cancelled" {
   847				continue
   848			}
   849			st, _ := app.loadSampleType(ctx, s.SampleTypeID)
   850			plan, err := app.evaluateServiceability(ctx, Coord{s.OriginLat, s.OriginLng}, s.OriginType, "", s.SampleTypeID, time.Now(), s.Deadline, s.Earliest, s.Latest)
   851			if err != nil || !plan.Serviceable {
   852				reason := "no_valid_route"
   853				status := "exception"
   854				if plan != nil && plan.Reason == "deadline_unreachable" {
   855					status = "expired"
   856					reason = "deadline_unreachable"
   857				}
   858				_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET status=$2, exception=$3 WHERE id=$1`, sid, status, asJSON(map[string]interface{}{"reason": reason}))
   859				if status == "expired" {
   860					lastStatus = "expired"
   861				} else {
   862					lastStatus = "exception"
   863				}
   864				continue
   865			}
   866			req := collectionReqBody{
   867				Origin: Coord{s.OriginLat, s.OriginLng}, OriginType: s.OriginType, SampleTypeID: s.SampleTypeID,
   868				ContainerType: s.ContainerType, TemperatureMinC: s.TempMin, TemperatureMaxC: s.TempMax,
   869			}
   870			jid, _, err := app.materializeJourney(ctx, u, sid, req, plan, st, s.Sealed, time.Now())
   871			if err != nil {
   872				lastStatus = "exception"
   873				continue
   874			}
   875			_, _ = app.store.pg.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2 WHERE id=$1`, jid, journeyID)
   876			_, _ = app.store.pg.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE id=$1`, sid, jid, plan.TargetLab)
   877			lastStatus = "replaced"
   878			lastID = jid
   879		}
   880		if lastStatus == "" {
   881			lastStatus = "not_required"
   882		}
   883		return lastStatus, lastID, nil
