  1038				"id": id, "type": typ, "entityType": et, "entityId": eid, "payload": p, "createdAt": rfc3339(created),
  1039			})
  1040			cursor = id
  1041		}
  1042		writeData(w, 200, map[string]interface{}{"events": events, "cursor": cursor})
  1043	}
