  1045	func parseInt64(s string, out *int64) (int, error) {
  1046		var n int64
  1047		for _, c := range s {
  1048			if c < '0' || c > '9' {
  1049				return 0, herr(400, "invalid_json", "invalid since")
  1050			}
  1051			n = n*10 + int64(c-'0')
  1052		}
  1053		*out = n
  1054		return 0, nil
  1055	}

